// 핵심기출 (SQL 자격검정 실전문제 1과목 1~50, 2과목 1~126) · 정답은 답지 기준
window.BANK.push(...[{"id":1653,"c":"c01","d":1,"q":"데이터 모델링의 특징으로 가장 적절하지 않은 것은?","code":null,"o":["현실 세계를 일정한 형식에 맞추어 표현하는 추상화의 의미를 가질 수 있다.","시스템 구현만을 위해 진행하는 사전단계의 작업으로서 데이터베이스 구축을 위한 사전작업의 의미가 있다.","복잡한 현실을 제한된 언어나 표기법으로 이해하기 쉽게 하는 단순화의 의미를 가지고 있다.","모호함을 배제하고 누구나 이해가 가능하도록 정확하게 현상을 기술하는 정확화의 의미를 가진다."],"a":1,"e":"모델링은 시스템 구현만 보고 하는 작업이 아니다. 구현을 포함해 업무를 분석하고 업무 형상을 정리하는 목적도 같이 가진다. '~만을 위해'라는 한정 표현이 함정.","src":"핵심기출 · 1과목 1번","w":["추상화는 모델링 3대 특징(단추명) 중 하나","","단순화도 3대 특징","명확화(정확화)도 3대 특징. 모호함 없이 한 가지로 읽히게 하는 것"],"kc":"1-1"},{"id":1654,"c":"c01","d":2,"q":"데이터 모델링에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["업무 정보를 구성하는 기초가 되는 정보들을 일정한 표기법으로 표현한다.","분석된 모델로 데이터베이스를 생성하여 개발 및 데이터관리에 사용하기 위한 것이다.","데이터베이스를 구축하는 목적으로 데이터 모델링을 수행하며 업무에 대한 설명은 별도의 표기법을 이용한다.","데이터 모델링 자체로서 업무의 흐름을 설명하고 분석하는 부분에 의미를 가지고 있다."],"a":2,"e":"업무 설명을 별도 표기법으로 하는 게 아니라, 데이터 모델 자체가 업무를 설명하고 분석하는 도구 역할을 한다. 그래서 ③이 틀린 설명.","src":"핵심기출 · 1과목 2번","w":["모델링은 업무 정보를 일정한 표기법으로 표현하는 작업이 맞음","분석된 모델로 실제 DB를 만들고 개발·관리에 쓰는 것도 모델링 목적","","모델 자체로 업무 흐름을 설명·분석하는 의미가 있다는 건 맞는 말"],"kc":"1-2"},{"id":1655,"c":"c01","d":2,"q":"데이터 모델링을 할 때 유의해야 할 사항으로 가장 적절하지 않은 것은?","code":null,"o":["여러 장소의 데이터베이스에 같은 정보를 저장하지 않도록 하여 중복성을 최소화한다.","데이터의 정의를 데이터의 사용 프로세스와 분리하여 유연성을 높인다.","사용자가 처리하는 프로세스나 장표 등에 따라 매핑이 될 수 있도록 프로그램과 테이블 간의 연계성을 높인다.","데이터 간의 상호 연관관계를 명확하게 정의하여 일관성 있게 데이터가 유지되도록 한다."],"a":2,"e":"유의사항은 중복·비유연성·비일관성 세 가지. 프로세스나 장표에 맞춰 프로그램과 테이블의 연계성을 높이면 업무가 조금만 바뀌어도 모델을 뜯어고쳐야 한다. 오히려 연계성을 낮춰야 하는 쪽.","src":"핵심기출 · 1과목 3번","w":["중복 최소화는 '중복' 유의사항에 대한 올바른 대응","데이터 정의와 사용 프로세스 분리는 '비유연성' 대응책","","관계를 명확히 정의해 일관성을 지키는 건 '비일관성' 대응책"],"kc":"1-3"},{"id":1656,"c":"c01","d":1,"q":"아래에서 설명하는 데이터 모델링의 유의점은?","code":null,"o":["중복","비유연성","비일관성","일관성"],"a":1,"e":"사소한 업무 변화에도 모델이 자주 바뀌어 유지보수가 어려워지는 문제 = 비유연성. 대응책이 데이터 정의와 사용 프로세스를 분리하는 것이라 지문 뒷부분까지 딱 맞는다.","src":"핵심기출 · 1과목 4번","w":["중복은 같은 정보를 여러 곳에 저장하는 문제","","비일관성은 연관 데이터를 고려하지 않고 일부만 수정해 서로 모순되는 문제","일관성은 유의사항 이름이 아님"],"kc":"1-4","box":["데이터 모델을 어떻게 설계했느냐에 따라 사소한 업무변화에도 데이터 모델이 수시로 변경되어 유지보수의 어려움을 가중시킬 수 있다. 데이터의 정의를 데이터의 사용 프로세스와 분리하여 데이터 모델링은 데이터 혹은 프로세스의 작은 변화가 애플리케이션과 데이터베이스에 중대한 변화를 일으킬 수 있는 가능성을 줄인다."]},{"id":1657,"c":"c03","d":2,"q":"데이터 독립성의 구성요소에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["통합된 모든 사용자의 관점은 개념스키마와 관련이 있다.","물리적인 저장구조를 표현하는 스키마는 내부스키마이다.","View 단계는 여러 사용자 관점으로 구성하는 개념스키마에 해당한다.","논리적인 데이터 독립성을 고려하는 단계는 외부단계와 개념적 단계이다."],"a":2,"e":"View 단계, 즉 여러 사용자 관점으로 구성되는 건 외부스키마다. 개념스키마는 모든 사용자 관점을 통합한 조직 전체 관점.","src":"핵심기출 · 1과목 5번","w":["개념스키마 = 통합된 전체 사용자 관점, 맞는 설명","물리적 저장구조 = 내부스키마, 맞는 설명","","논리적 독립성은 외부-개념 사이, 맞는 설명"],"kc":"1-5"},{"id":1658,"c":"c03","d":1,"q":"아래에서 설명하는 스키마 구조로 가장 적절한 것은?","code":null,"o":["외부스키마(External Schema)","개념스키마(Conceptual Schema)","내부스키마(Internal Schema)","논리스키마(Logical Schema)"],"a":1,"e":"모든 사용자 관점을 통합한 조직 전체의 DB 구조, 저장 데이터와 그 관계를 표현 → 개념스키마. 모델링은 결국 이 개념스키마를 만들어 가는 과정이다.","src":"핵심기출 · 1과목 6번","w":["외부스키마는 사용자·응용 프로그램별 관점(View)","","내부스키마는 물리적 저장 구조","논리스키마는 3단계 스키마 구조의 공식 단계명이 아님"],"kc":"1-6","box":["- 모든 사용자 관점을 통합한 조직 전체 관점의 통합적 표현","- 모든 응용시스템들이나 사용자들이 필요로 하는 데이터를 통합한 조직 전체의 DB를 기술한 것으로 DB에 저장되는 데이터와 그들 간의 관계를 표현하는 스키마"]},{"id":1659,"c":"c16","d":2,"q":"아래 ERD에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["한 명의 고객은 여러 개의 제품을 주문할 수 있다.","하나의 주문은 반드시 한 명의 고객에 의해 주문된다.","하나의 고객은 주문을 할 수도 있고 안 할 수도 있다.","하나의 주문은 고객이 있을 수도 있고 없을 수도 있다."],"a":3,"e":"고객 쪽 관계선 끝이 '|'(필수)라 주문은 반드시 고객이 있어야 한다. 주문 쪽은 '○<'(선택·다수)라 고객은 주문이 없어도 되고 여러 건도 가능. 주문에 고객이 없을 수 있다는 ④가 틀렸다.","src":"핵심기출 · 1과목 7번","w":["주문 쪽이 까마귀발(다수)이라 한 고객이 여러 주문(제품) 가능","고객 쪽이 필수(|)라 맞는 설명","주문 쪽에 ○(선택)가 있어 맞는 설명",""],"kc":"1-7","img":"data/kc/1-7.jpg"},{"id":1660,"c":"c02","d":1,"q":"ERD에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["1976년 피터 첸(Peter Chen)에 의해 Entity-Relationship Model(E-R Model)이라는 표기법이 만들어졌다.","일반적으로 ERD를 작성할 때 엔터티 도출 → 엔터티 배치 → 관계 설정 → 관계명 기술의 흐름으로 작업을 진행한다.","관계의 명칭은 관계 표현에서 매우 중요한 부분에 해당한다.","가장 중요한 엔터티를 오른쪽 상단에 배치하고 추가로 발생되는 엔터티들을 왼쪽 편과 하단에 배치하는 것이 원칙이다."],"a":3,"e":"가장 중요한 엔터티는 왼쪽 상단에 둔다. 사람 시선이 왼쪽→오른쪽, 위→아래로 흐르기 때문. 오른쪽 상단이라고 바꿔 놓은 게 함정.","src":"핵심기출 · 1과목 8번","w":["ERD는 1976년 피터 첸이 만든 표기법이 맞음","작성 순서 엔터티 도출→배치→관계 설정→관계명 기술, 맞음","관계명은 관계 표현에서 중요한 요소가 맞음",""],"kc":"1-8"},{"id":1661,"c":"c04","d":1,"q":"아래 시나리오에서 엔터티로 가장 적절한 것은?","code":null,"o":["병원","환자","이름","주소"],"a":1,"e":"엔터티는 두 개 이상의 인스턴스와 두 개 이상의 속성을 가져야 한다. 병원은 S병원 하나뿐이라 안 되고, 이름·주소는 환자의 속성. 여러 명이 있고 이름·주소를 가진 환자가 엔터티.","src":"핵심기출 · 1과목 9번","w":["S병원 1개뿐이라 인스턴스가 하나 → 엔터티 불가","","이름은 환자를 설명하는 속성","주소도 환자의 속성"],"kc":"1-9","box":["S병원은 여러 명의 환자가 존재하고 각 환자의 이름, 주소 등을 관리해야 한다.","(단, 업무범위와 데이터의 특성은 위 시나리오에 기술되어 있는 사항만을 근거하여 판단해야 함)"]},{"id":1662,"c":"c04","d":2,"q":"엔터티의 특징으로 가장 적절하지 않은 것은?","code":null,"o":["속성이 없는 엔터티는 있을 수 없다. 엔터티는 반드시 속성을 가져야 한다.","엔터티는 다른 엔터티와 관계가 있어야 한다. 단, 통계성 엔터티나, 코드성 엔터티의 경우 관계를 생략할 수 있다.","객체 지향의 디자인 패턴에는 싱글턴패턴이 있어 하나의 인스턴스를 가지는 클래스가 존재한다. 이와 유사하게 엔터티는 한 개의 인스턴스를 가지는 것만으로도 충분한 의미를 부여할 수 있다.","데이터로서 존재하지만 업무에서 필요로 하지 않으면 해당 업무의 엔터티로 성립될 수 없다."],"a":2,"e":"엔터티는 영속적으로 존재하는 두 개 이상의 인스턴스 집합이어야 한다. 싱글턴 패턴처럼 인스턴스 하나로 충분하다는 ③은 엔터티 특징과 정면으로 어긋난다.","src":"핵심기출 · 1과목 10번","w":["엔터티는 반드시 속성을 가져야 함, 맞는 설명","관계 필수 + 통계성·코드성은 관계 생략 가능, 맞는 설명","","업무에서 필요하지 않으면 엔터티가 아님, 맞는 설명"],"kc":"1-10"},{"id":1663,"c":"c04","d":1,"q":"엔터티의 일반적인 특징으로 가장 적절하지 않은 것은?","code":null,"o":["다른 엔터티와의 관계를 가지지 않는다.","유일한 식별자에 의해 식별이 가능해야 한다.","엔터티는 업무 프로세스에 의해 이용되어야 한다.","엔터티는 반드시 속성을 포함해야 한다."],"a":0,"e":"엔터티는 다른 엔터티와 최소 한 개 이상의 관계를 가져야 한다. 관계를 생략할 수 있는 건 공통코드·통계성 같은 예외일 뿐이다.","src":"핵심기출 · 1과목 11번","w":["","유일한 식별자로 식별 가능해야 함, 맞는 특징","업무 프로세스에 의해 이용되어야 함, 맞는 특징","반드시 속성을 포함해야 함, 맞는 특징"],"kc":"1-11"},{"id":1664,"c":"c04","d":1,"q":"발생 시점에 따라 구분할 수 있는 엔터티의 유형으로 적절하지 않은 것은?","code":null,"o":["관계 엔터티(Relation Entity)","행위 엔터티(Active Entity)","중심 엔터티(Main Entity)","기본 엔터티(Fundamental Entity)"],"a":0,"e":"발생 시점 분류는 기본(키)·중심·행위 세 가지. 관계 엔터티는 이 분류에 없다.","src":"핵심기출 · 1과목 12번","w":["","행위 엔터티는 발생 시점 분류에 포함","중심 엔터티도 포함","기본 엔터티도 포함"],"kc":"1-12"},{"id":1665,"c":"c04","d":1,"q":"엔터티에 이름을 부여하는 방법으로 가장 적절하지 않은 것은?","code":null,"o":["가능하면 약어를 사용하여 엔터티의 이름을 간결하고 명확하게 한다.","현업의 업무 용어를 사용하여 업무상의 의미를 분명하게 한다.","모든 엔터티에서 유일한 이름이 부여되어야 한다.","엔터티가 생성되는 의미대로 자연스럽게 부여하도록 한다."],"a":0,"e":"엔터티명은 현업 용어를 쓰고, 약어는 가능하면 쓰지 않는다. 단수명사, 전체에서 유일한 이름, 생성 의미대로 부여하는 게 원칙.","src":"핵심기출 · 1과목 13번","w":["","현업 업무 용어 사용, 맞는 원칙","모든 엔터티에서 유일한 이름, 맞는 원칙","생성되는 의미대로 부여, 맞는 원칙"],"kc":"1-13"},{"id":1666,"c":"c05","d":1,"q":"업무에서 필요로 하는 인스턴스에서 관리하고자 하는 의미상 더 이상 분리되지 않는 최소의 데이터 단위는?","code":null,"o":["도메인","속성","엔터티","관계"],"a":1,"e":"업무에서 관리하고자 하는, 의미상 더 이상 쪼개지지 않는 최소 데이터 단위 = 속성의 정의 그대로다.","src":"핵심기출 · 1과목 14번","w":["도메인은 속성이 가질 수 있는 값의 범위","","엔터티는 속성들을 묶은 인스턴스 집합","관계는 엔터티 간 연관"],"kc":"1-14"},{"id":1667,"c":"c05","d":2,"q":"속성에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["엔터티에 대한 자세하고 구체적인 정보를 나타낸다.","하나의 엔터티는 두 개 이상의 속성을 갖는다.","하나의 인스턴스에서 각각의 속성은 하나 이상의 속성값을 가질 수 있다.","속성도 집합이다."],"a":2,"e":"한 인스턴스에서 각 속성은 속성값을 딱 하나만 가진다. 하나 이상 가질 수 있다면 1정규형부터 깨진다.","src":"핵심기출 · 1과목 15번","w":["속성은 엔터티를 구체적으로 설명하는 정보, 맞음","한 엔터티는 두 개 이상 속성, 맞음","","속성도 같은 성격 값들의 집합으로 볼 수 있음, 맞음"],"kc":"1-15"},{"id":1668,"c":"c10","d":3,"q":"아래에서 수행한 정규화 작업으로 가장 적절한 것은? (단, 이후 필요한 정규화 작업은 계속 수행될 예정)","code":null,"o":["1차 정규화","2차 정규화","3차 정규화","4차 정규화"],"a":1,"e":"변경 전 주문상품의 PK는 (주문번호, 주문상품코드)인데 상품명·가격은 주문상품코드에만 종속된다(부분 함수 종속). 그래서 상품 엔터티로 떼어낸 것 → 2차 정규화.","src":"핵심기출 · 1과목 16번","w":["1차 정규화는 반복 속성·다중값 제거","","3차 정규화는 일반속성끼리의 이행 종속 제거","4차 정규화는 다치 종속 제거"],"kc":"1-16","img":"data/kc/1-16.jpg"},{"id":1669,"c":"c05","d":1,"q":"데이터를 조회할 때 빠른 성능을 낼 수 있도록 하기 위해 원래 속성값을 계산하여 저장할 수 있도록 만든 속성은?","code":null,"o":["파생 속성(Derived Attribute)","기본 속성(Basic Attribute)","설계 속성(Designed Attribute)","PK 속성(PK Attribute)"],"a":0,"e":"원래 값으로 계산해서 저장해 두는 속성 = 파생 속성. 조회 성능은 좋아지지만 원본이 바뀔 때 같이 맞춰 줘야 해서 가급적 적게 쓰는 게 좋다.","src":"핵심기출 · 1과목 17번","w":["","기본 속성은 업무에서 바로 도출된 속성","설계 속성은 업무에 없던 걸 설계하며 만든 속성(코드 등)","PK 속성은 속성 특성 분류명이 아님"],"kc":"1-17"},{"id":1670,"c":"c05","d":1,"q":"아래 설명이 나타내는 데이터 모델의 개념으로 가장 적절한 것은?","code":null,"o":["시스템 카탈로그(System Catalog)","용어 사전(Word Dictionary)","속성 사전(Attribute Dictionary)","도메인(Domain)"],"a":3,"e":"속성값의 범위, 데이터 타입과 크기, 제약사항을 정하는 개념 = 도메인.","src":"핵심기출 · 1과목 18번","w":["시스템 카탈로그는 DBMS가 관리하는 메타데이터 저장소","용어 사전은 표준 용어를 정리한 것","속성 사전은 속성 목록 정의",""],"kc":"1-18","box":["주문이라는 엔터티가 있을 때 단가라는 속성값의 범위는 100에서 10,000 사이의 실수 값이며 제품명이라는 속성은 길이가 20자리 이내의 문자열로 정의할 수 있다."]},{"id":1671,"c":"c05","d":2,"q":"데이터 모델링을 할 때 속성의 명칭을 부여하는 방법으로 가장 적절하지 않은 것은?","code":null,"o":["속성의 이름에 약어를 사용할 경우 그 의미를 명확하게 이해할 수 없고 혼돈을 초래하여 커뮤니케이션의 혼란을 야기할 수 있으므로 지나친 약어 사용은 가급적 제한하도록 한다.","속성의 이름에는 서술식 용어는 사용하지 않도록 한다.","직원 엔터티의 이름, 고객 엔터티의 이름과 같이 엔터티별로 동일한 속성명을 사용하여 데이터 모델의 일관성을 유지하는 것이 좋다.","데이터 모델링 대상에서 사용하는 용어도 있고 외부에서 사용하는 용어도 있어 중복이 있을 때, 가급적 해당 업무에서 자주 사용하는 이름을 이용하도록 한다."],"a":2,"e":"속성명은 전체 데이터 모델에서 유일하게 짓는 게 좋다. '이름'처럼 엔터티마다 같은 이름을 쓰면 반정규화·통합할 때 헷갈린다. 직원명, 고객명처럼 구분해서 짓는다.","src":"핵심기출 · 1과목 19번","w":["약어 남용 금지, 맞는 원칙","서술식 속성명 지양, 맞는 원칙","","현업에서 자주 쓰는 이름 사용, 맞는 원칙"],"kc":"1-19"},{"id":1672,"c":"c06","d":3,"q":"데이터 모델링의 관계에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["관계는 존재에 의한 관계와 행위에 의한 관계로 구분될 수 있으나 ERD에서는 관계를 연결할 때, 존재와 행위를 구분하지 않고 단일화된 표기법을 사용한다.","UML(Unified Modeling Language)에는 클래스다이어그램의 관계 중 연관관계(Association)와 의존관계(Dependency)가 있고 이것은 실선과 점선으로 다르게 표현이 된다.","연관관계는 항상 이용하는 관계로 존재적 관계에 해당하고, 의존관계는 상대방 클래스의 행위에 의해 관계가 형성되는 행위적 관계에 해당한다.","연관관계는 오퍼레이션에서 파라미터 등으로 이용할 수 있고, 의존관계는 소스코드에서 멤버변수로 선언하여 사용할 수 있다."],"a":3,"e":"연관관계는 소스코드에서 멤버변수로 선언해서 쓰고, 의존관계는 오퍼레이션의 파라미터 등으로 이용한다. ④는 두 개를 바꿔 놓았다.","src":"핵심기출 · 1과목 20번","w":["ERD는 존재·행위 관계를 구분 없이 같은 표기법 사용, 맞음","UML 연관관계 실선, 의존관계 점선, 맞음","연관=존재적, 의존=행위적, 맞음",""],"kc":"1-20"},{"id":1673,"c":"c06","d":2,"q":"데이터 모델링의 관계에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["관계는 존재적 관계와 행위에 의한 관계로 나누어볼 수 있다.","관계의 표기법은 관계명, 관계차수, 식별성의 3가지 개념을 사용한다.","부서와 사원 엔터티 간의 '소속' 관계는 존재적 관계의 사례이다.","주문과 배송 엔터티 간의 '배송근거' 관계는 행위에 의한 관계의 사례이다."],"a":1,"e":"관계 표기법은 관계명·관계차수·관계선택사양(선택성) 세 가지다. 식별성은 표기법 구성요소가 아니다.","src":"핵심기출 · 1과목 21번","w":["존재적 관계·행위 관계 구분, 맞음","","부서-사원 소속은 존재 관계의 대표 예","주문-배송은 행위 관계 예"],"kc":"1-21"},{"id":1674,"c":"c03","d":1,"q":"아래에서 설명하는 데이터 독립성은?","code":null,"o":["논리적 독립성","물리적 독립성","개념적 독립성","내부적 독립성"],"a":1,"e":"파일 구조·색인 구조가 바뀌어도 논리 스키마나 응용 프로그램에 영향이 없다 = 물리적 독립성(내부-개념 사이).","src":"핵심기출 · 1과목 22번","w":["논리적 독립성은 개념 스키마 변경이 외부 스키마에 영향 없는 것","","개념적 독립성이라는 용어는 쓰지 않음","내부적 독립성도 공식 용어 아님"],"kc":"1-22","box":["- 데이터베이스의 파일 구조의 변화가 논리스키마(Schema)에 영향을 주지 않음","- 데이터베이스의 색인 구조의 변화가 응용 프로그램에 영향을 주지 않음"]},{"id":1675,"c":"c06","d":1,"q":"1:1, 1:M과 같이 두 엔터티 간의 관계에서 참여자의 수를 나타내는 것은?","code":null,"o":["관계명(Relationship Membership)","관계차수(Relationship Degree/Cardinality)","관계선택사양(Relationship Optionality)","관계정의(Relationship Definition)"],"a":1,"e":"1:1, 1:M처럼 관계에 참여하는 수를 나타내는 건 관계차수(Cardinality).","src":"핵심기출 · 1과목 23번","w":["관계명은 관계의 이름","","선택사양은 필수/선택 여부","관계정의는 표기법 구성요소가 아님"],"kc":"1-23"},{"id":1676,"c":"c06","d":2,"q":"두 개의 엔터티 사이에 정의한 관계에 대해 확인해야 할 사항으로 가장 적절하지 않은 것은?","code":null,"o":["두 개의 엔터티 사이에 관심 있는 연관규칙이 존재하는가?","두 개의 엔터티 사이에 정보의 조합이 발생되는가?","업무기술서, 장표에 관계연결을 가능하게 하는 명사(Noun)가 있는가?","업무기술서, 장표에 관계연결에 대한 규칙이 서술되어 있는가?"],"a":2,"e":"관계 연결을 가능하게 하는 건 명사가 아니라 동사(Verb)다. 업무기술서에서 동사를 찾아야 관계가 보인다.","src":"핵심기출 · 1과목 24번","w":["연관규칙 존재 여부, 맞는 확인 사항","정보의 조합 발생 여부, 맞는 확인 사항","","관계연결 규칙 서술 여부, 맞는 확인 사항"],"kc":"1-24"},{"id":1677,"c":"c06","d":2,"q":"두 개의 엔터티 사이에서 관계를 도출할 때 확인해야 할 사항을 모두 고른 것은?","code":null,"o":["(가), (나), (다)","(가), (나), (라)","(가), (다), (라)","(가), (나), (다), (라)"],"a":3,"e":"관계 도출 시 확인 사항은 연관규칙·정보의 조합·규칙 서술·동사 네 가지 전부다.","src":"핵심기출 · 1과목 25번","w":["(라) 동사(Verb) 항목도 확인해야 함","(다) 규칙 서술 항목 빠짐","(나) 정보 조합 항목 빠짐",""],"kc":"1-25","box":["(가) 두 개의 엔터티 사이에 관심 있는 연관규칙이 존재하는가?","(나) 두 개의 엔터티 사이에 정보의 조합이 발생되는가?","(다) 업무기술서, 장표에 관계연결에 대한 규칙이 서술되어 있는가?","(라) 업무기술서, 장표에 관계연결을 가능하게 하는 동사(Verb)가 있는가?"]},{"id":1678,"c":"c07","d":2,"q":"주식별자를 지정할 때 고려해야 할 사항을 모두 고른 것은?","code":null,"o":["(가), (나), (다)","(가), (나), (라)","(나), (다), (라)","(가), (나), (다), (라)"],"a":3,"e":"주식별자 지정 시 유일성·최소성·불변성·존재성 네 가지를 모두 따진다. (가)유일성 (나)최소성 (다)불변성 (라)존재성.","src":"핵심기출 · 1과목 26번","w":["(라) 존재성도 고려 대상","(다) 불변성도 고려 대상","(가) 유일성이 빠짐",""],"kc":"1-26","box":["(가) 주식별자에 의해 엔터티 내의 모든 인스턴스들이 유일하게 구분되어야 한다.","(나) 주식별자를 구성하는 속성의 수는 유일성을 만족하는 최소의 수가 되어야 한다.","(다) 지정된 주식별자의 값은 자주 변하지 않는 것이어야 한다.","(라) 주식별자가 지정이 되면 반드시 값이 들어와야 한다."]},{"id":1679,"c":"c07","d":3,"q":"아래에서 사원 엔터티의 특성에 해당하지 않는 것은?","code":null,"o":["주식별자","단일식별자","내부식별자","인조식별자"],"a":3,"e":"사번은 사원이 생길 때 업무적으로 부여되는 값이라 본질식별자로 본다. 단일 속성이고, 스스로 생성된 내부식별자이며, 대표 식별자(주식별자)도 맞다. 인조식별자는 아니다.","src":"핵심기출 · 1과목 27번","w":["사번이 사원의 대표 식별자라 주식별자 맞음","속성 하나로 식별하니 단일식별자 맞음","다른 엔터티에서 받은 게 아니라 내부식별자 맞음",""],"kc":"1-27","imgAlt":"부서(부서번호 / 부서명, 위치) ┼- - - - -○< 사원(사번 / 부서번호(FK), 주민등록번호) — 비식별 관계(점선)","img":"data/kc/1-27.jpg"},{"id":1680,"c":"c07","d":2,"q":"식별자로 가장 적절하지 않은 것은?","code":null,"o":["사원 ─ 식별자: 사원번호 NUMBER(10) / 속성: 주민등록번호 NUMBER(13)","사원 ─ 식별자: 이름 VARCHAR2(20) / 속성: 사원번호 NUMBER(10)","사원 ─ 식별자: 주민번호 NUMBER(13) / 속성: 사원번호 NUMBER(10)","사원 ─ 식별자: 일련번호 VARCHAR2(10) / 속성: 주민등록번호 CHAR(18), 사원번호 NUMBER(10)"],"a":1,"e":"이름은 동명이인이 생길 수 있어 유일성을 보장 못 한다. 명칭·내역처럼 이름으로 기술되는 값은 주식별자로 부적절.","src":"핵심기출 · 1과목 28번","w":["사원번호로 식별, 적절","","주민번호 역시 유일하게 식별 가능","인조식별자인 일련번호도 식별자로 쓸 수 있음"],"kc":"1-28","imgAlt":"각 보기는 사원 엔터티. 가로선 위가 식별자, 아래가 일반 속성","img":"data/kc/1-28.jpg"},{"id":1681,"c":"c07","d":1,"q":"주식별자의 특징과 그에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["유일성: 주식별자에 의해 엔터티 내의 모든 인스턴스들은 유일하게 구분된다.","존재성: 주식별자는 데이터 값이 없을 수 있다. (NULL 존재 가능)","불변성: 주식별자가 한번 특정 엔터티에 지정되면 그 식별자의 값은 변하지 않아야 한다.","최소성: 주식별자를 구성하는 속성의 수는 유일성을 만족하는 최소의 수가 되어야 한다."],"a":1,"e":"존재성은 주식별자가 지정되면 반드시 값이 있어야 한다는 뜻. NULL 허용이라고 바꿔 놓은 ②가 틀림.","src":"핵심기출 · 1과목 29번","w":["유일성 설명 맞음","","불변성 설명 맞음","최소성 설명 맞음"],"kc":"1-29"},{"id":1682,"c":"c08","d":3,"q":"데이터 모델링에서 비식별자 관계로 연결하는 경우로 가장 적절하지 않은 것은?","code":null,"o":["엔터티와 엔터티가 1:M 관계의 부모와 자식관계에서 데이터가 부모 없이 자식쪽 엔터티의 인스턴스가 먼저 생성될 수 있을 경우 비식별자 관계로 연결해야 한다.","부모 엔터티의 인스턴스가 자식 엔터티의 인스턴스보다 먼저 소멸하는 경우 비식별자 관계로 연결해야 한다.","SQL 문의 조인 관계를 최소화 하는 경우 비식별자 관계로 연결해야 한다.","자식 엔터티의 식별자가 부모 엔터티의 주식별자를 상속받아 생성하는 것보다 별도의 주식별자를 생성하는 것이 더 유리하다고 판단되는 경우 비식별자 관계로 연결해야 한다."],"a":2,"e":"SQL 조인을 줄이고 싶다면 식별자 관계로 연결해야 한다. 부모 식별자가 자식 PK까지 내려가 있으면 중간 테이블을 거치지 않고 바로 조건을 걸 수 있기 때문.","src":"핵심기출 · 1과목 30번","w":["부모 없이 자식이 먼저 생길 수 있으면 비식별 관계, 맞음","부모가 먼저 소멸할 수 있으면 비식별 관계, 맞음","","자식 PK를 독립적으로 두는 게 유리하면 비식별 관계, 맞음"],"kc":"1-30"},{"id":1683,"c":"c07","d":3,"q":"아래 식별자에 대한 설명이 올바르게 짝지어진 것은?","code":null,"o":["(가) 보조식별자 (나) 실질식별자 (다) 인조식별자 (라) 복합식별자","(가) 보조식별자 (나) 인조식별자 (다) 본질식별자 (라) 복합식별자","(가) 주식별자 (나) 보조식별자 (다) 본질식별자 (라) 외부식별자","(가) 주식별자 (나) 보조식별자 (다) 인조식별자 (라) 외부식별자"],"a":2,"e":"(가) 대표성 있음 = 주식별자, (나) 유일하지만 대표성 없음 = 보조식별자, (다) 업무적 의미 = 본질식별자, (라) 다른 엔터티에서 상속 = 외부식별자.","src":"핵심기출 · 1과목 31번","w":["(가)는 대표성이 있으니 주식별자","(가)·(나) 자리가 틀림","","(다)는 업무적 의미가 있으니 인조가 아니라 본질식별자"],"kc":"1-31","box":["(가) 대표성을 가지며, 엔터티 내의 여러 인스턴스 중 하나를 유일하게 구분할 수 있는 식별자","(나) 엔터티 내의 여러 인스턴스 중 하나를 유일하게 구분할 수 있으나, 대표성을 가지지 못하는 식별자","(다) 엔터티 내의 집합을 명확하게 설명할 수 있는 업무적으로 의미가 부여된 식별자","(라) 다른 엔터티로부터 상속되어 정의된 식별자"]},{"id":1684,"c":"c05","d":1,"q":"속성이 가질 수 있는 값의 범위를 지칭하는 용어는?","code":null,"o":["제약 사항","도메인","데이터 타입","데이터 크기"],"a":1,"e":"속성이 가질 수 있는 값의 범위 = 도메인. 데이터 타입·크기·제약사항을 지정한다.","src":"핵심기출 · 1과목 32번","w":["제약 사항은 도메인을 구성하는 일부","","데이터 타입도 도메인 안에 포함되는 요소","데이터 크기도 도메인의 일부"],"kc":"1-32"},{"id":1685,"c":"c05","d":1,"q":"아래 빈칸 ㉠, ㉡, ㉢에 해당하는 것은?","code":null,"o":["㉠ 기본 속성  ㉡ 설계 속성  ㉢ 파생 속성","㉠ 기본 속성  ㉡ 일반 속성  ㉢ 설계 속성","㉠ 일반 속성  ㉡ 기본 속성  ㉢ 파생 속성","㉠ 일반 속성  ㉡ 설계 속성  ㉢ 파생 속성"],"a":0,"e":"업무분석으로 바로 정의한 속성 = 기본 속성, 설계하며 새로 만든 속성 = 설계 속성, 계산·변형해서 만든 속성 = 파생 속성. 일반 속성은 구성 방식에 따른 분류(PK·FK 아닌 속성)라 다른 축이다.","src":"핵심기출 · 1과목 33번","w":["","㉡은 설계 속성, ㉢은 파생 속성","㉠은 기본 속성(일반 속성은 다른 분류 기준)","㉠ 자리에 일반 속성은 맞지 않음"],"kc":"1-33","box":["업무분석을 통해 바로 정의한 속성을 ( ㉠ ), 원래 업무상 존재하지는 않지만 설계를 하면서 도출해 내는 속성을 ( ㉡ ), 다른 속성으로부터 계산이나 변형이 되어 생성되는 속성을 ( ㉢ )이라고 한다."]},{"id":1686,"c":"c10","d":4,"q":"속성 a, b, c, d, e로 구성된 릴레이션에서 아래와 같은 함수 종속성(Functional Dependency)이 존재할 때, 이 릴레이션의 후보 키로 가장 적절하지 않은 것은?","code":null,"o":["d","ab","ac","ae"],"a":2,"e":"후보키는 모든 속성을 결정해야 한다. ab→cde라 ab는 후보키. d→ab→cde라 d도 후보키. e→b이므로 ae→ab→cde라 ae도 후보키. ac는 a도 c도 왼쪽에 오는 함수 종속이 없어서 b, d, e를 결정하지 못한다.","src":"핵심기출 · 1과목 34번","w":["d→ab→cde로 전체 결정, 후보키 맞음","ab→cde로 전체 결정, 후보키 맞음","","e→b 때문에 ae→ab→cde, 후보키 맞음"],"kc":"1-34","box":["ab → cde, e → b, d → ab"]},{"id":1687,"c":"c10","d":2,"q":"아래 주문상세 엔터티의 주식별자가 (주문번호, 상품번호)일 때, 이 엔터티가 만족하지 않는 정규형은?","code":null,"o":["제1정규형","제2정규형","제3정규형","제4정규형"],"a":1,"e":"PK가 (주문번호, 상품번호)인데 상품명은 상품번호만으로 결정된다. 부분 함수 종속이라 제2정규형을 만족하지 않는다.","src":"핵심기출 · 1과목 35번","w":["값이 모두 원자값이라 1NF는 만족","","3NF 이전에 2NF부터 깨져 있음","4NF는 2NF를 만족한 다음 단계 이야기"],"kc":"1-35","tables":[{"name":"주문상세","cols":["주문번호","상품번호","상품명"],"rows":[["10001","901","DB 전문가 가이드"],["10001","876","딥러닝 전문가 가이드"],["10002","901","DB 전문가 가이드"],["10003","901","DB 전문가 가이드"],["10004","876","딥러닝 전문가 가이드"]]}]},{"id":1688,"c":"c10","d":3,"q":"아래 엔터티에 필요한 정규화와 분리된 스키마 구조로 가장 적절한 것은?","code":null,"o":["2차 정규화 - 정규화테이블(__관서번호__, __납부자번호__, 관리점번호, 관서명, 상태, 관서등록일자)","3차 정규화 - 정규화테이블(__관서번호__, __납부자번호__, 관리점번호, 관서명, 상태, 관서등록일자)","2차 정규화 - 정규화테이블(__관서번호__, 관리점번호, 관서명, 상태, 관서등록일자)","3차 정규화 - 정규화테이블(__관서번호__, 관리점번호, 관서명, 상태, 관서등록일자)"],"a":2,"e":"관서번호 하나로 관리점번호·관서명·상태·관서등록일자가 결정된다. PK 일부에 종속된 부분 종속이므로 2차 정규화로 관서번호를 PK로 하는 테이블을 따로 분리한다.","src":"핵심기출 · 1과목 36번","w":["분리할 테이블의 PK는 관서번호 하나여야 함","부분 종속 제거는 3차가 아니라 2차, PK도 틀림","","부분 종속 제거는 3차가 아니라 2차 정규화"],"kc":"1-36","box":["[보관금원장]","식별자: 관서번호, 납부자번호","일반속성: 관리점번호, 관서명, 상태, 관서등록일자, 직급명, 통신번호","","함수종속성(FD):","{관서번호, 납부자번호} → {직급명, 통신번호}","{관서번호} → {관리점번호, 관서명, 상태, 관서등록일자}"],"note":"__밑줄__ = 원본의 밑줄(식별자)"},{"id":1689,"c":"c10","d":2,"q":"정규화와 성능에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["정규화를 수행하면 중복 속성을 제거하여 용량을 최소화시킬 수 있다.","일반적으로 정규화 수행 시 데이터 처리 성능이 향상된다.","반정규화가 조회 성능을 항상 향상시키는 것은 아니며, 때로는 정규화에 의해 성능이 향상될 수도 있다.","정규화를 수행하면 조회 성능을 보장받을 수 있다."],"a":3,"e":"정규화하면 테이블이 쪼개져 조인이 늘어나므로 조회 성능이 떨어질 수 있다. 그래서 반정규화를 검토하는 것. '조회 성능을 보장'은 틀렸다.","src":"핵심기출 · 1과목 37번","w":["중복 속성 제거로 용량 최소화, 맞음","입력·수정·삭제 등 처리 성능은 일반적으로 향상, 맞음","반정규화가 항상 조회 성능을 높이는 건 아님, 맞음",""],"kc":"1-37"},{"id":1690,"c":"c10","d":3,"q":"아래와 같이 전제조건이 있을 때 테이블에서 나타날 수 있는 현상으로 가장 적절한 것은?","code":null,"o":["조회 조건이 유형기능분류코드에 따라 반복되는 그룹이 칼럼단위로 되어 있으므로 제1정규형이라고 할 수 있다.","유형기능분류코드에 대해 where절에 조건으로 들어오는 값이 있으므로 PK와 이에 대한 인덱스만 있으면 SQL 문장은 빠르게 수행될 수 있다고 할 수 있다.","유형기능분류코드가 일반속성 안에서 반복적으로 속성이 구분되어 있기 때문에 이전종속을 수행해야 하는 제2정규형이라 할 수 있다.","조회 성능을 위해 유형기능분류코드 각각에 대하여 개별로 인덱스를 모두 생성할 경우 입력, 수정, 삭제 때 성능이 저하되므로 제1차 정규화를 수행한 후 인덱스를 적용하는 것이 좋다."],"a":3,"e":"유형기능분류코드1~9처럼 같은 성격 컬럼이 반복되면 1차 정규화 대상이다. 조건이 OR로 엮이면 인덱스 하나만 없어도 풀스캔이 나고, 9개 컬럼마다 인덱스를 만들면 DML이 느려진다. 그래서 1차 정규화 후 인덱스를 거는 게 답.","src":"핵심기출 · 1과목 38번","w":["컬럼 단위 반복 그룹이 있으니 1NF를 만족한 게 아니라 1NF 위반","OR 조건 + 인덱스 누락 시 풀스캔, PK 인덱스만으로 빨라지지 않음","반복 속성은 2NF가 아니라 1NF 문제",""],"kc":"1-38","box":["전제조건: 유형기능분류코드에 해당하는 속성들은 분포도가 양호하며, SQL Where절에서 각각의 값이 상수 값으로 조건 입력될 수 있는 특징을 가진다."],"imgAlt":"모델(모델코드 / 모델명, 제품류코드, 물품가, 출하가, A유형기능분류코드1 ~ I유형기능분류코드9, 바코드, 가로, 세로, 높이, 모델구분, ...)","img":"data/kc/1-38.jpg"},{"id":1691,"c":"c10","d":4,"q":"아래 논리 데이터 모델을 3차 정규화까지 수행했을 때 도출되는 엔터티 수로 가장 적절한 것은? (단, 하나의 대출자에 대해 하나의 대출번호로 여러 개의 도서 대출/반납을 관리한다고 가정하고, 엔터티 통합은 고려하지 않음)","code":null,"o":["5","6","7","8"],"a":2,"e":"3차 정규화까지 하면 학과, 학생, 교수, LAB실이용신청, 대출, 대출도서, 도서 이렇게 7개가 나온다. 학생에서 학과(이행종속)와 반복되는 LAB실 이용(1NF)·승인교수(이행종속)가, 도서대출에서 대출도서(반복)와 도서 정보(부분종속)가 떨어져 나가는 구조.","src":"핵심기출 · 1과목 39번","w":["학과·교수 분리를 빠뜨린 수","도서 또는 대출도서 분리를 빠뜨린 수","","학생 엔터티를 하나 더 쪼개는 등 필요 이상으로 분리한 수"],"kc":"1-39","imgAlt":"학생(# 학번 / * 성명, * 학과번호, * 학과명, o LAB실이용신청일1, o LAB실이용시작일1, o LAB실이용만기일1, o LAB실이용승인교수번호1, o LAB실이용승인교수명1, ... 같은 묶음이 4까지 반복) ┄대출자로┄ 도서대출(# 대출번호 / * 대출자번호(FK), * 대출자명, * 대출자신분구분(학생,교수), * 대출일자, * 대출도서번호, * 대출도서명, o 출판사명, o 출판년월, o 대표저자명, o ISBN, o 반납일자)","img":"data/kc/1-39.jpg"},{"id":1692,"c":"c10","d":2,"q":"아래에서 빈칸 ㉠, ㉡에 들어갈 용어로 가장 적절한 것은?","code":null,"o":["㉠ 제1정규형  ㉡ 제2정규형","㉠ 제1정규형  ㉡ 제3정규형","㉠ 제2정규형  ㉡ 제3정규형","㉠ 제3정규형  ㉡ 제2정규형"],"a":2,"e":"제2정규형이면서 PK가 아닌 속성이 PK에 이행적으로 종속되지 않으면 제3정규형이다.","src":"핵심기출 · 1과목 40번","w":["1NF에서 바로 3NF 정의로 가지 않음, 2NF가 전제","㉠은 2NF여야 함","","㉡에 해당하는 건 3NF"],"kc":"1-40","box":["어떤 릴레이션 R이 ( ㉠ )이고, 기본키에 속하지 않은 속성 모두가 기본키에 이행적 함수종속이 아닐 때 ( ㉡ )에 속한다."]},{"id":1693,"c":"c10","d":2,"q":"데이터 모델링의 정규화에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["정규화는 개념 데이터 모델의 일관성을 확보하고 중복을 제거하여 속성들이 가장 적절한 엔터티에 배치되도록 한다.","제1정규형은 모든 인스턴스가 반드시 하나의 값을 가져야 함을 의미한다.","제3정규형을 만족하는 엔터티의 일반속성은 주식별자 전체에 종속적이다.","반정규화는 성능을 위해 데이터 중복을 허용하는 것이지만 성능의 향상을 항상 보장하는 것은 아니다."],"a":0,"e":"정규화는 논리 데이터 모델을 상세화하는 과정의 활동이다. 개념 데이터 모델이라고 한 ①이 틀렸다.","src":"핵심기출 · 1과목 41번","w":["","1NF는 모든 속성이 하나의 값만 가짐, 맞음","3NF는 2NF 전제라 주식별자 전체에 종속, 맞음","반정규화가 성능을 항상 보장하진 않음, 맞음"],"kc":"1-41"},{"id":1694,"c":"c08","d":3,"q":"관계(Relationship)와 조인(Join)에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["조인(Join)이란 식별자를 상속하고, 상속된 속성을 매핑키로 활용하여 데이터를 결합하는 것을 의미한다.","부모의 식별자를 자식의 일반속성으로 상속하면 식별 관계, 부모의 식별자를 자식의 식별자에 포함하면 비식별 관계라고 할 수 있다.","관계(Relationship)를 맺는다는 것은 식별자를 상속시키고 해당 식별자를 매핑키로 활용해 데이터를 결합해 보겠다는 것을 의미한다.","\"SELECT B.고객명 FROM 주문 A, 고객 B WHERE A.고객번호 = B.고객번호\" 쿼리에서 조인키(Join Key)는 \"고객번호\"이다."],"a":1,"e":"부모 식별자를 자식 식별자(PK)에 포함하면 식별 관계, 일반속성으로 받으면 비식별 관계. ②는 반대로 써 놓았다.","src":"핵심기출 · 1과목 42번","w":["조인 = 상속된 속성을 매핑키로 결합, 맞음","","관계를 맺는 것 = 식별자 상속 + 매핑키 결합, 맞음","주문.고객번호 = 고객.고객번호로 조인하므로 조인키는 고객번호"],"kc":"1-42"},{"id":1695,"c":"c10","d":1,"q":"아래에서 설명하는 정규형으로 가장 적절한 것은?","code":null,"o":["제1정규형","제2정규형","제3정규형","보이스-코드 정규형"],"a":1,"e":"일반속성이 주식별자 전체에 종속 = 부분 종속이 없다 = 제2정규형.","src":"핵심기출 · 1과목 43번","w":["1NF는 모든 속성이 원자값","","3NF는 일반속성 간 이행 종속이 없는 것","BCNF는 모든 결정자가 후보키"],"kc":"1-43","box":["엔터티의 일반속성은 주식별자 전체에 종속적이어야 한다."]},{"id":1696,"c":"c10","d":3,"q":"아래와 같이 수강지도 엔터티를 만들었을 때 이에 해당하는 정규형과 정규화의 대상으로 가장 적절한 것은?","code":null,"o":["1차 정규형, 2차 정규화 대상","2차 정규형, 3차 정규화 대상","3차 정규형, 보이스-코드 정규화대상","보이스-코드정규형, 4차 정규화 대상"],"a":0,"e":"반복 그룹이 없으니 1NF는 만족. 그런데 학번→지도교수명, 학번→학과명처럼 PK 일부에 종속된 속성이 있어 2NF가 아니다. 그래서 1정규형이면서 2차 정규화 대상.","src":"핵심기출 · 1과목 44번","w":["","부분 종속이 있어 2NF가 아님","2NF도 아니니 3NF는 더더욱 아님","BCNF와는 거리가 멂"],"kc":"1-44","box":["[수강지도]","식별자: 학번, 과목코드","일반속성: 성적, 지도교수명, 학과명","","함수종속성(FD)","1. 학번 || 과목코드 → 성적","2. 학번 → 지도교수명","3. 학번 → 학과명"]},{"id":1697,"c":"c10","d":2,"q":"고객번호를 식별자로 하는 아래 엔터티에서 필요한 정규화 작업으로 가장 적절한 것은?","code":null,"o":["1차 정규화","2차 정규화","3차 정규화","4차 정규화"],"a":0,"e":"취미코드·취미명에 '10,11', '노래,댄스'처럼 값이 여러 개 들어 있다. 속성은 하나의 값만 가져야 하므로 1차 정규화부터 필요.","src":"핵심기출 · 1과목 45번","w":["","부분 종속 이전에 다중값 문제가 먼저","3차는 이행 종속 문제","4차는 다치 종속 문제"],"kc":"1-45","tables":[{"name":"","cols":["고객번호","고객명","주민등록번호","취미코드","취미명"],"rows":[["10","김OO","123456-7890123","10,11","노래,댄스"],["20","이OO","234567-8901234","12,13","검도, 게임"],["30","박OO","345678-9012345","11,15,16","댄스,등산,수영"]]}]},{"id":1698,"c":"c15","d":1,"q":"NULL에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["모르는 값을 의미한다.","값의 부재를 의미한다.","공백문자(Empty String) 혹은 숫자 0을 의미한다.","NULL과의 모든 비교(IS NULL 제외)는 알 수 없음(Unknown)을 반환한다."],"a":2,"e":"NULL은 모르는 값, 값의 부재다. 공백문자('')나 숫자 0과 같지 않다.","src":"핵심기출 · 1과목 46번","w":["모르는 값, 맞음","값의 부재, 맞음","","IS NULL 외 모든 비교는 Unknown, 맞음"],"kc":"1-46"},{"id":1699,"c":"c10","d":3,"q":"아래와 같이 테이블을 변환하였을 때 이에 대한 설명으로 가장 적절하지 않은 것은? (단, (A)에서 주식별자는 (사번, 부서)이며, 함수 종속성 부서→사무실이 존재한다고 가정)","code":null,"o":["제1정규화를 수행한 것에 해당한다.","제2정규화를 수행한 것에 해당한다.","(B)는 제3정규형을 만족한다.","주어진 사번의 사무실을 검색하는 작업의 성능이 저하된다."],"a":0,"e":"(A)에서 PK가 (사번, 부서)인데 부서→사무실 부분 종속이 있었다. 이걸 떼어냈으니 2차 정규화를 수행한 것이고 1차 정규화가 아니다. (B)는 이행 종속도 없어 3NF까지 만족.","src":"핵심기출 · 1과목 47번","w":["","부분 종속 제거 = 제2정규화, 맞음","(B)는 3NF도 만족, 맞음","사번→사무실을 찾으려면 조인이 필요해 성능 저하, 맞음"],"kc":"1-47","tables":[{"name":"(A)","cols":["사번","부서","사무실"],"rows":[["001","총무","서울"],["002","영업","부산"],["003","총무","서울"],["004","연구","대전"],["005","영업","부산"]]},{"name":"(B) ①","cols":["사번","부서"],"rows":[["001","총무"],["002","영업"],["003","총무"],["004","연구"],["005","영업"]]},{"name":"(B) ②","cols":["부서","사무실"],"rows":[["총무","서울"],["영업","부산"],["연구","대전"]]}],"note":"(A) ⇨ (B): (A)를 (B)의 두 테이블로 분리"},{"id":1700,"c":"c13","d":2,"q":"순차적으로 수행되는 작업 A와 B가 반드시 모두 수행되거나 모두 수행되지 않아야 한다고 할 때, 이에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["A와 B는 하나의 트랜잭션으로 묶여 처리되어야 한다.","A와 B를 수행한 후 각각 커밋(Commit)을 해주어야 한다.","A와 B에 주어진 조건은 트랜잭션의 원자성(Atomicity)에 해당한다.","A까지만 수행되고 시스템 장애가 발생했다면 A를 undo해야 한다."],"a":1,"e":"A와 B는 한 트랜잭션으로 묶어 둘 다 끝난 뒤 한 번만 커밋해야 한다. 각각 커밋하면 A만 반영되고 B가 실패하는 상황을 막을 수 없다.","src":"핵심기출 · 1과목 48번","w":["하나의 트랜잭션으로 묶어야 함, 맞음","","모두 수행 or 모두 미수행 = 원자성, 맞음","A만 수행 후 장애면 A를 undo, 맞음"],"kc":"1-48"},{"id":1701,"c":"c15","d":2,"q":"NULL 값에 대한 설명으로 가장 적절한 것은?","code":null,"o":["NULL 값에 어떤 숫자를 더해도 결과는 항상 NULL이다.","NULL 값과 어떤 숫자의 크기를 비교해도 결과는 항상 NULL이다.","\"NULL = NULL\" 연산의 결과는 TRUE이다.","집계 함수를 계산할 때 NULL 값은 0으로 처리된다."],"a":0,"e":"NULL에 어떤 숫자를 더해도 NULL. 비교 결과는 NULL이 아니라 Unknown이고, NULL = NULL도 TRUE가 아니다. 집계 함수는 NULL을 0으로 치지 않고 아예 뺀다.","src":"핵심기출 · 1과목 49번","w":["","비교 결과는 NULL이 아니라 Unknown","NULL = NULL은 TRUE가 아님(Unknown/FALSE 취급)","집계 시 NULL은 0이 아니라 계산에서 제외"],"kc":"1-49"},{"id":1702,"c":"c07","d":2,"q":"본질식별자와 인조식별자에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["인조식별자는 대체로 본질식별자가 복잡한 구성을 가질 때 만들어진다.","인조식별자를 사용하면 중복 데이터를 막기 어려워진다.","인조식별자를 사용하면 본질식별자를 사용할 때와 비교하여 추가적인 인덱스가 필요해진다.","인조식별자는 개발 편의성을 높여주기 때문에 되도록 사용하는 것이 바람직하다."],"a":3,"e":"인조식별자는 중복 데이터를 막기 어렵고 추가 인덱스가 필요해지는 등 단점이 있다. 편하다고 무조건 쓰는 게 아니라 꼭 필요할 때만 쓴다.","src":"핵심기출 · 1과목 50번","w":["본질식별자가 복잡할 때 대체로 만들어짐, 맞음","일련번호라 같은 데이터가 중복 입력돼도 못 막음, 맞음","본질식별자 유일성 보장용 인덱스가 추가로 필요, 맞음",""],"kc":"1-50"},{"id":1703,"c":"s01","d":1,"q":"데이터 제어어(DCL)에 해당하는 명령어는?","code":null,"o":["INSERT","RENAME","COMMIT","REVOKE"],"a":3,"e":"DCL은 권한을 주고(GRANT) 회수(REVOKE)하는 명령어다.","src":"핵심기출 · 2과목 1번","w":["INSERT는 DML","RENAME은 DDL","COMMIT은 TCL",""],"kc":"2-1"},{"id":1704,"c":"s01","d":1,"q":"아래에서 빈칸 ㉠에 들어갈 내용으로 가장 적절한 것은?","code":null,"o":["UPDATE","SELECT","ALTER","REVOKE"],"a":0,"e":"잘못 입력됐거나 바뀐 정보를 고치는 DML = UPDATE.","src":"핵심기출 · 2과목 2번","w":["","SELECT는 조회","ALTER는 테이블 구조 변경(DDL)","REVOKE는 권한 회수(DCL)"],"kc":"2-2","box":["INSERT는 테이블에 데이터를 입력할 때 사용한다.","( ㉠ )는 입력한 정보 중에 잘못 입력되거나 변경이 발생하여 정보를 수정할 때 사용한다.","DELETE는 테이블의 정보가 필요 없게 되었을 경우 데이터 삭제를 수행한다."]},{"id":1705,"c":"s01","d":1,"q":"아래 내용에 해당하는 SQL 명령어의 종류는?","code":null,"o":["DDL","DML","TCL","TML"],"a":2,"e":"COMMIT, ROLLBACK, SAVEPOINT처럼 DML 결과를 트랜잭션 단위로 제어 = TCL.","src":"핵심기출 · 2과목 3번","w":["DDL은 구조 정의(CREATE, ALTER 등)","DML은 데이터 조작","","TML이라는 분류는 없음"],"kc":"2-3","box":["논리적인 작업의 단위를 묶어 DML에 의해 조작된 결과를 작업단위(Transaction)별로 제어하는 명령어인 Commit, Rollback, Savepoint 등이 여기에 해당하며, 일부에서는 DCL(Data Control Language)로 분류하기도 한다."]},{"id":1706,"c":"s03","d":2,"q":"SELECT 문에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["WHERE 절은 필수가 아니므로 생략 가능하다.","DISTINCT 옵션을 통해 중복된 데이터가 있을 경우 1건으로 처리해 출력할 수 있다.","FROM 절이 없는 다음 문장 \"SELECT COL1, COL2\"은 에러 없이 수행된다.","SELECT List에 서브쿼리가 사용될 수 있다."],"a":2,"e":"오라클에서 SELECT와 FROM은 필수라 FROM 없는 'SELECT COL1, COL2'는 에러. 상수만 조회할 때도 DUAL을 붙인다.","src":"핵심기출 · 2과목 4번","w":["WHERE는 선택 사항, 맞음","DISTINCT로 중복 1건 처리, 맞음","","SELECT 절 스칼라 서브쿼리 사용 가능, 맞음"],"kc":"2-4"},{"id":1707,"c":"s01","d":1,"q":"SQL의 종류와 해당되는 명령어를 바르게 연결한 것은?","code":null,"o":["DML - SELECT","TCL - GRANT","DCL - DROP","DML - ALTER"],"a":0,"e":"SELECT는 DML. GRANT는 DCL, DROP·ALTER는 DDL이라 나머지는 모두 잘못 연결됐다.","src":"핵심기출 · 2과목 5번","w":["","GRANT는 TCL이 아니라 DCL","DROP은 DCL이 아니라 DDL","ALTER는 DML이 아니라 DDL"],"kc":"2-5"},{"id":1708,"c":"s01","d":1,"q":"아래 내용의 범주에 해당하는 SQL 명령어로 가장 적절하지 않은 것은?","code":null,"o":["CREATE","GRANT","ALTER","DROP"],"a":1,"e":"테이블 구조를 생성·변경·삭제 = DDL(CREATE, ALTER, DROP, RENAME). GRANT는 DCL이라 범주가 다르다.","src":"핵심기출 · 2과목 6번","w":["CREATE는 DDL","","ALTER는 DDL","DROP은 DDL"],"kc":"2-6","box":["테이블의 구조를 생성, 변경, 삭제하는 등 데이터 구조를 정의하는 데 사용되는 명령어이다."]},{"id":1709,"c":"s03","d":1,"q":"데이터베이스에서 조회되는 데이터에 대한 조건을 설정하여 원하는 데이터만을 검색하기 위해 사용하는 절로 가장 적절한 것은?","code":null,"o":["WHERE 절","GROUP BY 절","ORDER BY 절","HAVING 절"],"a":0,"e":"조회할 데이터에 조건을 걸어 원하는 행만 고르는 절 = WHERE.","src":"핵심기출 · 2과목 7번","w":["","GROUP BY는 소그룹 묶기","ORDER BY는 정렬","HAVING은 그룹에 대한 조건"],"kc":"2-7"},{"id":1710,"c":"s11","d":2,"q":"SQL 문을 실행했을 때 오류가 발생하는 부분으로 가장 적절한 것은?","code":null,"o":["SELECT DEPTNO, ROUND(AVG(SAL),2)","FROM EMP","WHERE AVG(SAL) >= 1800","GROUP BY DEPTNO;"],"a":2,"e":"WHERE 절에는 집계 함수를 쓸 수 없다. 그룹 조건은 HAVING AVG(SAL) >= 1800으로 써야 한다.","src":"핵심기출 · 2과목 8번","w":["SELECT 절의 집계 함수는 GROUP BY와 함께라 문제없음","FROM 절은 문제없음","","GROUP BY DEPTNO는 문제없음"],"kc":"2-8"},{"id":1711,"c":"s10","d":3,"q":"아래 SQL의 수행 결과로 가장 적절한 것은?","code":["SELECT SUM(COL2) + SUM(COL3) FROM TAB_A;","SELECT SUM(COL2) + SUM(COL3) FROM TAB_A WHERE COL1 > 0;","SELECT SUM(COL2) + SUM(COL3) FROM TAB_A WHERE COL1 IS NOT NULL;","SELECT SUM(COL2) + SUM(COL3) FROM TAB_A WHERE COL1 IS NULL;"],"o":["60, NULL, 30, 60","60, 20, 30, 60","90, NULL, 30, 60","90, 20, 30, 60"],"a":2,"e":"SUM은 NULL을 빼고 더한다. ① 전체: COL2 50+10=60, COL3 20+10=30 → 90. ② COL1>0이면 30인 행만 남는데 COL2가 NULL → SUM(COL2)=NULL, NULL+20=NULL. ③ IS NOT NULL이면 30, 0 행 → COL2 10, COL3 20 → 30. ④ IS NULL이면 두 번째 행만 → 50+10=60.","src":"핵심기출 · 2과목 9번","w":["첫 번째 SQL은 COL2 합 60 + COL3 합 30 = 90","첫 번째가 90이고 두 번째는 SUM(COL2)가 NULL이라 결과 NULL","","두 번째 SQL은 COL2가 NULL 하나뿐이라 SUM 결과가 NULL"],"kc":"2-9","tables":[{"name":"TAB_A","cols":["COL1","COL2","COL3"],"rows":[["30","NULL","20"],["NULL","50","10"],["0","10","NULL"]],"after":true}]},{"id":1712,"c":"s09","d":1,"q":"다음 SQL 문장 중 COLUMN1의 값이 NULL이 아닌 경우를 찾아내는 문장으로 가장 적절한 것은? (ANSI 표준 기준)","code":null,"o":["SELECT * FROM MYTABLE WHERE COLUMN1 IS NOT NULL;","SELECT * FROM MYTABLE WHERE COLUMN1 <> NULL;","SELECT * FROM MYTABLE WHERE COLUMN1 != NULL;","SELECT * FROM MYTABLE WHERE COLUMN1 NOT NULL;"],"a":0,"e":"NULL 비교는 = 나 <> 로 하면 결과가 Unknown이라 아무것도 안 나온다. 반드시 IS NULL / IS NOT NULL.","src":"핵심기출 · 2과목 10번","w":["","<> NULL은 항상 Unknown","!= NULL도 항상 Unknown","NOT NULL은 WHERE 조건 문법이 아님(IS NOT NULL)"],"kc":"2-10"},{"id":1713,"c":"s19","d":3,"q":"아래에 대한 설명으로 가장 적절한 것은?","code":["CREATE TABLE 서비스","(","    서비스번호 VARCHAR2(10) PRIMARY KEY,","    서비스명 VARCHAR2(100) NULL,","    개시일자 DATE NOT NULL",");","","-- SQL","㉠ SELECT * FROM 서비스 WHERE 서비스번호 = 1;","㉡ INSERT INTO 서비스 VALUES ('999', '', '2015-11-11');","㉢ SELECT * FROM 서비스 WHERE 서비스명 = '';","㉣ SELECT * FROM 서비스 WHERE 서비스명 IS NULL;"],"o":["서비스번호 칼럼의 레코드 중 '001'과 같은 숫자 형식으로 된 레코드가 하나라도 입력되어 있다면 ㉠은 오류 없이 실행된다.","오라클에서 ㉡과 같이 데이터를 입력하였을 때, 서비스명 칼럼에 공백 문자 데이터가 입력된다.","오라클에서 ㉡과 같이 데이터를 입력하고 ㉢과 같이 조회하였을 때, 데이터는 조회된다.","SQL Server에서 ㉡과 같이 데이터를 입력하고 ㉣과 같이 조회하였을 때, 데이터는 조회되지 않는다."],"a":3,"e":"SQL Server는 ''를 빈 문자열로 저장하므로 IS NULL로는 안 잡히고 = ''로 찾아야 한다. 오라클은 ''를 NULL로 저장해서 반대가 된다.","src":"핵심기출 · 2과목 11번","w":["VARCHAR2 컬럼과 숫자 1을 비교하면 모든 값을 숫자로 변환하는데, 숫자로 못 바꾸는 값이 하나라도 있으면 에러. '001' 같은 게 하나 있다고 되는 게 아니라 전부 숫자형이어야 함","오라클은 ''를 NULL로 저장","오라클에서 ''는 NULL이라 = ''로는 조회 안 됨(IS NULL로 찾아야 함)",""],"kc":"2-11"},{"id":1714,"c":"s04","d":2,"q":"함수의 실행 결과로 가장 적절하지 않은 것은? (단, A의 아스키코드는 65이다.)","code":null,"o":["LOWER('SQL Expert') : 'sql expert'","UPPER('SQL Expert') : 'SQL EXPERT'","ASCII('A') : 65","LTRIM('xxYYZZxYZxx','x') : 'YYZZxYZ'"],"a":3,"e":"LTRIM은 왼쪽에서부터 지정 문자를 지우다가 다른 문자를 만나면 멈춘다. 'xxYYZZxYZxx'에서 앞의 xx만 지워져 'YYZZxYZxx'가 된다. 오른쪽 xx까지 지운 건 TRIM.","src":"핵심기출 · 2과목 12번","w":["LOWER는 전부 소문자, 맞음","UPPER는 전부 대문자, 맞음","ASCII('A') = 65, 맞음",""],"kc":"2-12"},{"id":1715,"c":"s05","d":3,"q":"아래를 참고할 때 실행 결과가 다른 SQL은?","code":null,"o":["SELECT SVC_ID, COUNT(*) AS CNT\nFROM SVC_JOIN\nWHERE SVC_END_DATE >= TO_DATE('20150101000000', 'YYYYMMDDHH24MISS')\nAND SVC_END_DATE <= TO_DATE('20150131235959', 'YYYYMMDDHH24MISS')\nAND CONCAT(JOIN_YMD, JOIN_HH) = '2014120100'\nGROUP BY SVC_ID;","SELECT SVC_ID, COUNT(*) AS CNT\nFROM SVC_JOIN\nWHERE SVC_END_DATE >= TO_DATE('20150101', 'YYYYMMDD')\nAND SVC_END_DATE < TO_DATE('20150201', 'YYYYMMDD')\nAND (JOIN_YMD, JOIN_HH) IN (('20141201', '00'))\nGROUP BY SVC_ID;","SELECT SVC_ID, COUNT(*) AS CNT\nFROM SVC_JOIN\nWHERE '201501' = TO_CHAR(SVC_END_DATE, 'YYYYMM')\nAND JOIN_YMD = '20141201'\nAND JOIN_HH = '00'\nGROUP BY SVC_ID;","SELECT SVC_ID, COUNT(*) AS CNT\nFROM SVC_JOIN\nWHERE TO_DATE('201501', 'YYYYMM') = SVC_END_DATE\nAND JOIN_YMD||JOIN_HH = '2014120100'\nGROUP BY SVC_ID"],"a":3,"e":"①②③은 가입이 2014-12-01 00시이고 종료일시가 2015년 1월 한 달 범위 안인 데이터를 찾는다. ④는 TO_DATE('201501','YYYYMM') = 2015-01-01 00:00:00과 정확히 같은 데이터만 찾아서 결과가 다르다.","src":"핵심기출 · 2과목 13번","w":["1월 1일 0시~1월 31일 23:59:59 범위 + 가입일시 조건","1월 1일 이상 2월 1일 미만 범위 + 다중 컬럼 IN","TO_CHAR로 'YYYYMM'이 201501인 것 = 1월 전체",""],"kc":"2-13","box":["서비스_가입 (논리)","  식별자: 고객ID, 서비스ID, 가입일자, 가입시간","  일반속성: 서비스시작일시, 서비스종료일시","SVC_JOIN (물리)","  CUST_ID VARCHAR2(10) NOT NULL, SVC_ID VARCHAR2(5) NOT NULL, JOIN_YMD VARCHAR2(8) NOT NULL, JOIN_HH VARCHAR2(4) NOT NULL  ← PK","  SVC_START_DATE DATE NULL, SVC_END_DATE DATE NULL"]},{"id":1716,"c":"s11","d":2,"q":"GROUP BY 절과 HAVING 절에 대한 설명으로 가장 적절한 것은?","code":null,"o":["집계 함수의 통계 정보는 NULL 값을 가진 행을 포함하여 수행한다.","GROUP BY 절에서는 SELECT 절과 같이 ALIAS 명을 사용할 수 있다.","집계 함수는 WHERE 절에도 올 수 있다.","HAVING 절은 일반적으로 GROUP BY 절 뒤에 위치한다."],"a":3,"e":"HAVING은 보통 GROUP BY 뒤에 온다.","src":"핵심기출 · 2과목 14번","w":["집계 함수는 NULL 행을 제외하고 계산","GROUP BY에는 SELECT 절 ALIAS를 쓸 수 없음(GROUP BY가 먼저 실행)","집계 함수는 WHERE 절에 못 씀",""],"kc":"2-14"},{"id":1717,"c":"s04","d":3,"q":"아래를 참고할 때 SQL의 실행 결과로 가장 적절한 것은? (단, 이해를 돕기 위해 ↵는 줄바꿈을 의미하며 실제 저장값이 아님, 또한 CHR(10)의 ASCII 값은 줄바꿈을 의미)","code":["SELECT SUM(CC)","FROM","(","SELECT (LENGTH(C1) - LENGTH(REPLACE(C1, CHR(10))) + 1) CC","FROM TAB1",");"],"o":["2","3","5","6"],"a":2,"e":"LENGTH(C1) - LENGTH(줄바꿈 뺀 C1) = 줄바꿈 개수, +1 하면 줄 수. 'A↵A'는 3-2+1=2, 'B↵B↵B'는 5-3+1=3. SUM = 5.","src":"핵심기출 · 2과목 15번","w":["행 개수(2건)를 답으로 본 값","줄바꿈 개수만 센 값(1+2=3), 행마다 1을 더해야 줄 수","","줄 수를 행마다 하나씩 더 센 값"],"kc":"2-15","tables":[{"name":"TAB1","cols":["ROWNUM","C1"],"rows":[["1","A↵A"],["2","B↵B↵B"]]}]},{"id":1718,"c":"s05","d":2,"q":"아래 SQL의 실행 결과로 가장 적절한 것은? (단, DBMS는 오라클로 가정)","code":["SELECT TO_CHAR(TO_DATE('2023.01.10 10', 'YYYY.MM.DD HH24')","       + 1/24/(60/10), 'YYYY.MM.DD HH24:MI:SS') FROM DUAL;"],"o":["2023.01.10 11:01:00","2023.01.10 10:05:00","2023.01.10 10:10:00","2023.01.10 10:30:00"],"a":2,"e":"오라클 날짜 연산에서 1 = 하루. 1/24 = 1시간, 1/24/60 = 1분이니 1/24/(60/10) = 1/24/6 = 10분. 10:00에 10분 더해 10:10:00.","src":"핵심기출 · 2과목 16번","w":["1시간 1분을 더한 값","5분을 더한 값","","30분을 더한 값"],"kc":"2-16"},{"id":1719,"c":"s07","d":2,"q":"아래의 (가)와 (나)가 동일한 결과를 출력한다고 할 때, 빈칸 ㉠에 들어갈 내용으로 가장 적절한 것은? (단, 스칼라 서브쿼리는 제외함)","code":["(가)","SELECT LOC,","  CASE WHEN LOC = 'NEW YORK' THEN 'EAST'","    ELSE 'ETC'","  END as AREA","FROM DEPT;","","(나)","SELECT LOC,","       ( ㉠ ) as AREA","FROM DEPT;"],"o":["CASE WHEN LOC IS 'NEW YORK' THEN 'EAST' ELSE 'ETC' END","CASE LOC WHEN 'NEW YORK' THEN 'EAST' ELSE 'ETC' END","CASE LOC WHEN 'NEW YORK' THEN 'EAST' DEFAULT 'ETC' END","DECODE (LOC, 'EAST', 'NEW YORK', 'ETC')"],"a":1,"e":"= 조건 하나뿐인 검색 CASE는 단순 CASE 'CASE LOC WHEN 'NEW YORK' THEN ...'으로 바꿀 수 있다.","src":"핵심기출 · 2과목 17번","w":["IS는 NULL 비교에만 씀. LOC IS 'NEW YORK'은 문법 오류","","CASE에는 DEFAULT가 아니라 ELSE","DECODE(LOC, 'NEW YORK', 'EAST', 'ETC') 순서여야 함"],"kc":"2-17"},{"id":1720,"c":"s07","d":3,"q":"각 팀별로 FW, MF, DF, GK 포지션의 인원수와 팀별 전체 인원수를 구하는 SQL을 작성할 때 결과가 다른 하나는? (단, ①은 SQL Server 환경이고 보기 ②, ③, ④는 오라클 환경이다.)","code":null,"o":["SELECT TEAM_ID,\nISNULL(SUM(CASE WHEN POSITION = 'FW' THEN 1 END), 0) FW,\nISNULL(SUM(CASE WHEN POSITION = 'MF' THEN 1 END), 0) MF,\nISNULL(SUM(CASE WHEN POSITION = 'DF' THEN 1 END), 0) DF,\nISNULL(SUM(CASE WHEN POSITION = 'GK' THEN 1 END), 0) GK,\nCOUNT(*) SUM\nFROM PLAYER\nGROUP BY TEAM_ID;","SELECT TEAM_ID,\nNVL(SUM(CASE POSITION WHEN 'FW' THEN 1 END),0) FW,\nNVL(SUM(CASE POSITION WHEN 'MF' THEN 1 END),0) MF,\nNVL(SUM(CASE POSITION WHEN 'DF' THEN 1 END),0) DF,\nNVL(SUM(CASE POSITION WHEN 'GK' THEN 1 END),0) GK,\nCOUNT(*) SUM\nFROM PLAYER\nGROUP BY TEAM_ID;","SELECT TEAM_ID,\nNVL(SUM(CASE WHEN POSITION = 'FW' THEN 1 END), 0) FW,\nNVL(SUM(CASE WHEN POSITION = 'MF' THEN 1 END), 0) MF,\nNVL(SUM(CASE WHEN POSITION = 'DF' THEN 1 END), 0) DF,\nNVL(SUM(CASE WHEN POSITION = 'GK' THEN 1 END), 0) GK,\nCOUNT(*) SUM\nFROM PLAYER\nGROUP BY TEAM_ID;","SELECT TEAM_ID,\nNVL(SUM(CASE POSITION WHEN 'FW' THEN 1 ELSE 1 END),0) FW,\nNVL(SUM(CASE POSITION WHEN 'MF' THEN 1 ELSE 1 END),0) MF,\nNVL(SUM(CASE POSITION WHEN 'DF' THEN 1 ELSE 1 END),0) DF,\nNVL(SUM(CASE POSITION WHEN 'GK' THEN 1 ELSE 1 END),0) GK,\nCOUNT(*) SUM\nFROM PLAYER\nGROUP BY TEAM_ID;"],"a":3,"e":"④는 ELSE 1이 있어서 포지션과 상관없이 모든 행이 1이 된다. FW·MF·DF·GK 칸 모두 팀 전체 인원수가 나와 결과가 다르다. 나머지는 해당 포지션만 1, 아니면 NULL이라 정상.","src":"핵심기출 · 2과목 18번","w":["SQL Server ISNULL로 NULL→0, 정상 결과","단순 CASE + NVL, 정상 결과","검색 CASE + NVL, 정상 결과",""],"kc":"2-18"},{"id":1721,"c":"s11","d":2,"q":"아래 SQL에 대한 설명으로 가장 적절한 것은? (단, 고객이름은 중복되지 않는다고 가정)","code":["SELECT 고객이름, SUM(수량)","FROM 고객, 상품, 주문","WHERE 고객.고객번호 = 주문.고객번호","AND 상품.상품번호 = 주문.상품번호","GROUP BY 고객.고객이름","HAVING MAX(수량) > 10;"],"o":["고객번호가 10보다 큰 고객이름과 주문한 수량의 합을 구한다.","수량이 10보다 큰 주문을 한 고객이름과 주문한 수량의 합을 구한다.","열한 번 이상 상품을 주문한 고객이름과 주문한 수량의 합을 구한다.","주문한 수량의 합이 10보다 큰 고객이름과 주문한 수량의 합을 구한다."],"a":1,"e":"HAVING MAX(수량) > 10은 '한 번이라도 수량 10 초과 주문을 한 고객'이라는 뜻. 그 고객의 이름과 전체 주문 수량 합을 구한다.","src":"핵심기출 · 2과목 19번","w":["고객번호 조건이 아니라 수량 조건","","주문 횟수(COUNT)가 아님","합계가 아니라 MAX 조건"],"kc":"2-19","box":["고객 (__고객번호__, 고객이름, 주소, 전화번호)","상품 (__상품번호__, 상품이름, 무게, 가격)","주문 (__고객번호__, __상품번호__, 수량, 날짜)"]},{"id":1722,"c":"s06","d":1,"q":"EMP 테이블에서 MGR의 값이 7698과 같으면 NULL을 표시하고, 같지 않으면 MGR을 표시하려고 할 때 빈칸 ㉠에 들어갈 함수는?","code":["SELECT ENAME, EMPNO, MGR, ( ㉠ )(MGR,7698) as NM","FROM EMP;"],"o":["NULLIF","NVL","IFNULL","COALESCE"],"a":0,"e":"NULLIF(MGR, 7698)은 두 값이 같으면 NULL, 다르면 MGR을 돌려준다.","src":"핵심기출 · 2과목 20번","w":["","NVL은 NULL일 때 대체값","IFNULL은 MySQL 함수, 기능도 NVL 쪽","COALESCE는 처음으로 NULL 아닌 값"],"kc":"2-20"},{"id":1723,"c":"s12","d":2,"q":"실행 결과가 다른 하나는?","code":null,"o":["SELECT DNAME, LOC, DEPTNO\nFROM DEPT\nORDER BY DNAME, LOC, 3 DESC;","SELECT DNAME, LOC AREA, DEPTNO\nFROM DEPT\nORDER BY DNAME, AREA, DEPTNO DESC;","SELECT DNAME, LOC AREA, DEPTNO\nFROM DEPT\nORDER BY 1, AREA, 3 DESC;","SELECT DNAME DEPT, LOC AREA, DEPTNO\nFROM DEPT\nORDER BY DEPT DESC, LOC, 3 DESC;"],"a":3,"e":"①②③은 모두 DNAME 오름차순 → LOC 오름차순 → DEPTNO 내림차순. ④는 DEPT(=DNAME 별칭)를 DESC로 정렬해서 결과가 다르다.","src":"핵심기출 · 2과목 21번","w":["DNAME, LOC, 3번째 컬럼 DESC","AREA는 LOC 별칭, 같은 정렬","1번째 컬럼, AREA, 3번째 DESC, 같은 정렬",""],"kc":"2-21"},{"id":1724,"c":"s09","d":2,"q":"아래는 이름이 4문자 이상이고 2번째 문자가 S인 학번을 출력하는 SQL이다. 빈칸 ㉠에 들어갈 수 있는 내용으로 가장 적절하지 않은 것은?","code":["SELECT 학번","FROM   학생","WHERE  학생.이름 LIKE ( ㉠ )"],"o":["`'%S___'`","`'_S%__'`","`'_S_%_'`","`'_S__%'`"],"a":0,"e":"`'%S___'`는 %가 빈 문자열도 되니까 'SABC'처럼 S가 첫 글자인 이름도 걸린다. 2번째 문자가 S라는 조건을 보장 못 해서 부적절.","src":"핵심기출 · 2과목 22번","w":["","'_S%__' : 2번째 S, 최소 4글자, 맞음","'_S_%_' : 2번째 S, 최소 4글자, 맞음","'_S__%' : 2번째 S, 최소 4글자, 맞음"],"kc":"2-22"},{"id":1725,"c":"s12","d":1,"q":"전공이름별로 묶어 전공이름과 학점 평균을 전공이름의 내림차순으로 정렬하여 출력하고자 할 때, 빈칸 ㉠, ㉡에 들어갈 명령어로 가장 적절한 것은?","code":["SELECT   전공이름, AVG(학점)","FROM     전공, 학생","WHERE    전공.전공번호 = 학생.전공번호","( ㉠ )   전공이름","ORDER BY 전공이름 ( ㉡ );"],"o":["㉠ GROUP BY  ㉡ DESC","㉠ HAVING  ㉡ DESC","㉠ GROUP BY  ㉡ ASC","㉠ HAVING  ㉡ ASC"],"a":0,"e":"전공이름으로 묶으니 ㉠ GROUP BY, 내림차순이니 ㉡ DESC.","src":"핵심기출 · 2과목 23번","w":["","HAVING은 그룹 조건이지 그룹을 만드는 절이 아님","ASC는 오름차순","둘 다 틀림"],"kc":"2-23"},{"id":1726,"c":"s04","d":2,"q":"SQL의 실행 결과로 가장 적절하지 않은 것은?","code":null,"o":["ROUND(4.875, 2) = 4.88","LENGTH('KOREAN') = 6","DATE_FORMAT('2022-11-02', '%Y-%m-%d') = 2022-11-02","SUBSTR('Gangneung Wonju', 8, 4) = 'g Wo'"],"a":3,"e":"'Gangneung Wonju'에서 8번째 글자는 n(G1 a2 n3 g4 n5 e6 u7 n8). 거기서 4글자는 'ng W'라 'g Wo'는 틀렸다.","src":"핵심기출 · 2과목 24번","w":["소수 셋째 자리에서 반올림 4.88, 맞음","KOREAN은 6글자, 맞음","MySQL DATE_FORMAT 결과 2022-11-02, 맞음",""],"kc":"2-24"},{"id":1727,"c":"s20","d":3,"q":"아래를 참고할 때 광고매체 ID별 최초로 게시한 광고명과 광고시작일자를 출력하기 위하여 빈칸 ㉠에 들어갈 SQL로 가장 적절한 것은?","code":["SELECT C.광고매체명, B.광고명, A.광고시작일자","FROM   광고게시 A, 광고 B, 광고매체 C,","       ( ㉠ ) D","WHERE  A.광고시작일자 = D.광고시작일자","AND    A.광고매체ID = D.광고매체ID","AND    A.광고ID = B.광고ID","AND    A.광고매체ID = C.광고매체ID","ORDER BY C.광고매체명;"],"o":["SELECT D.광고매체ID, MIN(D.광고시작일자) AS 광고시작일자\nFROM 광고게시 D\nWHERE D.광고매체ID = C.광고매체ID\nGROUP BY D.광고매체ID","SELECT 광고매체ID, MIN(광고시작일자) AS 광고시작일자\nFROM 광고게시\nGROUP BY 광고매체ID","SELECT MIN(광고매체ID) AS 광고매체ID, MIN(광고시작일자) AS 광고시작일자\nFROM 광고게시\nGROUP BY 광고ID","SELECT MIN(광고매체ID) AS 광고매체ID, MIN(광고시작일자) AS 광고시작일자\nFROM 광고게시"],"a":1,"e":"광고게시에서 광고매체ID별로 가장 이른 광고시작일자를 구해 인라인 뷰 D로 쓰면 된다. ②가 정확히 그 역할.","src":"핵심기출 · 2과목 25번","w":["인라인 뷰 안에서는 같은 FROM의 다른 테이블 C를 참조할 수 없음","","광고ID로 그룹핑하면 광고별 최솟값이 됨","GROUP BY가 없어 전체에서 최솟값 한 건만 나옴"],"kc":"2-25","imgAlt":"광고 (광고ID / 광고명)  ┼- - -○<  광고게시 (광고게시번호 / 광고ID(FK), 광고매체ID(FK), 광고시작일자, 광고종료일자)  >○- - -┼  광고매체 (광고매체ID / 광고매체명)","img":"data/kc/2-25.jpg"},{"id":1728,"c":"s34","d":3,"q":"아래 SQL을 순서대로 실행했을 때 최종적으로 반영되는 SQL을 모두 고른 것은?","code":["(가) INSERT INTO emp (empno, ename, deptno) VALUES (999, 'Smith', 10);","    SAVEPOINT a;","(나) DELETE emp WHERE empno = 202;","    SAVEPOINT b;","(다) UPDATE emp SET ename = 'Clark';","    ROLLBACK TO SAVEPOINT a;","(라) INSERT INTO emp (empno, ename, deptno) VALUES (300, 'Thomas', 30);","    SAVEPOINT c;","(마) DELETE emp WHERE deptno = 20;","    COMMIT;"],"o":["(가), (나), (다), (라), (마)","(가), (나), (다), (라)","(나), (다), (라), (마)","(가), (라), (마)"],"a":3,"e":"ROLLBACK TO SAVEPOINT a는 a 이후 작업인 (나) DELETE와 (다) UPDATE를 취소한다. 그 뒤 (라) INSERT, (마) DELETE를 하고 COMMIT하니 반영되는 건 (가), (라), (마).","src":"핵심기출 · 2과목 26번","w":["(나)·(다)는 SAVEPOINT a로 롤백됨","(나)·(다)는 롤백, (마)는 커밋 전에 실행돼 반영됨","(가)는 SAVEPOINT a 이전이라 살아 있고 (나)·(다)는 취소",""],"kc":"2-26"},{"id":1729,"c":"s10","d":3,"q":"아래 SQL의 실행 결과로 가장 적절한 것은?","code":["SELECT COLB","     , MAX(COLA) AS COLA1","     , MIN(COLA) AS COLA2","     , SUM(COLA + COLC) AS SUMAC","FROM   TABLE_A","GROUP BY COLB;"],"o":[{"cols":["COLB","COLA1","COLA2","SUMAC"],"rows":[["NULL","NULL","NULL","NULL"],["가","1","1","6"],["나","3","3","3"],["다","5","5","5"]]},{"cols":["COLB","COLA1","COLA2","SUMAC"],"rows":[["가","1","NULL","6"],["나","3","NULL","3"],["다","5","NULL","5"]]},{"cols":["COLB","COLA1","COLA2","SUMAC"],"rows":[["NULL","NULL","NULL","3"],["가","1","1","6"],["나","3","3","5"],["다","5","5","5"]]},{"cols":["COLB","COLA1","COLA2","SUMAC"],"rows":[["가","1","NULL","6"],["나","3","NULL","5"],["다","5","NULL","5"]]}],"a":0,"e":"GROUP BY는 COLB가 NULL인 행도 하나의 그룹으로 출력한다. MAX/MIN은 NULL을 빼고 계산하고, COLA+COLC는 둘 중 하나라도 NULL이면 NULL이라 SUM에서 빠진다. 가: 1+5=6, 나: 3+0=3, 다: 5+0=5, NULL그룹: COLA가 NULL뿐이라 전부 NULL.","src":"핵심기출 · 2과목 27번","w":["","COLB NULL 그룹이 빠졌고 MIN(COLA)도 NULL이 아님","NULL 그룹 SUMAC가 3이 아니라 NULL(COLA가 NULL), 나 그룹도 3","COLB NULL 그룹이 빠졌고 MIN(COLA)도 NULL이 아님, 나 그룹 SUMAC도 3"],"kc":"2-27","tables":[{"name":"TABLE_A","cols":["TABKEY","COLA","COLB","COLC"],"rows":[["1","NULL","가","NULL"],["2","1","가","5"],["3","NULL","나","2"],["4","3","나","0"],["5","NULL","NULL","3"],["6","5","다","0"],["7","NULL","다","NULL"]]}],"otype":"table"},{"id":1730,"c":"s12","d":2,"q":"아래 SQL의 실행 결과로 가장 적절한 것은?","code":["SELECT ID FROM TBL","GROUP BY ID","HAVING COUNT(*) = 2","ORDER BY (CASE WHEN ID = 999 THEN 0 ELSE ID END)"],"o":[{"cols":["ID"],"rows":[["100"],["999"]]},{"cols":["ID"],"rows":[["999"],["100"]]},{"cols":["ID"],"rows":[["100"],["200"],["999"]]},{"cols":["ID"],"rows":[["999"],["200"],["100"]]}],"a":1,"e":"COUNT(*)=2인 ID는 100과 999(200은 3건). ORDER BY CASE에서 999는 0으로 바뀌어 맨 앞, 100은 그대로 100. 그래서 999, 100 순서.","src":"핵심기출 · 2과목 28번","w":["999가 0으로 치환돼 먼저 와야 함","","200은 3건이라 HAVING에서 빠짐","200이 포함될 수 없음"],"kc":"2-28","tables":[{"name":"TBL","cols":["ID"],"rows":[["100"],["100"],["200"],["200"],["200"],["999"],["999"]]}],"otype":"table"},{"id":1731,"c":"s12","d":3,"q":"오류가 발생하는 SQL은?","code":null,"o":["SELECT 지역, SUM(매출금액) AS 매출금액\nFROM 지역별매출\nGROUP BY 지역\nORDER BY 매출금액 DESC;","SELECT 지역, 매출금액\nFROM 지역별매출\nORDER BY 년 ASC;","SELECT 지역, SUM(매출금액) AS 매출금액\nFROM 지역별매출\nGROUP BY 지역\nORDER BY 년 DESC;","SELECT 지역, SUM(매출금액) AS 매출금액\nFROM 지역별매출\nGROUP BY 지역\nHAVING SUM(매출금액) > 1000\nORDER BY COUNT(*) ASC;"],"a":2,"e":"GROUP BY를 쓰면 SELECT·ORDER BY에는 GROUP BY 표현식이나 집계 함수만 올 수 있다. ③은 GROUP BY 지역 상태에서 '년'으로 정렬하려 해서 에러. ②는 GROUP BY가 없어서 오라클이 SELECT에 없는 컬럼으로도 정렬해 준다.","src":"핵심기출 · 2과목 29번","w":["매출금액은 SELECT 절 별칭이라 ORDER BY에서 사용 가능","GROUP BY 없음 → SELECT에 없는 컬럼 정렬 가능(오라클)","","COUNT(*)는 집계 함수라 정렬 기준으로 가능"],"kc":"2-29"},{"id":1732,"c":"s05","d":2,"q":"아래 SQL의 실행 결과로 가장 적절한 것은?","code":["SELECT TO_CHAR(TO_DATE('2019.02.25', 'YYYY.MM.DD') +","       1/12/(60/30), 'YYYY.MM.DD HH24:MI:SS')","FROM DUAL;"],"o":["2019.02.25 02:00:00","2019.02.25 01:30:00","2019.02.25 01:00:00","2019.02.25 00:30:00"],"a":2,"e":"1/12 = 2시간, 2시간/(60/30) = 2시간/2 = 1시간. 2019-02-25 00:00:00 + 1시간 = 01:00:00.","src":"핵심기출 · 2과목 30번","w":["2시간 더한 값(1/12를 그대로 본 것)","1시간 30분","","30분"],"kc":"2-30"},{"id":1733,"c":"s06","d":2,"q":"실행 결과가 NULL인 SQL은? (단, DBMS는 오라클로 가정)","code":null,"o":["SELECT COALESCE(NULL, 'A') FROM DUAL;","SELECT NULLIF('A', 'A') FROM DUAL;","SELECT NVL('A', NULL) FROM DUAL;","SELECT NVL(NULL, 0) + 10 FROM DUAL;"],"a":1,"e":"NULLIF('A','A')는 두 값이 같아서 NULL.","src":"핵심기출 · 2과목 31번","w":["COALESCE는 첫 번째 NULL 아닌 값 → 'A'","","NVL('A', NULL) → 'A'","NVL(NULL,0)=0, 0+10=10"],"kc":"2-31"},{"id":1734,"c":"s03","d":1,"q":"SELECT 문장의 실행 순서를 올바르게 나열한 것은?","code":null,"o":["SELECT - FROM - WHERE - GROUP BY - HAVING - ORDER BY","FROM - SELECT - WHERE - GROUP BY - HAVING - ORDER BY","FROM - WHERE - GROUP BY - HAVING - ORDER BY - SELECT","FROM - WHERE - GROUP BY - HAVING - SELECT - ORDER BY"],"a":3,"e":"실행 순서는 FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY.","src":"핵심기출 · 2과목 32번","w":["SELECT는 맨 처음이 아님","SELECT가 WHERE보다 먼저일 수 없음","ORDER BY 다음 SELECT가 아니라 SELECT 다음 ORDER BY",""],"kc":"2-32"},{"id":1735,"c":"s13","d":1,"q":"5개의 테이블로부터 필요한 칼럼을 조회하려고 할 때, 최소 몇 개의 JOIN 조건이 필요한가?","code":null,"o":["2개","3개","4개","5개"],"a":2,"e":"N개 테이블을 조인하려면 최소 N-1개의 조인 조건이 필요하다. 5개면 4개.","src":"핵심기출 · 2과목 33번","w":["부족함","부족함","","N개가 아니라 N-1개"],"kc":"2-33"},{"id":1736,"c":"s13","d":2,"q":"출연료가 8888 이상인 영화명, 배우명, 출연료를 구하는 SQL로 가장 적절한 것은? (단, 밑줄 친 속성들은 테이블의 기본키이다.)","code":null,"o":["SELECT 출연.영화명, 영화.배우명, 출연.출연료\nFROM 배우, 영화, 출연\nWHERE 출연료 >= 8888\nAND 출연.영화번호 = 영화.영화번호\nAND 출연.배우번호 = 배우.배우번호;","SELECT 영화.영화명, 배우.배우명, 출연료\nFROM 영화, 배우, 출연\nWHERE 출연.출연료 > 8888\nAND 출연.영화번호 = 영화.영화번호\nAND 영화.영화번호 = 배우.배우번호;","SELECT 영화명, 배우명, 출연료\nFROM 배우, 영화, 출연\nWHERE 출연료 >= 8888\nAND 영화번호 = 영화.영화번호\nAND 배우번호 = 배우.배우번호;","SELECT 영화.영화명, 배우.배우명, 출연료\nFROM 배우, 영화, 출연\nWHERE 출연료 >= 8888\nAND 출연.영화번호 = 영화.영화번호\nAND 출연.배우번호 = 배우.배우번호;"],"a":3,"e":"영화명은 영화 테이블, 배우명은 배우 테이블에 있다. 출연-영화는 영화번호로, 출연-배우는 배우번호로 조인해야 한다.","src":"핵심기출 · 2과목 34번","w":["출연에는 영화명이 없고 영화에는 배우명이 없음","영화번호 = 배우번호로 조인하는 잘못된 조건","영화번호, 배우번호가 여러 테이블에 있어 테이블명 없이 쓰면 모호성 에러",""],"kc":"2-34","box":["배우(__배우번호__, 배우명, 성별)","영화(__영화번호__, 영화명, 제작년도)","출연(__배우번호__, __영화번호__, 출연료)"]},{"id":1737,"c":"s13","d":3,"q":"아래에서 JOIN에 대한 설명으로 가장 적절한 것은?","code":null,"o":["(가), (다), (라)","(가), (나), (다)","(가), (나), (다), (라)","(가), (다), (라), (마)"],"a":3,"e":"(나)가 틀렸다. 옵티마이저는 FROM 절 테이블이 아무리 많아도 항상 2개씩 짝지어 조인한다. 나머지 (가)(다)(라)(마)는 맞는 설명.","src":"핵심기출 · 2과목 35번","w":["(마)도 맞는 설명이라 포함돼야 함","(나)는 틀린 설명","(나)는 틀렸고 (마)가 빠짐",""],"kc":"2-35","box":["(가) 일반적으로 조인은 PK와 FK값의 연관성에 의해 성립된다.","(나) DBMS 옵티마이저는 FROM 절에 나열된 테이블들을 임의로 3개 정도씩 묶어서 조인을 처리한다.","(다) EQUI JOIN은 조인에 관여하는 테이블 간의 칼럼 값들이 정확하게 일치하는 경우에 사용되는 방법이다.","(라) EQUI JOIN은 '=' 연산자에 의해서만 수행되며, 그 이외의 비교 연산자를 사용하는 경우에는 모두 NON EQUI JOIN이다.","(마) 대부분 NON EQUI JOIN을 수행할 수 있지만, 때로는 설계상의 이유로 수행이 불가능한 경우도 있다."]},{"id":1738,"c":"s13","d":2,"q":"아래 SQL의 실행 결과로 가장 적절한 것은?","code":["SELECT COUNT(*) CNT","FROM EMP_TBL A, RULE_TBL B","WHERE A.ENAME LIKE B.RULE;"],"o":["0","2","4","6"],"a":2,"e":"LIKE로 조인하면 규칙마다 매칭되는 행이 나온다. S%: SMITH, SCOTT. %T%: SMITH, SCOTT(ALLEN엔 T가 없음). 총 4건.","src":"핵심기출 · 2과목 36번","w":["매칭되는 행이 있음","규칙 하나만 계산한 값","","EMP 3건 × RULE 2건 전부(CROSS JOIN 결과)"],"kc":"2-36","tables":[{"name":"EMP_TBL","cols":["EMPNO","ENAME"],"rows":[["1000","SMITH"],["1050","ALLEN"],["1100","SCOTT"]]},{"name":"RULE_TBL","cols":["RULE_NO","RULE"],"rows":[["1","S%"],["2","%T%"]]}]},{"id":1739,"c":"s02","d":1,"q":"순수 관계 연산자로 가장 적절하지 않은 것은?","code":null,"o":["SELECT","UPDATE","JOIN","DIVIDE"],"a":1,"e":"순수 관계 연산자는 SELECT, PROJECT, JOIN, DIVIDE. UPDATE는 관계 연산자가 아니라 SQL DML 문장이다.","src":"핵심기출 · 2과목 37번","w":["SELECT는 순수 관계 연산자","","JOIN은 순수 관계 연산자","DIVIDE는 순수 관계 연산자(SQL로는 구현 안 됨)"],"kc":"2-37"},{"id":1740,"c":"s22","d":4,"q":"아래를 참고할 때 가장 적절한 SQL은?","code":null,"o":["SELECT C.컨텐츠ID, C.컨텐츠명\nFROM 고객 A INNER JOIN 추천컨텐츠 B\nON (A.고객ID = B.고객ID) INNER JOIN 컨텐츠 C\nON (B.컨텐츠ID = C.컨텐츠ID)\nWHERE A.고객ID = #custId#\nAND B.추천대상일자 = TO_CHAR(SYSDATE, 'YYYY.MM.DD')\nAND NOT EXISTS (SELECT X.컨텐츠ID\n                FROM 비선호컨텐츠 X\n                WHERE X.고객ID = B.고객ID);","SELECT C.컨텐츠ID, C.컨텐츠명\nFROM 고객 A INNER JOIN 추천컨텐츠 B\nON (A.고객ID = #custId# AND A.고객ID = B.고객ID) INNER JOIN 컨텐츠 C\nON (B.컨텐츠ID = C.컨텐츠ID) RIGHT OUTER JOIN 비선호컨텐츠 D\nON (B.고객ID = D.고객ID AND B.컨텐츠ID = D.컨텐츠ID)\nWHERE B.추천대상일자 = TO_CHAR(SYSDATE, 'YYYY.MM.DD')\nAND B.컨텐츠ID IS NOT NULL;","SELECT C.컨텐츠ID, C.컨텐츠명\nFROM 고객 A INNER JOIN 추천컨텐츠 B\nON (A.고객ID = B.고객ID) INNER JOIN 컨텐츠 C\nON (B.컨텐츠ID = C.컨텐츠ID) LEFT OUTER JOIN 비선호컨텐츠 D\nON (B.고객ID = D.고객ID AND B.컨텐츠ID = D.컨텐츠ID)\nWHERE A.고객ID = #custId#\nAND B.추천대상일자 = TO_CHAR(SYSDATE, 'YYYY.MM.DD')\nAND D.컨텐츠ID IS NOT NULL;","SELECT C.컨텐츠ID, C.컨텐츠명\nFROM 고객 A INNER JOIN 추천컨텐츠 B\nON (A.고객ID = #custId# AND A.고객ID = B.고객ID) INNER JOIN 컨텐츠 C\nON (B.컨텐츠ID = C.컨텐츠ID)\nWHERE B.추천대상일자 = TO_CHAR(SYSDATE, 'YYYY.MM.DD')\nAND NOT EXISTS (SELECT X.컨텐츠ID\n                FROM 비선호컨텐츠 X\n                WHERE X.고객ID = B.고객ID\n                AND X.컨텐츠ID = B.컨텐츠ID);"],"a":3,"e":"오늘 추천대상인 컨텐츠 중 고객이 비선호로 등록한 컨텐츠만 빼야 한다. ④는 NOT EXISTS 안에서 고객ID와 컨텐츠ID 둘 다 맞춰 정확히 그 컨텐츠만 제외한다.","src":"핵심기출 · 2과목 38번","w":["NOT EXISTS에 컨텐츠ID 조건이 없어 비선호가 하나라도 있으면 그 고객의 추천이 전부 빠짐","비선호컨텐츠 기준 RIGHT OUTER JOIN이라 비선호에 등록된 것만 남음","LEFT OUTER JOIN 후 IS NOT NULL이면 오히려 비선호 컨텐츠만 추출(IS NULL이어야 함)",""],"kc":"2-38","box":["[설명]","우리는 매일 배치작업을 통하여 고객에게 추천할 컨텐츠를 생성하고 고객에게 추천서비스를 제공한다.","추천 컨텐츠 엔터티에서 언제 추천을 해야 하는지를 정의하는 추천대상일자가 있어 해당일자에만 컨텐츠를 추천해야 한다. 또한 고객이 컨텐츠를 추천 받았을 때 '선호하는 컨텐츠가 아닌 경우에는 고객이 비선호 컨텐츠로 분류하여 더 이상 추천 받기를 원하지 않는다.' 그러므로 우리는 비선호 컨텐츠 엔터티에 등록된 데이터에 대해서는 추천을 수행하지 않아야 한다.","※ 배치작업이란? 어떤 처리를 연속적으로 하는 것이 아니고 일정량씩 나누어 처리하는 경우 그 일정량을 배치(batch)라고 한다. 배치의 원뜻은 한 묶음이라는 의미다. [기계공학용어사전]","예) 상품을 주문하는 로직은 그 당시에 발생하는 트랜잭션에 대한 처리이므로 배치작업이라 표현하지는 않는다. 하지만 상품별 주문량을 집계하는 로직의 경우 특정조건(기간 등)으로 일괄처리를 해야하므로 배치작업이라 표현할 수 있다."],"imgAlt":"고객(고객ID / 고객명, 나이) ┼──○< 추천컨텐츠(고객ID(FK), 컨텐츠ID(FK) / 추천대상일자) >○──┼ 컨텐츠(컨텐츠ID / 컨텐츠명); 고객 ┼──○< 비선호컨텐츠(고객ID(FK), 컨텐츠ID(FK) / 등록일시) >○──┼ 컨텐츠","img":"data/kc/2-38.jpg"},{"id":1741,"c":"s13","d":3,"q":"아래에 대한 설명으로 가장 적절한 것은?","code":null,"o":["제품, 생산제품, 생산라인 엔터티를 INNER JOIN하기 위해서 생산제품 엔터티는 WHERE 절에 최소 3번 나타나야 한다.","제품과 생산라인 엔터티를 JOIN 시 적절한 JOIN 조건이 없으므로 카티시안 곱(Cartesian Product)이 발생한다.","제품과 생산라인 엔터티에는 생산제품과 대응되지 않는 레코드는 없다.","특정 생산라인번호에서 생산되는 제품의 제품명을 알기 위해서는 제품, 생산제품, 생산라인까지 3개 엔터티의 INNER JOIN이 필요하다."],"a":1,"e":"제품과 생산라인 사이에는 바로 이어 주는 공통 컬럼이 없다. 둘만 조인하면 조인 조건을 걸 수 없어 카티시안 곱이 생기고, 생산제품을 거쳐야 제대로 연결된다.","src":"핵심기출 · 2과목 39번","w":["생산제품은 WHERE 절에 최소 2번(제품과 1번, 생산라인과 1번)","","생산제품 쪽이 선택(○)이라 대응되지 않는 레코드가 있을 수 있음","제품명은 제품과 생산제품 2개만 조인하면 됨(라인번호가 생산제품에 있음)"],"kc":"2-39","imgAlt":"제품(제품코드 / 제품명, 제품유형코드, 단위) ┼──○< 생산제품(라인번호(FK), 제품코드(FK)) >○──┼ 생산라인(라인번호 / 최초가동일자)","img":"data/kc/2-39.jpg"},{"id":1742,"c":"s11","d":2,"q":"아래 SQL의 빈칸 ㉠, ㉡에 들어갈 내용으로 가장 적절한 것은?","code":["SELECT A.이름, A.등급","FROM 고객 A","( ㉠ )","GROUP BY A.이름, A.등급","( ㉡ );"],"o":["㉠ INNER JOIN 구매정보 B ON A.고객번호=B.고객번호\n㉡ HAVING SUM(B.구매번호) >=3","㉠ INNER JOIN 구매정보 B ON A.고객번호=B.고객번호\n㉡ HAVING COUNT(B.구매번호) >=3","㉠ LEFT OUTER JOIN 구매정보 B ON A.고객번호=B.고객번호\n㉡ HAVING SUM(B.구매번호) >=3","㉠ INNER JOIN 구매정보 B ON A.고객번호=B.고객번호\n㉡ WHERE B.구매번호 >=3"],"a":1,"e":"구매 이력이 있어야 하니 INNER JOIN, 구매 횟수 3회 이상은 HAVING COUNT(B.구매번호) >= 3.","src":"핵심기출 · 2과목 40번","w":["SUM(구매번호)는 번호의 합이지 횟수가 아님","","LEFT OUTER JOIN이면 구매 이력 없는 고객도 붙고, SUM도 틀림","WHERE는 그룹 조건을 못 거는 데다 구매번호>=3은 의미가 다름"],"kc":"2-40","box":["[테이블]","고객(__고객번호__, 이름, 등급), 구매정보(__구매번호__, 구매금액, 고객번호)","* 구매정보 테이블의 고객번호는 고객 테이블의 고객번호를 참조하는 외래키(Foreign Key)이다.","[조건]","구매 이력이 있는 고객 중 구매 횟수가 3회 이상인 고객의 이름과 등급을 출력"]},{"id":1743,"c":"s13","d":3,"q":"아래를 참고할 때 시간대별사용량 테이블을 기반으로 고객별 사용금액을 출력하는 SQL로 가장 적절한 것은?","code":null,"o":["SELECT A.고객ID, A.고객명, SUM(B.사용량 * C.단가) AS 사용금액\nFROM 고객 A INNER JOIN 시간대별사용량 B\nON (A.고객ID = B.고객ID) INNER JOIN 시간대구간 C\nON (B.사용시간대 <= C.시작시간대 AND B.사용시간대 >= C.종료시간대)\nGROUP BY A.고객ID, A.고객명\nORDER BY A.고객ID, A.고객명;","SELECT A.고객ID, A.고객명, SUM(B.사용량 * C.단가) AS 사용금액\nFROM 고객 A INNER JOIN 시간대별사용량 B INNER JOIN 시간대구간 C\nON (A.고객ID = B.고객ID AND B.사용시간대\n    BETWEEN C.시작시간대 AND C.종료시간대)\nGROUP BY A.고객ID, A.고객명\nORDER BY A.고객ID, A.고객명;","SELECT A.고객ID, A.고객명, SUM(B.사용량 * C.단가) AS 사용금액\nFROM 고객 A INNER JOIN 시간대별사용량 B\nON (A.고객ID = B.고객ID) INNER JOIN 시간대구간 C\nON B.사용시간대 BETWEEN C.시작시간대 AND C.종료시간대\nGROUP BY A.고객ID, A.고객명\nORDER BY A.고객ID, A.고객명;","SELECT A.고객ID, A.고객명, SUM(B.사용량 * C.단가) AS 사용금액\nFROM 고객 A INNER JOIN 시간대별사용량 B\nON (A.고객ID = B.고객ID) BETWEEN JOIN 시간대구간 C\nGROUP BY A.고객ID, A.고객명\nORDER BY A.고객ID, A.고객명;"],"a":2,"e":"사용시간대가 시작~종료 시간대 사이에 들어가면 되니 BETWEEN C.시작시간대 AND C.종료시간대로 NON EQUI JOIN 하면 된다.","src":"핵심기출 · 2과목 41번","w":["부등호가 반대(시작 이상, 종료 이하여야 함)","INNER JOIN을 ON 없이 연달아 쓰면 구문 오류","","BETWEEN JOIN이라는 구문은 없음"],"kc":"2-41","imgAlt":"시간대구간(시작시간대, 종료시간대 / 단가)   시간대별사용량(고객ID(FK), 사용시간대 / 사용량) >○──┼ 고객(고객ID / 고객명, 생년월일)","img":"data/kc/2-41.jpg"},{"id":1744,"c":"s14","d":3,"q":"실행 결과가 다른 하나는?","code":null,"o":["SELECT T.REGION_NAME, T.TEAM_NAME, T.STADIUM_ID, S.STADIUM_NAME\nFROM TEAM T INNER JOIN STADIUM S\nUSING (T.STADIUM_ID = S.STADIUM_ID);","SELECT TEAM.REGION_NAME, TEAM.TEAM_NAME, TEAM.STADIUM_ID, STADIUM.STADIUM_NAME\nFROM TEAM INNER JOIN STADIUM\nON (TEAM.STADIUM_ID = STADIUM.STADIUM_ID);","SELECT T.REGION_NAME, T.TEAM_NAME, T.STADIUM_ID, S.STADIUM_NAME\nFROM TEAM T, STADIUM S\nWHERE T.STADIUM_ID = S.STADIUM_ID;","SELECT TEAM.REGION_NAME, TEAM.TEAM_NAME, TEAM.STADIUM_ID, STADIUM.STADIUM_NAME\nFROM TEAM, STADIUM\nWHERE TEAM.STADIUM_ID = STADIUM.STADIUM_ID;"],"a":0,"e":"USING 절에는 컬럼명만 쓴다. USING (T.STADIUM_ID = S.STADIUM_ID)처럼 접두사·조건식을 쓰면 문법 오류. USING (STADIUM_ID)로 써야 하고 SELECT에서도 접두사 없이 STADIUM_ID.","src":"핵심기출 · 2과목 42번","w":["","INNER JOIN ... ON, 정상","WHERE 등가 조인, 정상","테이블명 그대로 WHERE 조인, 정상"],"kc":"2-42"},{"id":1745,"c":"s14","d":1,"q":"아래 두 SQL이 같은 결과를 출력할 때, 빈칸 ㉠에 들어갈 내용으로 가장 적절한 것은?","code":["-- SQL(1)","SELECT ENAME, DNAME","FROM   EMP, DEPT","ORDER  BY ENAME;","","-- SQL(2)","SELECT ENAME, DNAME","FROM   EMP ( ㉠ ) DEPT","ORDER  BY ENAME;"],"o":["FULL OUTER JOIN","SELF JOIN","NATURAL JOIN","CROSS JOIN"],"a":3,"e":"조인 조건 없이 FROM EMP, DEPT = 모든 조합 = CROSS JOIN.","src":"핵심기출 · 2과목 43번","w":["FULL OUTER JOIN은 ON 조건이 필요","SELF JOIN은 같은 테이블끼리 조인","NATURAL JOIN은 같은 이름 컬럼(DEPTNO)으로 등가 조인",""],"kc":"2-43"},{"id":1746,"c":"s16","d":4,"q":"아래를 참고할 때 SQL 실행 결과로 가장 적절한 것은?","code":["SELECT A.고객번호, A.고객명, B.단말기ID, B.단말기명, C.OSID, C.OS명","FROM   고객 A LEFT OUTER JOIN 단말기 B","ON     (A.고객번호 IN (11000, 12000) AND A.단말기ID = B.단말기ID)","       LEFT OUTER JOIN OS C","ON     (B.OSID = C.OSID)","ORDER BY A.고객번호;"],"o":[{"cols":["고객번호","고객명","단말기ID","단말기명","OSID","OS명"],"rows":[["11000","홍길동","1000","A1000","100","Android"],["12000","강감찬","NULL","NULL","NULL","NULL"],["13000","이순신","NULL","NULL","NULL","NULL"],["14000","안중근","NULL","NULL","NULL","NULL"],["15000","고길동","NULL","NULL","NULL","NULL"],["16000","이대로","NULL","NULL","NULL","NULL"]]},{"cols":["고객번호","고객명","단말기ID","단말기명","OSID","OS명"],"rows":[["11000","홍길동","1000","A1000","100","Android"],["12000","강감찬","NULL","NULL","NULL","NULL"]]},{"cols":["고객번호","고객명","단말기ID","단말기명","OSID","OS명"],"rows":[["11000","홍길동","1000","A1000","100","Android"]]},{"cols":["고객번호","고객명","단말기ID","단말기명","OSID","OS명"],"rows":[["11000","홍길동","1000","A1000","100","Android"],["12000","강감찬","NULL","NULL","NULL","NULL"],["13000","이순신","NULL","NULL","NULL","NULL"],["14000","안중근","3000","C3000","200","iOS"],["15000","고길동","4000","D4000","300","Bada"],["16000","이대로","4000","D4000","300","Bada"]]}],"a":0,"e":"고객번호 IN (11000, 12000) 조건이 WHERE가 아니라 ON에 있다. 그래서 고객은 6명 모두 나오고, 단말기 조인 대상만 11000·12000으로 제한된다. 12000은 단말기ID가 NULL이라 매칭 없음 → 11000만 단말기·OS 정보가 붙는다.","src":"핵심기출 · 2과목 44번","w":["","WHERE에 IN 조건이 있었다면 나올 결과","INNER JOIN처럼 매칭된 행만 남긴 결과","ON의 IN 조건을 무시한 결과"],"kc":"2-44","tables":[{"name":"OS","cols":["OSID(PK)","OS명"],"rows":[["100","Android"],["200","iOS"],["300","Bada"]]},{"name":"단말기","cols":["단말기ID(PK)","단말기명","OSID(FK)"],"rows":[["1000","A1000","100"],["2000","B2000","100"],["3000","C3000","200"],["4000","D3000","300"]]},{"name":"고객","cols":["고객번호(PK)","고객명","단말기ID(FK)"],"rows":[["11000","홍길동","1000"],["12000","강감찬","NULL"],["13000","이순신","NULL"],["14000","안중근","3000"],["15000","고길동","4000"],["16000","이대로","4000"]]}],"note":"원본 그대로 옮김: 단말기 테이블은 4000→D3000, 보기 ④는 D4000으로 인쇄됨","otype":"table"},{"id":1747,"c":"s16","d":3,"q":"아래 SQL에서 실행 결과가 같은 것은?","code":["(가) SELECT A.ID, B.ID","    FROM TBL1 A FULL OUTER JOIN TBL2 B","    ON A.ID = B.ID","","(나) SELECT A.ID, B.ID","    FROM TBL1 A LEFT OUTER JOIN TBL2 B","    ON A.ID = B.ID","    UNION","    SELECT A.ID, B.ID","    FROM TBL1 A RIGHT OUTER JOIN TBL2 B","    ON A.ID = B.ID","","(다) SELECT A.ID, B.ID","    FROM TBL1 A, TBL2 B","    WHERE A.ID = B.ID","    UNION ALL","    SELECT A.ID, NULL","    FROM TBL1 A","    WHERE NOT EXISTS (SELECT 1 FROM TBL2 B WHERE A.ID = B.ID)","    UNION ALL","    SELECT NULL, B.ID","    FROM TBL2 B","    WHERE NOT EXISTS (SELECT 1 FROM TBL1 A WHERE B.ID = A.ID)"],"o":["(가), (나)","(가), (다)","(나), (다)","(가), (나), (다)"],"a":3,"e":"(나) LEFT ∪ RIGHT, (다) INNER + 왼쪽에만 있는 것 + 오른쪽에만 있는 것. 둘 다 FULL OUTER JOIN과 같은 결과.","src":"핵심기출 · 2과목 45번","w":["(다)도 같은 결과","(나)도 같은 결과","(가)도 같은 결과",""],"kc":"2-45"},{"id":1748,"c":"s16","d":2,"q":"아래에서 EMP 테이블과 DEPT 테이블을 LEFT, FULL, RIGHT 외부조인(OUTER JOIN)하면 생성되는 결과 건수로 가장 적절한 것은?","code":null,"o":["3건, 5건, 4건","4건, 5건, 3건","3건, 4건, 4건","3건, 4건, 5건"],"a":0,"e":"EMP.C와 DEPT.C로 조인. 매칭되는 건 w 하나(EMP 2건). LEFT: EMP 3건(y는 NULL). FULL: 매칭 2 + EMP 단독 1 + DEPT 단독 z, v 2 = 5건. RIGHT: 매칭 2 + z, v = 4건.","src":"핵심기출 · 2과목 46번","w":["","LEFT가 4건이 될 수 없음","FULL이 5건","RIGHT는 4건"],"kc":"2-46","tables":[{"name":"EMP","cols":["A","B","C"],"rows":[["1","b","w"],["3","d","w"],["5","y","y"]]},{"name":"DEPT","cols":["C","D","E"],"rows":[["w","1","10"],["z","4","11"],["v","2","22"]]}],"note":"원본에는 조인 칼럼 표시가 없지만, 두 테이블의 공통 칼럼 C(EMP.C = DEPT.C)로 조인하는 문제"},{"id":1749,"c":"s16","d":1,"q":"DEPT와 EMP를 조인하되 사원이 없는 부서 정보도 같이 출력하고자 할 때, 아래 SQL의 빈칸 ㉠에 들어갈 내용으로 가장 적절한 것은?","code":["SELECT E.ENAME, D.DEPTNO, D.DNAME","FROM   DEPT D ( ㉠ ) EMP E","ON     D.DEPTNO = E.DEPTNO;"],"o":["LEFT OUTER JOIN","RIGHT OUTER JOIN","FULL OUTER JOIN","INNER JOIN"],"a":0,"e":"사원이 없는 부서도 나와야 하니 DEPT를 기준으로 → DEPT D LEFT OUTER JOIN EMP E.","src":"핵심기출 · 2과목 47번","w":["","RIGHT면 EMP 기준","FULL이면 부서 없는 사원까지 나옴","INNER면 사원 없는 부서가 빠짐"],"kc":"2-47"},{"id":1750,"c":"s16","d":3,"q":"아래 SQL의 실행 결과로 가장 적절한 것은?","code":["SELECT *","FROM TAB1 A LEFT OUTER JOIN TAB2 B","  ON ( A.C1 = B.C1 AND B.C2 BETWEEN 1 AND 3)"],"o":[{"cols":["C1","C2","C1","C2"],"rows":[["A","1","NULL","NULL"],["B","2","B","2"],["C","3","C","3"],["D","4","D","4"],["E","5","NULL","NULL"]]},{"cols":["C1","C2","C1","C2"],"rows":[["A","1","NULL","NULL"],["B","2","B","2"],["C","3","C","3"],["D","4","NULL","NULL"],["E","5","NULL","NULL"]]},{"cols":["C1","C2","C1","C2"],"rows":[["A","1","NULL","NULL"],["B","2","B","2"],["C","3","C","3"]]},{"cols":["C1","C2","C1","C2"],"rows":[["A","1","NULL","NULL"],["B","2","B","2"],["C","3","C","3"],["D","4","D","4"]]}],"a":1,"e":"OUTER JOIN에서 ON 조건은 '어떤 행을 붙일지'만 정한다. 기준 TAB1은 5건 모두 나오고, TAB2에서 C2가 1~3인 B, C만 붙는다. D는 C2=4라 붙지 않아 NULL.","src":"핵심기출 · 2과목 48번","w":["D 행에 TAB2가 붙으면 안 됨(C2=4)","","ON 조건을 WHERE처럼 적용해 기준 테이블 행을 줄인 결과","ON 조건을 무시한 결과에서 E만 빠진 형태"],"kc":"2-48","tables":[{"name":"TAB1","cols":["C1","C2"],"rows":[["A","1"],["B","2"],["C","3"],["D","4"],["E","5"]]},{"name":"TAB2","cols":["C1","C2"],"rows":[["B","2"],["C","3"],["D","4"]]}],"otype":"table"},{"id":1751,"c":"s17","d":3,"q":"아래의 오라클 SQL을 동일한 결과를 출력하는 ANSI 표준 구문으로 변경하고자 할 때 가장 적절한 SQL은?","code":["SELECT A.게시판ID, A.게시판명, COUNT(B.게시글ID) AS CNT","FROM   게시판 A, 게시글 B","WHERE  A.게시판ID = B.게시판ID(+)","AND    B.삭제여부(+) = 'N'","AND    A.사용여부 = 'Y'","GROUP BY A.게시판ID, A.게시판명","ORDER BY A.게시판ID;"],"o":["SELECT A.게시판ID, A.게시판명, COUNT(B.게시글ID) AS CNT\nFROM 게시판 A LEFT OUTER JOIN 게시글 B\nON (A.게시판ID = B.게시판ID AND B.삭제여부 = 'N')\nWHERE A.사용여부 = 'Y'\nGROUP BY A.게시판ID, A.게시판명\nORDER BY A.게시판ID;","SELECT A.게시판ID, A.게시판명, COUNT(B.게시글ID) AS CNT\nFROM 게시판 A LEFT OUTER JOIN 게시글 B\nON (A.게시판ID = B.게시판ID AND A.사용여부 = 'Y')\nWHERE B.삭제여부 = 'N'\nGROUP BY A.게시판ID, A.게시판명\nORDER BY A.게시판ID;","SELECT A.게시판ID, A.게시판명, COUNT(B.게시글ID) AS CNT\nFROM 게시판 A LEFT OUTER JOIN 게시글 B\nON (A.게시판ID = B.게시판ID)\nWHERE A.사용여부 = 'Y'\nAND B.삭제여부 = 'N'\nGROUP BY A.게시판ID, A.게시판명\nORDER BY A.게시판ID;","SELECT A.게시판ID, A.게시판명, COUNT(B.게시글ID) AS CNT\nFROM 게시판 A RIGHT OUTER JOIN 게시글 B\nON (A.게시판ID = B.게시판ID AND A.사용여부 = 'Y' AND\n    B.삭제여부 = 'N')\nGROUP BY A.게시판ID, A.게시판명\nORDER BY A.게시판ID;"],"a":0,"e":"(+)가 붙은 쪽(게시글)이 Inner 쪽이다. Inner 쪽 조건 B.삭제여부='N'은 ON 절에, Outer 쪽 조건 A.사용여부='Y'는 WHERE 절에 둬야 같은 결과.","src":"핵심기출 · 2과목 49번","w":["","Outer 쪽(게시판) 조건을 ON에 넣으면 사용여부 N인 게시판도 나옴","Inner 쪽 조건을 WHERE에 두면 게시글 없는 게시판이 빠짐(사실상 INNER JOIN)","RIGHT OUTER로 기준이 바뀜"],"kc":"2-49","imgAlt":"게시판(게시판ID / 게시판명, 등록일시, 사용여부) ┼- - -○< 게시글(게시글ID / 게시판ID(FK), 제목, 내용, 등록일시, 등록자명, 삭제여부)","img":"data/kc/2-49.jpg"},{"id":1752,"c":"s10","d":2,"q":"아래에 대한 설명으로 가장 적절한 것은? (단, 칼럼의 타입은 NUMBER이다.)","code":null,"o":["SELECT SUM(COL2) FROM TAB1 의 결과는 NULL이다.","SELECT SUM(COL1 + COL2 + COL3) FROM TAB1 의 결과는 185이다.","SELECT SUM(COL2 + COL3) FROM TAB1 의 결과는 90이다.","SELECT SUM(COL2) + SUM(COL3) FROM TAB1 의 결과는 90이다."],"a":2,"e":"컬럼끼리 더할 때 NULL이 섞이면 결과가 NULL, SUM 같은 행 집계는 NULL을 빼고 더한다. COL2+COL3 → NULL, NULL, 90 → SUM 90.","src":"핵심기출 · 2과목 50번","w":["SUM(COL2) = 20+70 = 90","COL1+COL2+COL3는 앞 두 행이 NULL이라 50+70+20 = 140","","SUM(COL2)+SUM(COL3) = 90+20 = 110"],"kc":"2-50","tables":[{"name":"TAB1","cols":["COL1","COL2","COL3"],"rows":[["10","20","NULL"],["15","NULL","NULL"],["50","70","20"]]}],"note":"원본 표에는 테이블명이 없고, 보기에서 TAB1로 부름"},{"id":1753,"c":"s20","d":1,"q":"아래에서 설명하는 서브쿼리의 종류로 가장 적절한 것은?","code":null,"o":["단일 행(Single Row) 서브쿼리","다중 칼럼(Multi Column) 서브쿼리","다중 행(Multi Row) 서브쿼리","단일 칼럼(Single Column) 서브쿼리"],"a":1,"e":"여러 컬럼을 반환해 메인쿼리에서 동시에 비교 = 다중 컬럼 서브쿼리.","src":"핵심기출 · 2과목 51번","w":["단일 행: 결과가 1건 이하","","다중 행: 결과가 여러 건","단일 컬럼 서브쿼리는 이 분류에 없음"],"kc":"2-51","box":["서브쿼리의 실행 결과로 여러 칼럼을 반환한다. 메인쿼리의 조건절에 여러 칼럼을 동시에 비교할 수 있다. 서브쿼리와 메인쿼리에서 비교하고자 하는 칼럼 개수와 칼럼의 위치가 동일해야 한다."]},{"id":1754,"c":"s24","d":3,"q":"SQL 실행 결과가 다른 하나는?","code":null,"o":["SELECT COL1, SUM(COL2)\nFROM T1\nGROUP BY COL1\nUNION ALL\nSELECT NULL, SUM(COL2)\nFROM T1\nORDER BY 1 ASC;","SELECT COL1, SUM(COL2)\nFROM T1\nGROUP BY GROUPING SETS (COL1)\nORDER BY 1 ASC;","SELECT COL1, SUM(COL2)\nFROM T1\nGROUP BY ROLLUP (COL1)\nORDER BY 1 ASC;","SELECT COL1, SUM(COL2)\nFROM T1\nGROUP BY CUBE (COL1)\nORDER BY 1 ASC;"],"a":1,"e":"①③④는 COL1별 합계에 전체 합계 행(COL1 NULL)이 붙는다. 인자가 하나일 때 ROLLUP과 CUBE는 결과가 같다. ②는 GROUPING SETS(COL1)뿐이라 COL1별 합계만 나와 건수가 다르다.","src":"핵심기출 · 2과목 52번","w":["COL1별 + UNION ALL 전체 합계","","ROLLUP(COL1) = COL1별 + 총계","CUBE(COL1) = COL1별 + 총계"],"kc":"2-52"},{"id":1755,"c":"s23","d":1,"q":"SET OPERATOR 중에서 수학의 교집합과 같은 기능을 하는 연산자로 가장 적절한 것은?","code":null,"o":["UNION","INTERSECT","MINUS","EXCEPT"],"a":1,"e":"교집합 = INTERSECT.","src":"핵심기출 · 2과목 53번","w":["UNION은 합집합","","MINUS는 차집합(오라클)","EXCEPT는 차집합(SQL Server)"],"kc":"2-53"},{"id":1756,"c":"s23","d":2,"q":"집합 연산자에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["UNION 연산자는 합집합 결과에서 중복된 행을 하나의 행으로 만든다.","UNION ALL 연산자는 집합 간의 결과가 중복되지 않는 경우, UNION과 결과가 동일하다.","UNION 연산자를 사용한 SQL은 각각의 집합에 GROUP BY절을 사용할 수 있다.","UNION 연산자를 사용한 SQL은 각각의 집합에 ORDER BY절을 사용할 수 있다."],"a":3,"e":"집합 연산자를 쓰면 ORDER BY는 맨 마지막에 한 번만 쓸 수 있다. 각 집합마다 쓰는 건 안 된다.","src":"핵심기출 · 2과목 54번","w":["중복 행 하나로, 맞음","중복이 없으면 UNION ALL = UNION, 맞음","각 SELECT에 GROUP BY는 가능, 맞음",""],"kc":"2-54"},{"id":1757,"c":"s23","d":4,"q":"아래의 SQL과 실행 결과가 동일한 SQL은?","code":["SELECT A.서비스ID, B.서비스명, B.서비스URL","FROM   (SELECT 서비스ID","        FROM   서비스","        INTERSECT","        SELECT 서비스ID","        FROM   서비스이용) A, 서비스 B","WHERE  A.서비스ID = B.서비스ID;"],"o":["SELECT B.서비스ID, A.서비스명, A.서비스URL\nFROM 서비스 A, 서비스이용 B\nWHERE A.서비스ID = B.서비스ID;","SELECT X.서비스ID, X.서비스명, X.서비스URL\nFROM 서비스 X\nWHERE NOT EXISTS (SELECT 1\n                  FROM (SELECT 서비스ID\n                        FROM 서비스\n                        MINUS\n                        SELECT 서비스ID\n                        FROM 서비스이용) Y\n                  WHERE X.서비스ID = Y.서비스ID);","SELECT B.서비스ID, A.서비스명, A.서비스URL\nFROM 서비스 A LEFT OUTER JOIN 서비스이용 B\nON (A.서비스ID = B.서비스ID)\nWHERE B.서비스ID IS NULL\nGROUP BY B.서비스ID, A.서비스명, A.서비스URL;","SELECT A.서비스ID, A.서비스명, A.서비스URL\nFROM 서비스 A\nWHERE 서비스ID IN (SELECT 서비스ID\n                  FROM 서비스이용\n                  MINUS\n                  SELECT 서비스ID\n                  FROM 서비스);"],"a":1,"e":"원래 SQL은 이용된 적 있는 서비스를 뽑는다. ②는 (전체 서비스 MINUS 이용된 서비스) = 이용 안 된 서비스에 NOT EXISTS를 걸어서 결국 이용된 서비스만 남긴다.","src":"핵심기출 · 2과목 55번","w":["서비스이용과 1:N이라 이용 건수만큼 중복 출력","","IS NULL이라 이용 안 된 서비스만 나옴","MINUS 순서가 반대라 서비스에 없는 서비스ID(사실상 없음)를 찾음"],"kc":"2-55","imgAlt":"서비스(서비스ID / 서비스명, 서비스URL) ┼──○< 서비스이용(회원ID(FK), 서비스ID(FK) / 이용일시) >○──┼ 회원(회원ID / 회원명)","img":"data/kc/2-55.jpg"},{"id":1758,"c":"s23","d":3,"q":"아래를 참고할 때 SQL 실행 결과로 가장 적절한 것은?","code":["SELECT COL1, COL2, COUNT(*) AS CNT","FROM   (SELECT COL1, COL2","        FROM   TBL1","        UNION ALL","        SELECT COL1, COL2","        FROM   TBL2","        UNION","        SELECT COL1, COL2","        FROM   TBL1)","GROUP BY COL1, COL2;"],"o":[{"cols":["COL1","COL2","CNT"],"rows":[["AA","A1","1"],["AB","A2","1"],["AC","A3","1"],["AD","A4","1"]]},{"cols":["COL1","COL2","CNT"],"rows":[["AA","A1","2"],["AB","A2","2"],["AC","A3","1"],["AD","A4","1"]]},{"cols":["COL1","COL2","CNT"],"rows":[["AA","A1","3"],["AB","A2","3"],["AC","A3","1"],["AD","A4","1"]]},{"cols":["COL1","COL2","CNT"],"rows":[["AA","A1","3"],["AB","A2","3"],["AC","A3","2"],["AD","A4","2"]]}],"a":0,"e":"집합 연산자는 위에서부터 차례로 수행된다. TBL1 UNION ALL TBL2로 6행을 만든 뒤 마지막 UNION TBL1에서 중복이 전부 제거돼 AA·AB·AC·AD 각 1행. GROUP BY 해도 CNT는 모두 1.","src":"핵심기출 · 2과목 56번","w":["","UNION과 UNION ALL 순서가 바뀌면 나오는 결과","UNION ALL만 썼을 때 결과","잘못된 계산"],"kc":"2-56","tables":[{"name":"TBL1","cols":["COL1","COL2"],"rows":[["AA","A1"],["AB","A2"]]},{"name":"TBL2","cols":["COL1","COL2"],"rows":[["AA","A1"],["AB","A2"],["AC","A3"],["AD","A4"]]}],"otype":"table"},{"id":1759,"c":"s24","d":4,"q":"아래 SQL의 빈칸 ㉠에 들어갔을 때 그 결과가 다른 하나는?","code":["SELECT b.grade, a.job, SUM(a.sal) AS SUM_SAL, COUNT(*) AS CNT","FROM emp a, salgrade b","WHERE a.sal BETWEEN b.losal AND b.hisal","GROUP BY ( ㉠ );"],"o":["GROUPING SETS (grade, (job, grade))","ROLLUP (grade, job)","grade, ROLLUP (job)","grade, CUBE (job)"],"a":1,"e":"①③④는 grade별, (grade, job)별 소계만 나온다. ROLLUP(grade, job)은 여기에 전체 총계 행까지 붙어서 결과가 다르다.","src":"핵심기출 · 2과목 57번","w":["GROUPING SETS(grade, (job, grade)) = 결과와 같음","","grade, ROLLUP(job) = (grade, job) + (grade)","grade, CUBE(job) = (grade, job) + (grade), 인자가 하나라 ROLLUP과 같음"],"kc":"2-57","tables":[{"name":"emp","cols":["EMPNO","ENAME","JOB","SAL"],"rows":[["7521","WARD","SALESMAN","1250"],["7566","JONES","MANAGER","2975"],["7654","MARTIN","SALESMAN","1250"],["7782","CLARK","MANAGER","2450"],["7788","SCOTT","ANALYST","3000"],["7844","TURNER","SALESMAN","1500"],["7902","FORD","ANALYST","3000"],["7934","MILLER","CLERK","1300"]]},{"name":"salgrade","cols":["GRADE","LOSAL","HISAL"],"rows":[["1","700","1200"],["2","1201","1400"],["3","1401","2000"],["4","2001","3000"],["5","3001","9999"]]},{"name":"실행 결과","cols":["GRADE","JOB","SUM_SAL","CNT"],"rows":[["2","CLERK","1300","1"],["2","SALESMAN","2500","2"],["2","NULL","3800","3"],["3","SALESMAN","1500","1"],["3","NULL","1500","1"],["4","ANALYST","6000","2"],["4","MANAGER","5425","2"],["4","NULL","11425","4"]],"after":true}]},{"id":1760,"c":"s28","d":4,"q":"아래 실행 결과를 출력하는 SQL로 가장 적절하지 않은 것은? (단, DBMS는 오라클로 가정)","code":null,"o":["SELECT A.부서코드, A.사원번호, A.급여\n     , ROUND(RATIO_TO_REPORT(급여) OVER (PARTITION BY 부서코드),2) AS 급여비중\nFROM ( SELECT 사원번호, 이름, 부서코드, 급여\n            , SUM(급여) OVER (PARTITION BY 부서코드) AS 부서급여합\n       FROM 직원\n       WHERE 부서코드 IN ('MKT','HRD') ) A\nORDER BY A.부서코드, A.급여 DESC, A.사원번호;","SELECT A.부서코드, A.사원번호, A.급여\n     , ROUND(급여/부서급여합,2) AS 급여비중\nFROM ( SELECT 사원번호, 이름, 부서코드, 급여\n            , SUM(급여) OVER (PARTITION BY 부서코드) AS 부서급여합\n       FROM 직원\n       WHERE 부서코드 IN ('MKT','HRD') ) A\nORDER BY A.부서코드, A.급여 DESC, A.사원번호;","SELECT A.부서코드, A.사원번호, A.급여\n     , ROUND(급여/B.부서급여합,2) AS 급여비중\nFROM 직원 A\n   , ( SELECT 부서코드, SUM(급여) AS 부서급여합\n       FROM 직원\n       WHERE 부서코드 IN ('MKT','HRD')\n       GROUP BY 부서코드 ) B\nWHERE A.부서코드 = B.부서코드\nAND A.부서코드 IN ('MKT','HRD')\nORDER BY A.부서코드, A.급여 DESC, A.사원번호;","SELECT A.부서코드, A.사원번호, A.급여\n     , ROUND(급여/부서급여합,2) AS 급여비중\nFROM ( SELECT 사원번호, 이름, 부서코드, 급여\n            , SUM(급여) OVER (PARTITION BY 부서코드 ORDER BY 사원번호) AS 부서급여합\n       FROM 직원\n       WHERE 부서코드 IN ('MKT','HRD') ) A\nORDER BY A.부서코드, A.급여 DESC, A.사원번호 ;"],"a":3,"e":"④는 SUM(급여) OVER(PARTITION BY 부서코드 ORDER BY 사원번호)라 누적합이 된다. 부서급여합이 사원마다 달라져 급여비중이 틀어진다.","src":"핵심기출 · 2과목 58번","w":["RATIO_TO_REPORT = 파티션 합 대비 비율, 결과와 같음","급여/부서 전체 합, 결과와 같음","부서별 합계 인라인 뷰와 조인, 결과와 같음",""],"kc":"2-58","tables":[{"name":"직원","cols":["사원번호","이름","부서코드","입사일","급여"],"rows":[["A001","홍길동","GEN","2019-01-01","1200000"],["A002","일지매","MKT","2019-01-12","1830000"],["A003","심청","MKT","2018-09-05","2340000"],["A004","고길동","HRD","2011-07-07","3500000"],["A005","이국","ACC","2007-10-13","2300000"],["A006","동치성","STG","2004-12-14","3560000"],["A007","손오공","MKT","2015-11-10","4500000"],["A008","사오정","HRD","2018-07-18","3200000"],["A009","저팔계","SYS","2011-03-03","2180000"],["A010","장길산","SYS","2019-01-23","1780000"]]},{"name":"실행 결과","cols":["부서코드","사원번호","급여","급여비중"],"rows":[["HRD","A004","3500000","0.52"],["HRD","A008","3200000","0.48"],["MKT","A007","4500000","0.52"],["MKT","A003","2340000","0.27"],["MKT","A002","1830000","0.21"]]}]},{"id":1761,"c":"s23","d":3,"q":"아래에 대한 설명으로 가장 적절한 것은? (단, 시스템적으로 회원기본정보와 회원상세정보는 1:1, 양쪽 필수 관계임을 보장한다.)","code":null,"o":["회원ID 칼럼을 대상으로 (회원기본정보 EXCEPT 회원상세정보) 연산을 수행하면 회원상세정보가 등록되지 않은 회원ID가 추출된다.","회원ID 칼럼을 대상으로 (회원기본정보 UNION ALL 회원상세정보) 연산을 수행한 결과의 건수는 회원기본정보의 전체건수와 동일하다.","회원ID 칼럼을 대상으로 (회원기본정보 INTERSECT 회원상세정보) 연산을 수행한 결과의 건수와 두 테이블을 회원ID로 JOIN 연산을 수행한 결과의 건수는 동일하다.","회원ID 칼럼을 대상으로 (회원기본정보 INTERSECT 회원상세정보) 연산을 수행한 결과와 (회원기본정보 UNION 회원상세정보) 연산을 수행한 결과는 다르다."],"a":2,"e":"1:1 양쪽 필수가 보장되니 두 테이블의 회원ID 집합은 똑같다. INTERSECT 결과 건수와 회원ID 조인 결과 건수는 같다.","src":"핵심기출 · 2과목 59번","w":["두 집합이 같으니 EXCEPT 결과는 항상 공집합","UNION ALL은 회원기본정보 건수의 2배","","INTERSECT 결과와 UNION 결과는 같음"],"kc":"2-59","imgAlt":"회원기본정보(회원ID) ┼──┼ 회원상세정보(회원ID(FK)), 관계선에 1 표시","img":"data/kc/2-59.jpg"},{"id":1762,"c":"s29","d":3,"q":"아래 SQL을 수행할 경우 정렬 순서상 3번째 표시될 값은?","code":["SELECT C3","FROM TAB1","START WITH C2 IS NULL","CONNECT BY PRIOR C1 = C2","ORDER SIBLINGS BY C3 DESC"],"o":["A","B","C","D"],"a":1,"e":"루트는 C2가 NULL인 1(A). 자식 2(B), 3(C)를 C3 DESC로 정렬하면 C가 먼저 오고, 그 다음 B, B의 자식 4(D). 순서 A, C, B, D → 3번째는 B.","src":"핵심기출 · 2과목 60번","w":["A는 1번째","","C는 2번째","D는 4번째"],"kc":"2-60","tables":[{"name":"TAB1","cols":["C1","C2","C3"],"rows":[["1","NULL","A"],["2","1","B"],["3","1","C"],["4","2","D"]]}]},{"id":1763,"c":"s29","d":2,"q":"오라클 계층형 질의에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["START WITH 절은 계층 구조의 시작점을 지정하는 구문이다.","ORDER SIBLINGS BY 절은 형제 노드 사이에서 정렬을 지정하는 구문이다.","순방향전개란 부모 노드로부터 자식 노드 방향으로 전개하는 것을 말한다.","루트 노드의 LEVEL 값은 0이다."],"a":3,"e":"오라클 계층형 질의에서 루트 노드의 LEVEL은 0이 아니라 1이다.","src":"핵심기출 · 2과목 61번","w":["START WITH = 시작점 지정, 맞음","ORDER SIBLINGS BY = 형제끼리 정렬, 맞음","순방향 = 부모→자식, 맞음",""],"kc":"2-61"},{"id":1764,"c":"s29","d":4,"q":"아래 SQL의 실행 결과로 가장 적절한 것은?","code":["SELECT 사원번호, 사원명, 입사일자, 매니저사원번호","FROM   사원","START WITH 매니저사원번호 IS NULL","CONNECT BY PRIOR 사원번호 = 매니저사원번호","AND 입사일자 BETWEEN '2013-01-01' AND '2013-12-31'","ORDER SIBLINGS BY 사원번호;"],"o":[{"cols":["사원번호","사원명","입사일자","매니저사원번호"],"rows":[["001","홍길동","2012-01-01","NULL"],["003","이순신","2013-01-01","001"],["004","이민정","2013-01-01","001"],["005","이병헌","2013-01-01","NULL"]]},{"cols":["사원번호","사원명","입사일자","매니저사원번호"],"rows":[["003","이순신","2013-01-01","001"],["004","이민정","2013-01-01","001"],["005","이병헌","2013-01-01","NULL"]]},{"cols":["사원번호","사원명","입사일자","매니저사원번호"],"rows":[["001","홍길동","2012-01-01","NULL"]]},{"cols":["사원번호","사원명","입사일자","매니저사원번호"],"rows":[["001","홍길동","2012-01-01","NULL"],["005","이병헌","2013-01-01","NULL"],["006","안성기","2014-01-01","005"],["007","이수근","2014-01-01","005"],["008","김병만","2014-01-01","005"]]}],"a":0,"e":"START WITH로 고른 루트(매니저 NULL인 001, 005)는 조건과 상관없이 결과에 들어간다. CONNECT BY의 입사일자 조건은 자식을 펼칠 때만 적용돼 001 밑의 003, 004만 붙고 002(2012년), 006~008(2014년)은 빠진다. 형제끼리 사원번호 순 정렬.","src":"핵심기출 · 2과목 62번","w":["","루트 001, 005가 빠질 수 없음","005 루트가 빠짐","입사일자 조건을 PRIOR 쪽(부모)에 건 것처럼 계산한 결과"],"kc":"2-62","tables":[{"name":"사원","cols":["사원번호","사원명","입사일자","매니저사원번호"],"rows":[["001","홍길동","2012-01-01","NULL"],["002","강감찬","2012-01-01","001"],["003","이순신","2013-01-01","001"],["004","이민정","2013-01-01","001"],["005","이병헌","2013-01-01","NULL"],["006","안성기","2014-01-01","005"],["007","이수근","2014-01-01","005"],["008","김병만","2014-01-01","005"]]}],"otype":"table"},{"id":1765,"c":"s29","d":2,"q":"계층형 질의문에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["SQL Server에서의 계층형 질의문은 CTE(Common Table Expression)를 재귀 호출함으로써 계층 구조를 전개한다.","SQL Server에서의 계층형 질의문은 앵커 멤버를 실행하여 기본 결과 집합을 만들고 이후 재귀 멤버를 지속적으로 실행한다.","오라클의 계층형 질의문에서 WHERE 절은 모든 전개를 진행한 이후 필터 조건으로서 조건을 만족하는 데이터만을 추출하는 데 활용된다.","오라클의 계층형 질의문에서 PRIOR 키워드는 CONNECT BY 절에만 사용할 수 있으며 'PRIOR 자식 = 부모' 형태로 사용하면 순방향 전개로 수행된다."],"a":3,"e":"PRIOR는 CONNECT BY 절 말고 SELECT, WHERE 절에서도 쓸 수 있다. 'CONNECT BY 절에만'이 틀렸다. 'PRIOR 자식 = 부모'가 순방향이라는 부분은 맞다.","src":"핵심기출 · 2과목 63번","w":["CTE 재귀 호출로 전개, 맞음","앵커 멤버 실행 후 재귀 멤버 반복, 맞음","WHERE는 전개가 끝난 뒤 필터, 맞음",""],"kc":"2-63"},{"id":1766,"c":"s29","d":4,"q":"아래 실행 결과를 출력하는 SQL로 가장 적절한 것은?","code":null,"o":["SELECT A.부서코드, A.부서명, A.상위부서코드, B.매출액, LVL\nFROM (SELECT 부서코드, 부서명, 상위부서코드, LEVEL AS LVL\n      FROM 부서\n      START WITH 부서코드 = '120'\n      CONNECT BY PRIOR 상위부서코드 = 부서코드\n      UNION\n      SELECT 부서코드, 부서명, 상위부서코드, LEVEL AS LVL\n      FROM 부서\n      START WITH 부서코드 = '120'\n      CONNECT BY 상위부서코드 = PRIOR 부서코드) A LEFT OUTER JOIN 매출 B\nON (A.부서코드 = B.부서코드)\nORDER BY A.부서코드;","SELECT A.부서코드, A.부서명, A.상위부서코드, B.매출액, LVL\nFROM (SELECT 부서코드, 부서명, 상위부서코드, LEVEL AS LVL\n      FROM 부서\n      START WITH 부서코드 = '100'\n      CONNECT BY 상위부서코드 = PRIOR 부서코드) A LEFT OUTER JOIN 매출 B\nON (A.부서코드 = B.부서코드)\nORDER BY A.부서코드;","SELECT A.부서코드, A.부서명, A.상위부서코드, B.매출액, LVL\nFROM (SELECT 부서코드, 부서명, 상위부서코드, LEVEL AS LVL\n      FROM 부서\n      START WITH 부서코드 = '121'\n      CONNECT BY PRIOR 상위부서코드 = 부서코드) A LEFT OUTER JOIN 매출 B\nON (A.부서코드 = B.부서코드)\nORDER BY A.부서코드;","SELECT A.부서코드, A.부서명, A.상위부서코드, B.매출액, LVL\nFROM (SELECT 부서코드, 부서명, 상위부서코드, LEVEL AS LVL\n      FROM 부서\n      START WITH 부서코드 = (\n            SELECT 부서코드\n            FROM 부서\n            WHERE 상위부서코드 IS NULL\n            START WITH 부서코드 = '120'\n            CONNECT BY PRIOR 상위부서코드 = 부서코드)\n      CONNECT BY 상위부서코드 = PRIOR 부서코드) A LEFT OUTER JOIN 매출 B\nON (A.부서코드 = B.부서코드)\nORDER BY A.부서코드;"],"a":0,"e":"결과에 100(LVL 2), 120(LVL 1), 121·122(LVL 2)가 나온다. 120에서 시작해 위로(역방향) 100까지, 아래로(순방향) 121·122까지 펼친 다음 UNION 한 ①이 정확히 이 결과.","src":"핵심기출 · 2과목 64번","w":["","100부터 순방향이라 아시아지부 전체(LVL 1~3)가 나옴","121부터 역방향이라 121, 120, 100만 나오고 LVL도 다름","최상위 100을 찾아 다시 순방향 → ②와 같은 결과"],"kc":"2-64","tables":[{"name":"부서","cols":["부서코드","부서명","상위부서코드"],"rows":[["100","아시아지부","NULL"],["110","한국지사","100"],["111","서울지점","110"],["112","부산지점","110"],["120","일본지사","100"],["121","도쿄지점","120"],["122","오사카지점","120"],["130","중국지사","100"],["131","베이징지점","130"],["132","상하이지점","130"],["200","남유럽지부","NULL"],["210","스페인지사","200"],["211","마드리드지점","210"],["212","그라나다지점","210"],["220","포르투갈지사","200"],["221","리스본지점","220"],["222","포르투지점","220"]]},{"name":"매출","cols":["부서코드","매출액"],"rows":[["111","1000"],["112","2000"],["121","1500"],["122","1000"],["131","1500"],["132","2000"],["211","2000"],["212","1500"],["221","1000"],["222","2000"]]},{"name":"실행 결과","cols":["부서코드","부서명","상위부서코드","매출액","LVL"],"rows":[["100","아시아지부","NULL","NULL","2"],["120","일본지사","100","NULL","1"],["121","도쿄지점","120","1500","2"],["122","오사카지점","120","1000","2"]]}]},{"id":1767,"c":"s14","d":2,"q":"아래의 SQL과 실행 결과가 다른 하나는?","code":["-- 테이블 생성","CREATE TABLE T1 (NO NUMBER, COLA VARCHAR2(10));","INSERT INTO T1 VALUES (1, 'AAA');","CREATE TABLE T2 (NO NUMBER, COLB VARCHAR2(10));","INSERT INTO T2 VALUES (1, 'BBB');","INSERT INTO T2 VALUES (3, 'CCC');","COMMIT;","","-- SQL","SELECT A.NO, A.COLA, B.COLB","  FROM T1 A, T2 B","  WHERE B.NO = A.NO;"],"o":["SELECT A.NO, A.COLA, B.COLB\nFROM T1 A INNER JOIN T2 B\nON B.NO = A.NO;","SELECT NO, A.COLA, B.COLB\nFROM T1 A JOIN T2 B\nUSING (NO);","SELECT A.NO, A.COLA, B.COLB\nFROM T1 A CROSS JOIN T2 B;","SELECT NO, A.COLA, B.COLB\nFROM T1 A NATURAL JOIN T2 B;"],"a":2,"e":"T1(1건)과 T2(2건)를 NO로 조인하면 NO=1 한 건. ①②④는 모두 NO 기준 등가 조인이라 1건, ③ CROSS JOIN만 1×2=2건으로 결과가 다르다.","src":"핵심기출 · 2과목 65번","w":["INNER JOIN ON, 1건","USING (NO), 1건","","NATURAL JOIN은 같은 이름 NO로 조인, 1건"],"kc":"2-65"},{"id":1768,"c":"s15","d":4,"q":"WINDOW FUNCTION을 사용하지 않고 아래의 실행 결과를 출력하는 SQL로 가장 적절한 것은?","code":null,"o":["SELECT A.일자, SUM(A.매출액) AS 누적매출액\nFROM 일자별매출 A\nGROUP BY A.일자\nORDER BY A.일자;","SELECT B.일자, SUM(B.매출액) AS 누적매출액\nFROM 일자별매출 A JOIN 일자별매출 B ON (A.일자 >= B.일자)\nGROUP BY B.일자\nORDER BY B.일자;","SELECT A.일자, SUM(B.매출액) AS 누적매출액\nFROM 일자별매출 A JOIN 일자별매출 B ON (A.일자 >= B.일자)\nGROUP BY A.일자\nORDER BY A.일자;","SELECT A.일자\n     ,(SELECT SUM(B.매출액)\n       FROM 일자별매출 B\n       WHERE B.일자 >= A.일자) AS 누적매출액\nFROM 일자별매출 A\nGROUP BY A.일자\nORDER BY A.일자;"],"a":2,"e":"누적 합계는 A.일자 >= B.일자로 셀프 조인한 뒤 A.일자로 묶어 SUM(B.매출액)을 구하면 된다. 11/03이면 B가 01, 02, 03 세 건 붙어 3000.","src":"핵심기출 · 2과목 66번","w":["셀프 조인 없이 일자별 매출 그대로 나옴(전부 1000)","B.일자로 묶으면 작은 날짜에 가장 큰 누적액이 붙음(역순 누적)","","B.일자 >= A.일자라 남은 기간 합계가 나옴(역순 누적)"],"kc":"2-66","tables":[{"name":"일자별매출","cols":["일자","매출액"],"rows":[["2015.11.01","1000"],["2015.11.02","1000"],["2015.11.03","1000"],["2015.11.04","1000"],["2015.11.05","1000"],["2015.11.06","1000"],["2015.11.07","1000"],["2015.11.08","1000"],["2015.11.09","1000"],["2015.11.10","1000"]]},{"name":"실행 결과","cols":["일자","누적매출액"],"rows":[["2015.11.01","1000"],["2015.11.02","2000"],["2015.11.03","3000"],["2015.11.04","4000"],["2015.11.05","5000"],["2015.11.06","6000"],["2015.11.07","7000"],["2015.11.08","8000"],["2015.11.09","9000"],["2015.11.10","10000"]]}]},{"id":1769,"c":"s20","d":2,"q":"아래 SQL의 실행 결과로 가장 적절한 것은?","code":["SELECT COUNT(DISTINCT A||B)","FROM   EMP","WHERE  D = (SELECT D FROM DEPT WHERE E = 'i');"],"o":["0","1","2","3"],"a":2,"e":"서브쿼리는 E='i'인 D = 'x'를 돌려준다. EMP에서 D='x'인 행은 (1,a), (2,a) → A||B는 '1a', '2a' 두 개라 COUNT(DISTINCT) = 2.","src":"핵심기출 · 2과목 67번","w":["조건에 맞는 행이 있음","B 값만 보고 DISTINCT 한 결과","","EMP 전체 3건을 센 결과"],"kc":"2-67","tables":[{"name":"EMP","cols":["A","B","C","D"],"rows":[["1","a","1","x"],["2","a","1","x"],["3","b","2","y"]]},{"name":"DEPT","cols":["D","E","F"],"rows":[["x","i","5"],["y","m","6"]]}]},{"id":1770,"c":"s20","d":3,"q":"아래에서 서브쿼리에 대한 설명으로 적절한 것을 모두 고른 것은?","code":null,"o":["(나), (라), (마)","(가), (나), (라)","(나), (다), (라)","(가), (나), (마)"],"a":1,"e":"(다) 복수 행 결과에는 IN, ALL, ANY 같은 다중 행 연산자를 써야 한다. (마) 다중 컬럼 서브쿼리는 SQL Server에서 지원하지 않는다. 그래서 맞는 건 (가), (나), (라).","src":"핵심기출 · 2과목 68번","w":["(마)는 SQL Server에서 지원 안 됨","","(다)는 단일 행 연산자로 복수 행 비교 불가","(마)가 틀렸고 (라)가 빠짐"],"kc":"2-68","box":["(가) 서브쿼리는 단일 행(Single Row) 또는 복수 행(Multi Row) 비교 연산자와 함께 사용할 수 있다.","(나) 서브쿼리는 SELECT 절, FROM 절, HAVING 절, ORDER BY 절 등에서 사용이 가능하다.","(다) 서브쿼리의 결과가 복수 행(Multi Row) 결과를 반환하는 경우에는 '=', '<=', '=>' 등의 연산자와 함께 사용할 수 있다.","(라) 연관(Correlated) 서브쿼리는 서브쿼리가 메인쿼리 칼럼을 포함하고 있는 형태의 서브쿼리이다.","(마) 다중 칼럼 서브쿼리는 서브쿼리의 결과로 여러 개의 칼럼이 반환되어 메인쿼리의 조건과 동시에 비교되는 것을 의미하며 오라클 및 SQL Server 등의 DBMS에서 사용할 수 있다."]},{"id":1771,"c":"s28","d":3,"q":"아래 실행 결과를 출력하는 SQL로 가장 적절한 것은?","code":null,"o":["SELECT KEY\n     , PERCENT_RANK() OVER(PARTITION BY GRP\n         ORDER BY VAL1) AS VAL1\n     , DENSE_RANK() OVER(ORDER BY VAL2) AS VAL2\nFROM TBL\nORDER BY KEY;","SELECT KEY\n     , CUME_DIST() OVER(ORDER BY VAL1) AS VAL1\n     , RANK() OVER(ORDER BY VAL2) AS VAL2\nFROM TBL\nORDER BY KEY;","SELECT KEY\n     , PERCENT_RANK() OVER(PARTITION BY GRP\n         ORDER BY VAL1) AS VAL1\n     , RANK() OVER(ORDER BY VAL2) AS VAL2\nFROM TBL\nORDER BY KEY;","SELECT KEY\n     , RATIO_TO_REPORT(VAL1) OVER(PARTITION BY GRP)\n       AS VAL1\n     , NTILE(5) OVER(ORDER BY VAL2) AS VAL2\nFROM TBL\nORDER BY KEY;"],"a":3,"e":"VAL1은 GRP별 VAL1 합계 대비 비율(A그룹 합 100 → 10/100=0.1), VAL2는 VAL2 순서로 5등분(2개씩 1~5). RATIO_TO_REPORT와 NTILE(5) 조합인 ④.","src":"핵심기출 · 2과목 69번","w":["PERCENT_RANK는 0부터 시작, DENSE_RANK는 1~10이 나옴","CUME_DIST·RANK로는 같은 값이 안 나옴","PERCENT_RANK는 첫 값이 0, RANK는 1~10",""],"kc":"2-69","tables":[{"name":"TBL","cols":["KEY","GRP","VAL1","VAL2"],"rows":[["1","A","10","100"],["2","A","10","200"],["3","A","10","300"],["4","A","20","400"],["5","A","50","500"],["6","B","40","600"],["7","B","10","700"],["8","B","20","800"],["9","B","20","900"],["10","B","10","1000"]]},{"name":"실행 결과","cols":["KEY","VAL1","VAL2"],"rows":[["1","0.1","1"],["2","0.1","1"],["3","0.1","2"],["4","0.2","2"],["5","0.5","3"],["6","0.4","3"],["7","0.1","4"],["8","0.2","4"],["9","0.2","5"],["10","0.1","5"]]}]},{"id":1772,"c":"s22","d":4,"q":"아래 SQL과 동일한 결과를 출력하는 SQL로 가장 적절하지 않은 것은?","code":["SELECT A.회원번호, A.회원명","FROM   회원 A, 동의항목 B","WHERE  A.회원번호 = B.회원번호","GROUP BY A.회원번호, A.회원명","HAVING COUNT(CASE WHEN B.동의여부 = 'N' THEN 0 ELSE","                  NULL END) >= 1","ORDER BY A.회원번호;"],"o":["SELECT A.회원번호, A.회원명\nFROM 회원 A\nWHERE EXISTS (SELECT 1\n              FROM 동의항목 B\n              WHERE A.회원번호 = B.회원번호\n              AND B.동의여부 = 'N')\nORDER BY A.회원번호;","SELECT A.회원번호, A.회원명\nFROM 회원 A\nWHERE A.회원번호 IN (SELECT B.회원번호\n                    FROM 동의항목 B\n                    WHERE B.동의여부 = 'N')\nORDER BY A.회원번호;","SELECT A.회원번호, A.회원명\nFROM 회원 A\nWHERE 0 < (SELECT COUNT(*)\n           FROM 동의항목 B\n           WHERE B.동의여부 = 'N')\nORDER BY A.회원번호;","SELECT A.회원번호, A.회원명\nFROM 회원 A, 동의항목 B\nWHERE A.회원번호 = B.회원번호 AND B.동의여부 = 'N'\nGROUP BY A.회원번호, A.회원명\nORDER BY A.회원번호;"],"a":2,"e":"원래 SQL은 동의여부 'N'이 한 건이라도 있는 회원을 찾는다. ③은 서브쿼리에 회원번호 연결 조건이 없어서, 누구든 'N'이 한 건만 있으면 모든 회원이 출력된다.","src":"핵심기출 · 2과목 70번","w":["EXISTS + 회원번호 연관 조건, 같은 결과","IN 서브쿼리, 같은 결과","","조인 후 WHERE로 거르고 GROUP BY로 중복 제거, 같은 결과"],"kc":"2-70","imgAlt":"회원(회원번호 / 회원명) ┼──○< 동의항목(회원번호(FK), 약관항목코드(FK) / 동의여부, 동의일시) >○──┼ 약관항목(약관항목코드 / 약관명)","img":"data/kc/2-70.jpg"},{"id":1773,"c":"s22","d":4,"q":"아래 SQL에 대한 설명으로 가장 적절한 것은?","code":["SELECT A.회원ID, A.회원명, A.이메일","FROM   회원 A","㉠ WHERE EXISTS (SELECT 'X'","                FROM   이벤트 B, 메일발송 C","                WHERE  B.시작일자 >= '2014.10.01'","                AND    B.이벤트ID = C.이벤트ID","㉡              AND    A.회원ID = C.회원ID","㉢              HAVING COUNT(*) < (SELECT COUNT(*)","                                  FROM   이벤트","                                  WHERE  시작일자","                                     >= '2014.10.01'));"],"o":["이벤트 시작일자가 '2014.10.01'과 같거나 큰 이벤트를 대상으로 이메일이 발송된 기록이 있는 모든 회원을 추출하는 SQL이다.","㉡을 제거하고 ㉠의 EXISTS 연산자를 IN 연산자로 변경해도 결과는 동일하다.","㉢은 이벤트 시작일자가 '2014.10.01'과 같거나 큰 이벤트건수와 그 이벤트들을 기준으로 회원별 이메일 발송건수를 비교하는 것이다.","GROUP BY 및 집계 함수를 사용하지 않고 HAVING절을 사용하였으므로 SQL이 실행되지 못하고 오류가 발생한다."],"a":2,"e":"시작일자 이후 이벤트 수보다 그 회원에게 발송된 메일 건수가 적은 회원, 즉 메일 발송이 누락된 회원을 찾는 SQL이다. ㉢이 바로 이벤트 건수와 회원별 발송 건수를 비교하는 부분.","src":"핵심기출 · 2과목 71번","w":["모든 회원이 아니라 발송이 누락된 회원만 추출","㉡을 빼고 IN으로 바꾸면 회원별 건수를 셀 수 없어 결과가 달라짐","","GROUP BY 없이 HAVING만 써도 전체를 한 그룹으로 보고 실행됨(오류 아님)"],"kc":"2-71","note":"원본은 ㉠㉡㉢ 부분이 각각 네모 칸으로 구분됨","imgAlt":"회원(회원ID / 회원명, 가입일시, 이메일) ┼──○< 메일발송(이벤트ID(FK), 회원ID(FK) / 발송일시) >○──┼ 이벤트(이벤트ID / 이벤트명, 시작일자, 종료일자, 내용)","img":"data/kc/2-71.jpg"},{"id":1774,"c":"s21","d":2,"q":"서브쿼리에 대한 설명으로 가장 적절한 것은?","code":null,"o":["단일 행 서브쿼리는 서브쿼리의 실행 결과가 항상 한 건 이하인 서브쿼리로 IN, ALL 등의 비교 연산자를 사용하여야 한다.","다중 행 서브쿼리 비교 연산자는 단일 행 서브쿼리의 비교 연산자로도 사용할 수 있다.","연관 서브쿼리는 주로 메인쿼리에 값을 제공하기 위한 목적으로 사용한다.","서브 쿼리는 항상 메인쿼리에서 읽힌 데이터에 대해 서브쿼리에서 해당 조건이 만족하는지를 확인하는 방식으로 수행된다."],"a":1,"e":"다중 행 비교 연산자(IN, ANY 등)는 단일 행 서브쿼리에도 쓸 수 있다. 반대로 단일 행 연산자는 다중 행 서브쿼리에 못 쓴다.","src":"핵심기출 · 2과목 72번","w":["단일 행 서브쿼리는 =, <, > 같은 단일 행 연산자. IN, ALL은 다중 행 연산자","","메인쿼리에 값을 제공하는 건 주로 비연관 서브쿼리","실행 순서는 상황에 따라 다름(서브쿼리 먼저일 수도 있음)"],"kc":"2-72"},{"id":1775,"c":"s20","d":3,"q":"아래 SQL에 대한 설명으로 가장 적절하지 않은 것은?","code":["SELECT B.사원번호, B.사원명, A.부서번호, A.부서명","     , ( SELECT COUNT(*)","         FROM 부양가족 Y","         WHERE Y.사원번호 = B.사원번호) AS 부양가족수","FROM 부서 A, (SELECT *","              FROM 사원","              WHERE 입사년도 = '2014') B","WHERE A.부서번호 = B.부서번호","AND EXISTS ( SELECT 1","             FROM 사원 X","             WHERE X.부서번호 = A.부서번호);"],"o":["위 SQL에는 다중 행 연관 서브쿼리, 단일 행 연관 서브쿼리, 인라인 뷰(Inline View)가 사용되었다.","SELECT 절에 사용된 서브쿼리는 스칼라 서브쿼리라고도 하며, 이러한 형태의 서브쿼리는 JOIN으로 동일한 결과를 추출할 수도 있다.","WHERE 절의 서브쿼리에 사원 테이블 검색 조건으로 입사년도 조건을 FROM 절의 서브쿼리와 동일하게 추가해야 원하는 결과를 추출할 수 있다.","FROM 절의 서브쿼리는 동적 뷰(Dynamic View)라고도 하며, SQL 문장 중 테이블 명이 올 수 있는 곳에서 사용할 수 있다."],"a":2,"e":"FROM 절 인라인 뷰에서 이미 입사년도 = '2014'로 거른 사원만 부서와 조인한다. EXISTS는 '사원이 있는 부서'만 확인할 뿐이라 입사년도 조건을 더 넣을 필요가 없다.","src":"핵심기출 · 2과목 73번","w":["EXISTS 안은 다중 행 연관, SELECT 절은 단일 행 연관, FROM 절은 인라인 뷰, 맞음","스칼라 서브쿼리는 조인으로 바꿀 수 있음, 맞음","","인라인 뷰 = 동적 뷰, 테이블 자리에 사용, 맞음"],"kc":"2-73"},{"id":1776,"c":"s22","d":4,"q":"아래를 참고할 때 평가대상상품에 대한 품질평가항목별 최종 평가결과를 출력하는 SQL로 가장 적절한 것은? (단, 평가항목에 대한 평가등급이 기대수준에 미치지 못할 경우 해당 평가항목에 대해서만 재평가를 수행한다.)","code":null,"o":["SELECT B.상품ID, B.상품명, C.평가항목ID, C.평가항목명, A.평가회차, A.평가등급, A.평가일자\nFROM 평가결과 A, 평가대상상품 B, 품질평가항목 C,\n     (SELECT MAX(평가회차) AS 평가회차 FROM 평가결과) D\nWHERE A.상품ID = B.상품ID\nAND A.평가항목ID = C.평가항목ID\nAND A.평가회차 = D.평가회차;","SELECT B.상품ID, B.상품명, C.평가항목ID, C.평가항목명, A.평가회차, A.평가등급, A.평가일자\nFROM 평가결과 A, 평가대상상품 B, 품질평가항목 C\nWHERE A.상품ID = B.상품ID\nAND A.평가항목ID = C.평가항목ID\nAND A.평가회차 = (SELECT MAX(X.평가회차)\n                 FROM 평가결과 X\n                 WHERE X.상품ID = B.상품ID\n                 AND X.평가항목ID = C.평가항목ID);","SELECT B.상품ID, B.상품명, C.평가항목ID, C.평가항목명\n     ,MAX(A.평가회차) AS 평가회차\n     ,MAX(A.평가등급) AS 평가등급\n     ,MAX(A.평가일자) AS 평가일자\nFROM 평가결과 A, 평가대상상품 B, 품질평가항목 C\nWHERE A.상품ID = B.상품ID\nAND A.평가항목ID = C.평가항목ID\nGROUP BY B.상품ID, B.상품명, C.평가항목ID, C.평가항목명;","SELECT B.상품ID, B.상품명, C.평가항목ID, C.평가항목명, A.평가회차, A.평가등급, A.평가일자\nFROM (SELECT 상품ID, 평가항목ID\n            ,MAX(평가회차) AS 평가회차\n            ,MAX(평가등급) AS 평가등급\n            ,MAX(평가일자) AS 평가일자\n      FROM 평가결과\n      GROUP BY 상품ID, 평가항목ID) A, 평가대상상품 B,\n     품질평가항목 C\nWHERE A.상품ID = B.상품ID\nAND A.평가항목ID = C.평가항목ID;"],"a":1,"e":"상품·평가항목마다 최종 평가회차가 다르다. 연관 서브쿼리로 해당 상품·평가항목의 MAX(평가회차)를 구해 조인한 ②가 정답.","src":"핵심기출 · 2과목 74번","w":["전체 평가결과에서 가장 큰 회차 하나만 기준으로 써서 항목별 최종 회차가 아님","","회차·등급·일자를 각각 MAX로 구해 같은 회차의 값이 아닐 수 있음","③과 같은 문제(컬럼별 MAX)"],"kc":"2-74","imgAlt":"품질평가항목(평가항목ID / 평가항목명) ┼──○< 평가결과(상품ID(FK), 평가회차, 평가항목ID(FK) / 평가등급, 평가일자) >○──┼ 평가대상상품(상품ID / 상품명)","img":"data/kc/2-74.jpg"},{"id":1777,"c":"s20","d":2,"q":"뷰에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["뷰는 단지 정의만을 가지고 있으며, 실행 시점에 질의를 재작성하여 수행한다.","뷰는 복잡한 SQL 문장을 단순화하는 장점이 있는 반면, 테이블 구조가 변경되면 응용 프로그램을 변경해 주어야 한다.","뷰는 보안을 강화하기 위한 목적으로도 활용할 수 있다.","실제 데이터를 저장하고 있는 뷰를 생성하는 기능을 지원하는 DBMS도 있다."],"a":1,"e":"뷰의 장점 중 독립성: 테이블 구조가 바뀌어도 뷰만 고치면 뷰를 쓰는 응용 프로그램은 그대로 둬도 된다. '응용 프로그램을 변경해 줘야 한다'가 틀렸다.","src":"핵심기출 · 2과목 75번","w":["뷰는 정의만 저장, 실행 시 재작성, 맞음","","보안(특정 컬럼 숨김) 목적, 맞음","Materialized View처럼 데이터를 저장하는 뷰를 지원하는 DBMS도 있음, 맞음"],"kc":"2-75"},{"id":1778,"c":"s20","d":2,"q":"아래에서 뷰 생성 스크립트를 실행한 후, SQL을 실행한 결과로 가장 적절한 것은?","code":["-- 뷰 생성 스크립트","CREATE VIEW V_TBL","AS","SELECT *","FROM TBL","WHERE C1 = 'B' OR C1 IS NULL","","-- SQL","SELECT SUM(C2) C2","FROM V_TBL","WHERE C2 >= 200 AND C1 = 'B'"],"o":["0","200","300","400"],"a":1,"e":"뷰 조건(C1='B' OR C1 IS NULL)과 조회 조건(C2>=200 AND C1='B')을 모두 만족하는 행은 ('B', 200) 하나뿐. SUM = 200.","src":"핵심기출 · 2과목 76번","w":["조건에 맞는 행이 있음","","C2>=200 조건을 빼고 B 행을 더한 값(200+100)","C1 조건을 무시한 결과"],"kc":"2-76","tables":[{"name":"TBL","cols":["C1","C2"],"rows":[["A","100"],["B","200"],["B","100"],["B","NULL"],["NULL","200"]]}]},{"id":1779,"c":"s26","d":4,"q":"아래 SQL의 실행 결과로 가장 적절한 것은?","code":["SELECT 사원ID, COL2, COL3","FROM  (SELECT 사원ID","             ,ROW_NUMBER() OVER(PARTITION BY 부서ID","               ORDER BY 연봉 DESC) AS COL1","             ,SUM(연봉) OVER(PARTITION BY 부서ID ORDER","               BY 사원ID ROWS BETWEEN UNBOUNDED PRECEDING AND","               CURRENT ROW) AS COL2","             ,MAX(연봉) OVER(ORDER BY 연봉 DESC ROWS","               CURRENT ROW) AS COL3","       FROM 사원)","WHERE COL1 = 2","ORDER BY 1;"],"o":[{"cols":["사원ID","COL2","COL3"],"rows":[["001","2500","4500"],["004","7500","4500"],["007","7500","4500"]]},{"cols":["사원ID","COL2","COL3"],"rows":[["001","2500","2500"],["004","7500","3000"],["007","7500","3000"]]},{"cols":["사원ID","COL2","COL3"],"rows":[["001","5500","4500"],["004","5500","4500"],["007","3000","4500"]]},{"cols":["사원ID","COL2","COL3"],"rows":[["001","5500","2500"],["004","5500","3000"],["007","3000","3000"]]}],"a":1,"e":"COL1은 부서별 연봉 내림차순 순번, 2번째인 001, 004, 007만 남는다. COL2는 부서별 사원ID 순 누적합: 001→2500, 004→4500+3000=7500, 007→4500+3000=7500. COL3는 ROWS CURRENT ROW = 자기 행만 보니 본인 연봉 2500, 3000, 3000.","src":"핵심기출 · 2과목 77번","w":["COL3를 전체 최댓값으로 계산한 결과","","COL2를 부서 전체 합으로 본 결과","COL2를 부서 전체 합으로 본 결과"],"kc":"2-77","tables":[{"name":"사원","cols":["사원ID","부서ID","연봉"],"rows":[["001","100","2500"],["002","100","3000"],["003","200","4500"],["004","200","3000"],["005","200","2500"],["006","300","4500"],["007","300","3000"]]}],"otype":"table"},{"id":1780,"c":"s24","d":4,"q":"아래 실행 결과를 출력하는 SQL로 가장 적절한 것은?","code":null,"o":["SELECT (CASE GROUPING(B.지역명) WHEN 0 THEN '지역전체'\n             ELSE B.지역명 END) AS 지역명\n      ,(CASE GROUPING(TO_CHAR(A.이용일시, 'YYYY.MM'))\n             WHEN 0 THEN '월별합계'\n             ELSE TO_CHAR(A.이용일시, 'YYYY.MM')\n        END) AS 이용월\n      ,SUM(A.이용량) AS 이용량\nFROM 이용내역 A INNER JOIN 지역 B ON (A.지역ID = B.지역ID)\nGROUP BY ROLLUP(B.지역명, TO_CHAR(A.이용일시, 'YYYY.MM'))","SELECT (CASE GROUPING(B.지역ID) WHEN 1 THEN '지역전체'\n             ELSE MIN(B.지역명) END) AS 지역명\n      ,(CASE GROUPING(TO_CHAR(A.이용일시, 'YYYY.MM'))\n             WHEN 1 THEN '월별합계'\n             ELSE TO_CHAR(A.이용일시, 'YYYY.MM')\n        END) AS 이용월\n      ,SUM(A.이용량) AS 이용량\nFROM 이용내역 A INNER JOIN 지역 B ON (A.지역ID = B.지역ID)\nGROUP BY ROLLUP(B.지역ID, TO_CHAR(A.이용일시, 'YYYY.MM'))","SELECT (CASE GROUPING(B.지역명) WHEN 1 THEN '지역전체'\n             ELSE B.지역명 END) AS 지역명\n      ,(CASE GROUPING(TO_CHAR(A.이용일시, 'YYYY.MM'))\n             WHEN 1 THEN '월별합계'\n             ELSE TO_CHAR(A.이용일시, 'YYYY.MM')\n        END) AS 이용월\n      ,SUM(A.이용량) AS 이용량\nFROM 이용내역 A INNER JOIN 지역 B ON (A.지역ID = B.지역ID)\nGROUP BY CUBE(B.지역명, TO_CHAR(A.이용일시, 'YYYY.MM'))","SELECT (CASE GROUPING(B.지역ID) WHEN 1 THEN '지역전체'\n             ELSE MIN(B.지역명) END) AS 지역명\n      ,(CASE GROUPING(TO_CHAR(A.이용일시, 'YYYY.MM'))\n             WHEN 1 THEN '월별합계'\n             ELSE TO_CHAR(A.이용일시, 'YYYY.MM')\n        END) AS 이용월\n      ,SUM(A.이용량) AS 이용량\nFROM 이용내역 A INNER JOIN 지역 B ON (A.지역ID = B.지역ID)\nGROUP BY GROUPING SETS(B.지역ID, TO_CHAR(A.이용일시, 'YYYY.MM'))"],"a":1,"e":"지역별 월별 소계와 전체 합계가 계층적으로 나오니 ROLLUP. 소계 행에서 GROUPING() 값은 1이므로 WHEN 1 THEN '지역전체'/'월별합계'로 써야 한다. 지역명은 지역ID 그룹 안에서 MIN으로 가져온다.","src":"핵심기출 · 2과목 78번","w":["GROUPING() = 0 조건이 반대라 일반 행에 '지역전체'가 붙음","","CUBE는 월별 전체 소계까지 만들어 행이 더 많음","GROUPING SETS는 계층 없이 지역별, 월별 합계만 따로 나옴"],"kc":"2-78","tables":[{"name":"실행 결과","cols":["지역명","이용월","이용량"],"rows":[["서울","2014.01","1000"],["서울","2014.02","1000"],["서울","월별합계","2000"],["경기","2014.01","1000"],["경기","2014.03","2000"],["경기","월별합계","3000"],["대전","2014.05","1500"],["대전","2014.06","1000"],["대전","월별합계","2500"],["지역전체","월별합계","7500"]]}],"imgAlt":"지역(지역ID / 지역명) ┼- - -○< 이용내역(이용자ID, 이용일시 / 이용량, 지역ID(FK))","img":"data/kc/2-78.jpg"},{"id":1781,"c":"s21","d":3,"q":"아래 SQL에 대한 설명으로 가장 적절한 것은?","code":["SELECT EMPNO, SAL","FROM   EMP","WHERE  SAL >= ( SELECT   MAX(SAL)","                FROM     EMP","                GROUP BY DEPTNO );"],"o":["'단일 행 하위 질의에 2개 이상의 행이 리턴되었습니다.' 오류가 발생한다.","부서별 최고연봉보다 크거나 같은 사원을 출력한다.","부서별 최고연봉 전부와 크거나 같은 연봉을 가진 사원을 출력하는 쿼리는 다음과 같이 변경할 수 있다.\nSELECT EMPNO, DEPTNO, SAL\nFROM EMP\nWHERE SAL >= ANY(SELECT MAX(SAL) FROM EMP GROUP BY DEPTNO);","부서별 최고연봉 중 하나보다 크거나 같은 연봉을 가진 사원을 출력하는 쿼리는 다음과 같이 변경할 수 있다.\nSELECT EMPNO, DEPTNO, SAL\nFROM emp\nWHERE SAL >= ALL(SELECT MAX(SAL) FROM EMP GROUP BY DEPTNO);"],"a":0,"e":"서브쿼리가 부서별 MAX를 여러 행 돌려주는데 >= 단일 행 연산자를 썼다. 실행하면 '단일 행 하위 질의에 2개 이상의 행이 리턴' 오류.","src":"핵심기출 · 2과목 79번","w":["","오류가 나서 결과가 안 나옴","'전부와 크거나 같은'은 >= ALL","'하나보다 크거나 같은'은 >= ANY"],"kc":"2-79"},{"id":1782,"c":"s24","d":2,"q":"아래를 참고할 때 SQL의 빈칸 ㉠에 들어갈 내용으로 가장 적절한 것은?","code":["SELECT DNAME","     , JOB","     , COUNT(EMPNO) TOTAL_EMP","     , SUM(SAL)     TOTAL_SAL","FROM EMP, DEPT","WHERE DEPT.DEPTNO = EMP.DEPTNO","GROUP BY ( ㉠ )",";"],"o":["ROLLUP (DNAME, JOB)","CUBE (DNAME, JOB)","GROUPING SETS ((DNAME, JOB), DNAME)","DNAME, ROLLUP (JOB)"],"a":0,"e":"(DNAME, JOB)별, DNAME별 소계, 전체 합계가 계층적으로 나온다 → ROLLUP(DNAME, JOB).","src":"핵심기출 · 2과목 80번","w":["","CUBE면 JOB별 소계(DNAME NULL)도 나옴","GROUPING SETS면 전체 합계 행이 없음","DNAME, ROLLUP(JOB)도 전체 합계가 없음"],"kc":"2-80","tables":[{"name":"실행 결과","cols":["DNAME","JOB","TOTAL_EMP","TOTAL_SAL"],"rows":[["SALES","CLERK","1","950"],["SALES","MANAGER","1","2850"],["SALES","SALESMAN","4","5600"],["SALES","NULL","6","9400"],["RESEARCH","CLERK","2","1900"],["RESEARCH","ANALYST","2","6000"],["RESEARCH","MANAGER","1","2975"],["RESEARCH","NULL","5","10875"],["ACCOUNTING","CLERK","1","1300"],["ACCOUNTING","MANAGER","1","2450"],["ACCOUNTING","PRESIDENT","1","5000"],["ACCOUNTING","NULL","3","8750"],["NULL","NULL","14","29025"]],"after":true}]},{"id":1783,"c":"s24","d":4,"q":"아래 실행 결과를 출력하는 SQL로 가장 적절한 것은?","code":null,"o":["SELECT A.설비ID, B.에너지코드, SUM(B.사용량) AS 사용량합계\nFROM 설비 A INNER JOIN 에너지사용량 B\nON (A.설비ID = B.설비ID)\nGROUP BY CUBE ((A.설비ID), (B.에너지코드), (A.설비ID,\n         B.에너지코드))\nORDER BY A.설비ID, B.에너지코드;","SELECT A.설비ID, B.에너지코드, SUM(B.사용량) AS 사용량합계\nFROM 설비 A INNER JOIN 에너지사용량 B\nON (A.설비ID = B.설비ID)\nGROUP BY CUBE (A.설비ID, B.에너지코드)\nORDER BY A.설비ID, B.에너지코드;","SELECT A.설비ID, B.에너지코드, SUM(B.사용량) AS 사용량합계\nFROM 설비 A INNER JOIN 에너지사용량 B\nON (A.설비ID = B.설비ID)\nGROUP BY GROUPING SETS((A.설비ID), (A.설비ID, B.에너지코드))\nORDER BY A.설비ID, B.에너지코드;","SELECT A.설비ID, B.에너지코드, SUM(B.사용량) AS 사용량합계\nFROM 설비 A INNER JOIN 에너지사용량 B\nON (A.설비ID = B.설비ID)\nGROUP BY GROUPING SETS((A.설비ID), (B.에너지코드),\n         (A.설비ID, B.에너지코드))\nORDER BY A.설비ID, B.에너지코드;"],"a":1,"e":"(설비ID, 에너지코드)별, 설비ID별, 에너지코드별, 전체 합계가 모두 나온다 = CUBE(설비ID, 에너지코드).","src":"핵심기출 · 2과목 81번","w":["그룹을 중복으로 지정해 같은 행이 여러 번 나옴","","에너지코드별 소계와 총계가 빠짐","전체 합계 행이 빠짐"],"kc":"2-81","tables":[{"name":"설비","cols":["설비ID","설비명"],"rows":[["1","설비1"],["2","설비2"],["3","설비3"]]},{"name":"에너지사용량","cols":["설비ID","에너지코드","사용량"],"rows":[["1","전기","100"],["1","용수","200"],["1","바람","300"],["2","전기","200"],["2","용수","300"],["3","전기","300"]]},{"name":"실행 결과","cols":["설비ID","에너지코드","사용량합계"],"rows":[["1","바람","300"],["1","용수","200"],["1","전기","100"],["1","NULL","600"],["2","용수","300"],["2","전기","200"],["2","NULL","500"],["3","전기","300"],["3","NULL","300"],["NULL","바람","300"],["NULL","용수","500"],["NULL","전기","600"],["NULL","NULL","1400"]]}]},{"id":1784,"c":"s24","d":3,"q":"아래를 참고할 때 SQL의 빈칸 ㉠에 들어갈 내용으로 가장 적절한 것은?","code":["SELECT A.JOB, A.DEPTNO, ROUND(AVG(A.SAL),2) AVG_SAL","  FROM EMP A","  GROUP BY ( ㉠ ) ;"],"o":["ROLLUP (JOB, DEPTNO)","ROLLUP ((JOB, DEPTNO))","ROLLUP ((JOB), (DEPTNO))","JOB, ROLLUP (DEPTNO)"],"a":1,"e":"(JOB, DEPTNO)별 평균과 전체 평균만 있다. 둘을 괄호로 묶어 하나의 단위로 쓰는 ROLLUP((JOB, DEPTNO)).","src":"핵심기출 · 2과목 82번","w":["JOB별 소계 행까지 생김","","ROLLUP((JOB),(DEPTNO))는 ROLLUP(JOB, DEPTNO)와 같아 JOB 소계가 생김","JOB별 소계가 생기고 전체 합계는 없음"],"kc":"2-82","tables":[{"name":"실행 결과","cols":["JOB","DEPTNO","AVG_SAL"],"rows":[["CLERK","10","1300"],["CLERK","20","950"],["CLERK","30","950"],["ANALYST","20","3000"],["MANAGER","10","2450"],["MANAGER","20","2975"],["MANAGER","30","2850"],["SALESMAN","30","1400"],["PRESIDENT","10","5000"],["NULL","NULL","2073.21"]],"after":true}]},{"id":1785,"c":"s24","d":3,"q":"아래 SQL의 실행 결과로 가장 적절한 것은?","code":["SELECT 상품ID, 월, SUM(매출액) AS 매출액","FROM   월별매출","WHERE  월 BETWEEN '2014.10' AND '2014.12'","GROUP BY GROUPING SETS((상품ID, 월));"],"o":[{"cols":["상품ID","월","매출액"],"rows":[["NULL","2014.10","4500"],["NULL","2014.11","4500"],["NULL","2014.12","5000"],["P001","NULL","5500"],["P002","NULL","4500"],["P003","NULL","4000"]]},{"cols":["상품ID","월","매출액"],"rows":[["P001","2014.10","1500"],["P001","2014.11","1500"],["P001","2014.12","2500"],["P002","2014.10","1000"],["P002","2014.11","2000"],["P002","2014.12","1500"],["P003","2014.10","2000"],["P003","2014.11","1000"],["P003","2014.12","1000"]]},{"cols":["상품ID","월","매출액"],"rows":[["NULL","2014.10","4500"],["NULL","2014.11","4500"],["NULL","2014.12","5000"],["P001","NULL","5500"],["P002","NULL","4500"],["P003","NULL","4000"],["NULL","NULL","14000"]]},{"cols":["상품ID","월","매출액"],"rows":[["P001","2014.10","1500"],["P002","2014.10","1000"],["P003","2014.10","2000"],["NULL","2014.10","4500"],["P001","2014.11","1500"],["P002","2014.11","2000"],["P003","2014.11","1000"],["NULL","2014.11","4500"],["P001","2014.12","2500"],["P002","2014.12","1500"],["P003","2014.12","1000"],["NULL","2014.12","5000"]]}],"a":1,"e":"GROUPING SETS((상품ID, 월))는 괄호로 하나의 그룹만 지정한 것이라 그냥 GROUP BY 상품ID, 월과 같다. 소계 없이 9행.","src":"핵심기출 · 2과목 83번","w":["GROUPING SETS(월, 상품ID) 결과","","GROUPING SETS(월, 상품ID, ()) 결과","GROUPING SETS((월, 상품ID), 월) 결과"],"kc":"2-83","tables":[{"name":"월별매출","cols":["상품ID","월","매출액"],"rows":[["P001","2014.10","1500"],["P001","2014.11","1500"],["P001","2014.12","2500"],["P002","2014.10","1000"],["P002","2014.11","2000"],["P002","2014.12","1500"],["P003","2014.10","2000"],["P003","2014.11","1000"],["P003","2014.12","1000"]]}],"otype":"table"},{"id":1786,"c":"s26","d":2,"q":"윈도우 함수(Window Function)에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["PARTITION BY 절과 GROUP BY 절은 의미적으로 유사하다.","PARTITION BY 절이 없으면 전체 집합을 하나의 Partition으로 정의한 것과 동일하다.","윈도우 함수 처리로 결과 건수가 줄어든다.","윈도우 함수 적용 범위는 Partition을 넘을 수 없다."],"a":2,"e":"윈도우 함수는 행마다 결과를 붙일 뿐 건수를 줄이지 않는다.","src":"핵심기출 · 2과목 84번","w":["파티션 나누기는 GROUP BY와 의미상 비슷, 맞음","PARTITION BY 없으면 전체가 하나의 파티션, 맞음","","적용 범위는 파티션을 넘지 않음, 맞음"],"kc":"2-84"},{"id":1787,"c":"s25","d":3,"q":"아래 SQL의 실행 결과로 가장 적절한 것은?","code":["SELECT 고객번호, 고객명, 매출액","     , RANK() OVER(ORDER BY 매출액 DESC) AS 순위","FROM   (","        SELECT A.고객번호","             , MAX(A.고객명) AS 고객명","             , SUM(B.매출액) AS 매출액","        FROM   고객 A INNER JOIN 월별매출 B","        ON     (A.고객번호 = B.고객번호)","        GROUP BY A.고객번호","       )","ORDER BY 순위;"],"o":[{"cols":["고객번호","고객명","매출액","순위"],"rows":[["005","이규혁","700","1"],["004","이상화","700","1"],["002","이순신","550","3"],["001","홍길동","350","4"],["003","강감찬","350","4"]]},{"cols":["고객번호","고객명","매출액","순위"],"rows":[["005","이규혁","700","1"],["004","이상화","700","2"],["002","이순신","550","3"],["001","홍길동","350","4"],["003","강감찬","350","5"]]},{"cols":["고객번호","고객명","매출액","순위"],"rows":[["005","이규혁","700","1"],["004","이상화","700","1"],["002","이순신","550","2"],["001","홍길동","350","3"],["003","강감찬","350","3"]]},{"cols":["고객번호","고객명","매출액","순위"],"rows":[["003","강감찬","350","1"],["001","홍길동","350","1"],["002","이순신","550","2"],["004","이상화","700","3"],["005","이규혁","700","3"]]}],"a":0,"e":"고객별 합계: 005·004 700, 002 550, 001·003 350. RANK는 같은 값에 같은 순위를 주고 다음 순위를 건너뛴다 → 1, 1, 3, 4, 4.","src":"핵심기출 · 2과목 85번","w":["","ROW_NUMBER 결과(동순위 없음)","DENSE_RANK 결과(건너뛰지 않음)","오름차순으로 매긴 결과"],"kc":"2-85","tables":[{"name":"고객","cols":["고객번호(PK)","고객명"],"rows":[["001","홍길동"],["002","이순신"],["003","강감찬"],["004","이상화"],["005","이규혁"]]},{"name":"월별매출","cols":["월(PK)","고객번호(PK)","매출액"],"rows":[["201301","001","200"],["201301","002","300"],["201301","003","250"],["201301","004","300"],["201301","005","250"],["201302","001","150"],["201302","002","150"],["201302","004","200"],["201302","005","100"],["201303","002","100"],["201303","003","100"],["201303","004","200"],["201303","005","350"]]}],"otype":"table"},{"id":1788,"c":"s25","d":2,"q":"아래를 참고할 때 SQL의 빈칸 ㉠에 들어갈 내용으로 가장 적절한 것은?","code":["SELECT JOB, ENAME, SAL, COMM","     , ( ㉠ ) () OVER(ORDER BY NVL(SAL,0) +","  NVL(COMM,0) DESC) RANK","  FROM EMP;"],"o":["ROWNUM","ROW_NUMBER","RANK","DENSE_RANK"],"a":3,"e":"결과를 보면 공동 2위 다음이 3위다. 동순위를 하나로 치고 다음 순위를 이어 붙이는 건 DENSE_RANK.","src":"핵심기출 · 2과목 86번","w":["ROWNUM은 윈도우 함수가 아님","ROW_NUMBER면 동순위가 없음","RANK면 공동 2위 다음이 4위",""],"kc":"2-86","tables":[{"name":"실행 결과","cols":["JOB","ENAME","SAL","COMM","RANK"],"rows":[["PRESIDENT","KING","5000","NULL","1"],["ANALYST","FORD","3000","NULL","2"],["ANALYST","SCOTT","3000","NULL","2"],["MANAGER","JONES","2975","NULL","3"],["MANAGER","BLAKE","2850","NULL","4"],["SALESMAN","MARTIN","1250","1400","5"],["MANAGER","CLARK","2450","NULL","6"],["SALESMAN","ALLEN","1600","300","7"],["SALESMAN","WARD","1250","500","8"],["SALESMAN","TURNER","1500","0","9"],["CLERK","MILLER","1300","NULL","10"],["CLERK","ADAMS","1100","NULL","11"],["CLERK","JAMES","950","NULL","12"],["CLERK","SMITH","800","NULL","13"]]}]},{"id":1789,"c":"s25","d":2,"q":"아래를 참고할 때 SQL의 실행 결과로 가장 적절한 것은?","code":["SELECT 추천경로, 추천인, 피추천인, 추천점수","FROM   (SELECT 추천경로, 추천인, 피추천인, 추천점수","             , ROW_NUMBER() OVER(PARTITION BY 추천경로","                 ORDER BY 추천점수 DESC) AS RNUM","        FROM   추천내역)","WHERE  RNUM = 1;"],"o":[{"cols":["추천경로","추천인","피추천인","추천점수"],"rows":[["SNS","나한일","강감찬","75"],["SNS","이순신","강감찬","80"],["이벤트응모","홍길동","강감찬","88"],["이벤트응모","저절로","이순신","78"],["홈페이지","저절로","이대로","93"],["홈페이지","홍두깨","심청이","98"]]},{"cols":["추천경로","추천인","피추천인","추천점수"],"rows":[["홈페이지","홍두깨","심청이","98"]]},{"cols":["추천경로","추천인","피추천인","추천점수"],"rows":[["SNS","이순신","강감찬","80"],["이벤트응모","홍길동","강감찬","88"],["홈페이지","홍두깨","심청이","98"]]},{"cols":["추천경로","추천인","피추천인","추천점수"],"rows":[["SNS","나한일","강감찬","75"],["이벤트응모","저절로","이순신","78"],["홈페이지","저절로","이대로","93"]]}],"a":2,"e":"ROW_NUMBER로 추천경로별 추천점수 내림차순 번호를 매기고 RNUM=1만 고르니, 경로별 최고 점수 1건씩: SNS 80, 이벤트응모 88, 홈페이지 98.","src":"핵심기출 · 2과목 87번","w":["필터 없이 전체가 나온 결과","전체 1등만 나온 결과","","경로별 최저 점수가 나온 결과"],"kc":"2-87","tables":[{"name":"추천내역","cols":["추천경로","추천인","피추천인","추천점수"],"rows":[["SNS","나한일","강감찬","75"],["SNS","이순신","강감찬","80"],["이벤트응모","홍길동","강감찬","88"],["이벤트응모","저절로","이순신","78"],["홈페이지","저절로","이대로","93"],["홈페이지","홍두깨","심청이","98"]]}],"otype":"table"},{"id":1790,"c":"s26","d":3,"q":"아래 SQL에 대한 설명으로 가장 적절한 것은?","code":["SELECT 상품분류코드","      ,AVG(상품가격) AS 상품가격","      ,COUNT(*) OVER(ORDER BY AVG(상품가격)","                RANGE BETWEEN 10000 PRECEDING","                AND 10000 FOLLOWING) AS 유사개수","FROM   상품","GROUP BY 상품분류코드;"],"o":["WINDOW FUNCTION을 GROUP BY 절과 함께 사용하였으므로 위의 SQL은 오류가 발생한다.","WINDOW FUNCTION의 ORDER BY절에 AVG 집계 함수를 사용하였으므로 위의 SQL은 오류가 발생한다.","유사개수 칼럼은 상품분류코드별 평균상품가격을 서로 비교하여 -10000 ~ +10000 사이에 존재하는 상품분류코드의 개수를 구한 것이다.","유사개수 칼럼은 상품전체의 평균상품가격을 서로 비교하여 -10000 ~ +10000 사이에 존재하는 상품의 개수를 구한 것이다."],"a":2,"e":"GROUP BY로 만든 결과 집합 위에 윈도우 함수를 쓰는 건 문제없다. 유사개수는 상품분류코드별 평균가격끼리 비교해 ±10000 안에 드는 상품분류코드 개수.","src":"핵심기출 · 2과목 88번","w":["GROUP BY와 윈도우 함수는 함께 쓸 수 있음","윈도우 ORDER BY에 집계 함수 사용 가능","","비교 대상은 상품 개별이 아니라 상품분류코드별 평균"],"kc":"2-88"},{"id":1791,"c":"s26","d":2,"q":"아래 SQL의 실행 결과로 가장 적절한 것은?","code":["SELECT Y.사원ID, Y.부서ID, Y.사원명, Y.연봉","FROM   (SELECT 사원ID, MAX(연봉) OVER(PARTITION BY","               부서ID) AS 최고연봉","        FROM 사원) X, 사원 Y","WHERE  X.사원ID = Y.사원ID","AND    X.최고연봉 = Y.연봉"],"o":[{"cols":["사원ID","부서ID","사원명","연봉"],"rows":[["002","100","강감찬","3000"],["003","200","김유신","4500"],["006","300","변사또","4500"]]},{"cols":["사원ID","부서ID","사원명","연봉"],"rows":[["001","100","홍길동","2500"],["005","200","유학생","2500"],["007","300","박문수","3000"]]},{"cols":["사원ID","부서ID","사원명","연봉"],"rows":[["003","200","김유신","4500"],["006","300","변사또","4500"]]},{"cols":["사원ID","부서ID","사원명","연봉"],"rows":[["003","200","김유신","4500"]]}],"a":0,"e":"인라인 뷰에서 사원마다 부서 최고연봉을 붙이고(100→3000, 200→4500, 300→4500), 연봉 = 최고연봉인 사원만 남기면 002, 003, 006.","src":"핵심기출 · 2과목 89번","w":["","부서별 최저 연봉 사원","300 부서 최고연봉 006이 빠질 이유 없음, 100 부서도 빠짐","003만 나올 이유 없음"],"kc":"2-89","tables":[{"name":"사원","cols":["사원ID","부서ID","사원명","연봉"],"rows":[["001","100","홍길동","2500"],["002","100","강감찬","3000"],["003","200","김유신","4500"],["004","200","김선달","3000"],["005","200","유학생","2500"],["006","300","변사또","4500"],["007","300","박문수","3000"]]}],"otype":"table"},{"id":1792,"c":"s27","d":1,"q":"아래를 참고할 때 SQL의 빈칸 ㉠에 들어갈 내용으로 가장 적절한 것은?","code":["SELECT EMPNO,HIREDATE, SAL, ( ㉠ ) (SAL) OVER (ORDER","  BY HIREDATE) AS SAL2","FROM EMP","WHERE JOB = 'SALESMAN';"],"o":["LEAD","ROW_NUMBER","RANK","LAG"],"a":3,"e":"결과를 보면 SAL_2에 바로 앞 행(입사일 순)의 SAL이 들어 있다. 이전 행 값 = LAG.","src":"핵심기출 · 2과목 90번","w":["LEAD는 다음 행 값","ROW_NUMBER는 순번","RANK는 순위",""],"kc":"2-90","tables":[{"name":"실행결과","cols":["EMPNO","HIREDATE","SAL","SAL_2"],"rows":[["7499","2018-02-20","1600","NULL"],["7521","2018-02-22","1250","1600"],["7844","2018-09-08","1500","1250"],["7654","2018-09-28","1250","1500"]],"after":true}]},{"id":1793,"c":"s36","d":2,"q":"GRANT와 REVOKE에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["어떤 사용자가 WITH GRANT OPTION과 함께 권한을 허가받았으면 그 사용자는 해당 권한을 WITH GRANT OPTION 유무와 관계없이 다른 사용자에게 허가할 수 있다.","PUBLIC을 사용하면 자신에게 허가된 권한을 모든 사용자들에게 허가할 수 있다.","REVOKE 문을 사용하여 권한을 취소하더라도 권한을 취소당한 사용자가 WITH GRANT OPTION을 통해서 다른 사용자에게 허가했던 권한들까지 연쇄적으로 모두 취소되는 것은 아니다.","REVOKE 문을 사용하여 권한을 취소할 때 그 권한을 허가한 사용자가 권한을 취소할 수 있다."],"a":2,"e":"REVOKE로 권한을 취소하면, 그 사용자가 WITH GRANT OPTION으로 남에게 줬던 권한까지 연쇄적으로 취소된다.","src":"핵심기출 · 2과목 91번","w":["WITH GRANT OPTION 받은 사용자는 다른 사용자에게 권한 부여 가능, 맞음","PUBLIC으로 모든 사용자에게 부여, 맞음","","권한을 준 사용자가 회수, 맞음"],"kc":"2-91"},{"id":1794,"c":"s36","d":1,"q":"B_User가 아래의 작업을 수행할 수 있도록 권한을 부여하는 DCL로 가장 적절한 것은?","code":["UPDATE A_User.TB_A","SET col1='AAA'","WHERE col2=3"],"o":["GRANT SELECT, UPDATE TO B_User;","REVOKE SELECT ON A_User.TB_A FROM B_User;","DENY UPDATE ON A_User.TB_A TO B_User;","GRANT SELECT, UPDATE ON A_User.TB_A TO B_User;"],"a":3,"e":"WHERE 조건으로 행을 찾으려면 SELECT, 값을 바꾸려면 UPDATE 권한이 필요하다. 문법은 GRANT 권한 ON 객체 TO 사용자.","src":"핵심기출 · 2과목 92번","w":["ON 대상 객체가 빠짐","REVOKE는 권한 회수","DENY는 SQL Server의 거부 명령, 권한 부여가 아님",""],"kc":"2-92"},{"id":1795,"c":"s35","d":1,"q":"아래는 EMPLOYEE 스키마뿐만 아니라 연관된 객체들도 모두 삭제하는 SQL 명령어이다. 빈칸 ㉠에 들어갈 내용으로 가장 적절한 것은?","code":["DROP SCHEMA EMPLOYEE ( ㉠ );"],"o":["NULL","NOT NULL","CASCADE","RESTRICT"],"a":2,"e":"CASCADE는 스키마 안의 연관 객체까지 모두 삭제. RESTRICT는 스키마가 비어 있을 때만 삭제된다.","src":"핵심기출 · 2과목 93번","w":["DROP 옵션이 아님","DROP 옵션이 아님","","RESTRICT는 비어 있을 때만 삭제"],"kc":"2-93"},{"id":1796,"c":"s36","d":3,"q":"사용자 Lee가 테이블 R을 생성한 후 아래의 SQL을 실행하였다. 그 이후에 실행 가능한 SQL로 가장 적절한 것은? (단, A, B의 데이터 타입은 정수형이다.)","code":["Lee: GRANT SELECT, INSERT, DELETE ON R TO Kim WITH","     GRANT OPTION;","Kim: GRANT SELECT, INSERT, DELETE ON R TO Park;","Lee: REVOKE DELETE ON R FROM Kim CASCADE;","Lee: REVOKE INSERT ON R FROM Kim CASCADE;"],"o":["Park: SELECT * FROM R WHERE A = 400;","Park: INSERT INTO R VALUES(400, 600);","Park: DELETE FROM R WHERE B = 800;","Kim: INSERT INTO R VALUES(500, 600);"],"a":0,"e":"DELETE, INSERT 권한은 CASCADE로 Kim과 Park 모두에게서 회수됐다. 남은 건 SELECT뿐이라 Park의 SELECT만 실행된다.","src":"핵심기출 · 2과목 94번","w":["","INSERT 권한이 회수됨","DELETE 권한이 회수됨","Kim의 INSERT 권한도 회수됨"],"kc":"2-94"},{"id":1797,"c":"s24","d":4,"q":"아래 SQL과 동일한 결과를 출력하는 SQL로 가장 적절한 것은?","code":["SELECT X.keyb, Y.col1, SUM(X.col1) AS sumcol1","FROM   Table_B X, Table_A Y","WHERE  X.keya = Y.keya","GROUP BY CUBE(X.keyb, Y.col1)","ORDER BY keyb, col1;"],"o":["SELECT X.keyb, Y.col1, SUM(X.col1) AS sumcol1\nFROM Table_B X, Table_A Y\nWHERE X.keya = Y.keya\nGROUP BY ROLLUP(X.keyb, Y.col1)\nORDER BY keyb, col1;","SELECT X.keyb, Y.col1, SUM(X.col1) AS sumcol1\nFROM Table_B X, Table_A Y\nWHERE X.keya = Y.keya\nGROUP BY GROUPING SETS((X.keyb, Y.col1), (X.keyb),\n         (Y.col1), ())\nORDER BY keyb, col1;","SELECT X.keyb, MAX(Y.col1) AS col1, SUM(X.col1) AS sumcol1\nFROM Table_B X, Table_A Y\nWHERE X.keya = Y.keya\nGROUP BY X.keyb\nUNION ALL\nSELECT MAX(X.keyb) AS keyb, Y.col1, SUM(X.col1) AS sumcol1\nFROM Table_B X, Table_A Y\nWHERE X.keya = Y.keya\nGROUP BY Y.col1\nORDER BY keyb, col1;","SELECT X.keyb, MAX(Y.col1) AS col1, SUM(X.col1) AS sumcol1\nFROM Table_B X, Table_A Y\nWHERE X.keya = Y.keya\nGROUP BY X.keyb\nUNION ALL\nSELECT MAX(X.keyb) AS keyb, Y.col1, SUM(X.col1) AS sumcol1\nFROM Table_B X, Table_A Y\nWHERE X.keya = Y.keya\nGROUP BY Y.col1\nUNION ALL\nSELECT X.keyb, Y.col1, SUM(X.col1) AS sumcol1\nFROM Table_B X, Table_A Y\nWHERE X.keya = Y.keya\nGROUP BY X.keyb, Y.col1\nORDER BY keyb, col1;"],"a":1,"e":"CUBE(keyb, col1) = GROUPING SETS((keyb, col1), (keyb), (col1), ()). ④는 UNION ALL 세 덩어리로 같은 그룹을 만들었지만 전체 합계(())가 빠져 있다.","src":"핵심기출 · 2과목 95번","w":["ROLLUP은 col1별 소계가 없음","","keyb별, col1별만 있고 (keyb, col1)과 전체 합계가 없음","전체 합계 행이 없음"],"kc":"2-95"},{"id":1798,"c":"s23","d":1,"q":"집합 연산자인 INTERSECT에 대한 설명으로 가장 적절한 것은?","code":null,"o":["여러 개의 SQL문의 결과에 대한 합집합으로, 중복된 행은 하나의 행으로 출력한다.","여러 개의 SQL문의 결과에 대한 합집합으로, 중복된 행도 그대로 결과로 출력한다.","여러 개의 SQL문의 결과에 대한 교집합으로, 중복된 행은 하나의 행으로 출력한다.","SQL문 결과간의 차집합으로, 중복된 행은 하나의 행으로 출력한다."],"a":2,"e":"INTERSECT는 교집합, 중복 행은 하나로 출력한다.","src":"핵심기출 · 2과목 96번","w":["UNION 설명","UNION ALL 설명","","MINUS/EXCEPT 설명"],"kc":"2-96"},{"id":1799,"c":"s27","d":3,"q":"아래를 참고할 때 SQL의 빈칸 ㉠에 들어갈 내용으로 가장 적절한 것은?","code":["SELECT a.empno","     , a.ename","     , a.job","     , LAG(a.sal, ( ㉠ )) OVER (PARTITION BY a.job","  ORDER BY a.ename) AS prev_sal","FROM emp a;"],"o":["0","1","2","4"],"a":2,"e":"JONES의 PREV_SAL이 2850(BLAKE)이다. JOB별 이름순으로 BLAKE, CLARK, JONES니까 2칸 앞 값. LAG(sal, 2). 두 번째 인자를 생략하면 1이라 반드시 2를 써야 한다.","src":"핵심기출 · 2과목 97번","w":["0이면 자기 자신 값","1이면 바로 앞 행(JONES는 CLARK 2450)","","4칸 앞이면 MANAGER 파티션에선 전부 NULL"],"kc":"2-97","tables":[{"name":"emp","cols":["EMPNO","ENAME","JOB","SAL"],"rows":[["7698","BLAKE","MANAGER","2850"],["7782","CLARK","MANAGER","2450"],["7566","JONES","MANAGER","2975"],["7499","ALLEN","SALESMAN","1600"],["7654","MARTIN","SALESMAN","1250"],["7844","TURNER","SALESMAN","1500"],["7521","WARD","SALESMAN","1250"]]},{"name":"실행 결과","cols":["EMPNO","ENAME","JOB","PREV_SAL"],"rows":[["7698","BLAKE","MANAGER","NULL"],["7782","CLARK","MANAGER","NULL"],["7566","JONES","MANAGER","2850"],["7499","ALLEN","SALESMAN","NULL"],["7654","MARTIN","SALESMAN","NULL"],["7844","TURNER","SALESMAN","1600"],["7521","WARD","SALESMAN","1250"]],"after":true}]},{"id":1800,"c":"s25","d":2,"q":"아래를 참고할 때, SQL의 빈칸 ㉠에 들어갈 내용으로 가장 적절한 것은?","code":["SELECT COL1","     , COL2","     , ( ㉠ ) () OVER (ORDER BY COL2) COL3","FROM TBL;"],"o":["DENSE_RANK","RANK","ROW_NUMBER","PERCENT_RANK"],"a":1,"e":"COL2 300이 세 명 공동 4위, 다음이 7위다. 동순위만큼 순위를 건너뛰니 RANK.","src":"핵심기출 · 2과목 98번","w":["DENSE_RANK면 300 다음 400이 5위","","ROW_NUMBER면 동순위 없음(1~8)","PERCENT_RANK는 0~1 사이 비율"],"kc":"2-98","tables":[{"name":"TBL","cols":["COL1","COL2"],"rows":[["1","100"],["2","100"],["3","200"],["4","300"],["5","300"],["6","300"],["7","400"],["8","500"]]},{"name":"실행 결과","cols":["COL1","COL2","COL3"],"rows":[["1","100","1"],["2","100","1"],["3","200","3"],["4","300","4"],["6","300","4"],["5","300","4"],["7","400","7"],["8","500","8"]],"after":true}]},{"id":1801,"c":"s35","d":3,"q":"아래 데이터 모델과 같은 테이블 및 PK 제약조건을 생성하는 DDL 문장으로 가장 적절한 것은? (단, DBMS는 오라클로 가정)","code":null,"o":["CREATE TABLE PRODUCT\n( PROD_ID VARCHAR2(10) NOT NULL\n ,PROD_NM VARCHAR2(100) NOT NULL\n ,REG_DT DATE NOT NULL\n ,REGR_NO NUMBER(10) NULL );\nALTER TABLE PRODUCT ADD PRIMARY KEY PRODUCT_PK\nON (PROD_ID);","CREATE TABLE PRODUCT\n( PROD_ID VARCHAR2(10)\n ,PROD_NM VARCHAR2(100)\n ,REG_DT DATE\n ,REGR_NO NUMBER(10) );\nALTER TABLE PRODUCT ADD CONSTRAINT PRODUCT_PK\n    PRIMARY KEY (PROD_ID);","CREATE TABLE PRODUCT\n( PROD_ID VARCHAR2(10) NOT NULL\n ,PROD_NM VARCHAR2(100) NOT NULL\n ,REG_DT DATE NOT NULL\n ,REGR_NO NUMBER(10) NULL\n ,ADD CONSTRAINT PRIMARY KEY (PROD_ID) );","CREATE TABLE PRODUCT\n( PROD_ID VARCHAR2(10) NOT NULL\n ,PROD_NM VARCHAR2(100) NOT NULL\n ,REG_DT DATE NOT NULL\n ,REGR_NO NUMBER(10)\n ,CONSTRAINT PRODUCT_PK PRIMARY KEY (PROD_ID) );"],"a":3,"e":"④는 CREATE TABLE 안에서 CONSTRAINT PRODUCT_PK PRIMARY KEY (PROD_ID)로 PK를 제대로 지정했고, NOT NULL도 모델과 똑같다.","src":"핵심기출 · 2과목 99번","w":["ADD PRIMARY KEY PRODUCT_PK ON (...)은 문법 오류. ADD CONSTRAINT 이름 PRIMARY KEY (컬럼)","PROD_NM, REG_DT의 NOT NULL을 빼먹음","CREATE TABLE 괄호 안에서 ADD CONSTRAINT는 문법 오류",""],"kc":"2-99","box":["[IE 표기법] PRODUCT","  PROD_ID: VARCHAR2(10) NOT NULL  (식별자)","  PROD_NM: VARCHAR2(100) NOT NULL","  REG_DT: DATE NOT NULL","  REGR_NO: NUMBER(10) NULL","[Barker 표기법] PRODUCT()","  # PROD_ID VARCHAR2(10)","  * PROD_NM VARCHAR2(100)","  * REG_DT DATE","  o REGR_NO NUMBER(10)"]},{"id":1802,"c":"s35","d":3,"q":"데이터가 들어있지 않은 왼쪽의 기관분류 테이블 (가)를 (나)와 같이 변경하고자 할 때 가장 적절한 SQL은? (단, DBMS는 SQL Server로 가정)","code":null,"o":["ALTER TABLE 기관분류 ALTER COLUMN (분류명 VARCHAR(30), 등록일자 DATE NOT NULL);","ALTER TABLE 기관분류 ALTER COLUMN (분류명 VARCHAR(30) NOT NULL, 등록일자 DATE NOT NULL);","ALTER TABLE 기관분류 ALTER COLUMN 분류명 VARCHAR(30);\nALTER TABLE 기관분류 ALTER COLUMN 등록일자 DATE NOT NULL;","ALTER TABLE 기관분류 ALTER COLUMN 분류명 VARCHAR(30) NOT NULL;\nALTER TABLE 기관분류 ALTER COLUMN 등록일자 DATE NOT NULL;"],"a":3,"e":"SQL Server는 ALTER COLUMN으로 한 번에 컬럼 하나만, 괄호 없이 수정한다. 또 NOT NULL을 다시 써 주지 않으면 NULL 허용으로 바뀐다. 두 문장으로 나눠 둘 다 NOT NULL을 명시한 ④가 정답.","src":"핵심기출 · 2과목 100번","w":["여러 컬럼 동시 수정 불가, 괄호 사용 불가","여러 컬럼 동시 수정 불가, 괄호 사용 불가","분류명에 NOT NULL을 안 써서 NULL 허용으로 바뀜",""],"kc":"2-100","box":["(가) 기관분류","  분류ID: VARCHAR(10) NOT NULL  (식별자)","  분류명: VARCHAR(10) NOT NULL","  등록일자: VARCHAR(10) NULL","        ⇨","(나) 기관분류","  분류ID: VARCHAR(10) NOT NULL  (식별자)","  분류명: VARCHAR(30) NOT NULL","  등록일자: DATE NOT NULL"]},{"id":1803,"c":"c13","d":2,"q":"아래와 같은 상황에서 문제가 발생한 트랜잭션의 특성으로 가장 적절한 것은?","code":null,"o":["원자성(Atomicity)","일관성(Consistency)","고립성(Isolation)","영속성(Durability)"],"a":2,"e":"TX1이 바꾼 값(200)을 커밋하기 전에 TX2가 같은 행을 300으로 덮어썼다. 진행 중인 트랜잭션이 다른 트랜잭션의 영향을 받은 것이라 고립성(Isolation) 문제.","src":"핵심기출 · 2과목 101번","w":["원자성은 전부 수행 or 전부 미수행 문제","일관성은 DB 규칙(무결성) 위배 문제","","영속성은 커밋한 결과가 영구 보존되는지 문제"],"kc":"2-101","tables":[{"name":"TableA","cols":["COL1","COL2"],"rows":[["A","100"],["B","200"]]},{"name":"트랜잭션","cols":["시간","TX1","TX2"],"rows":[["t1","update TableA set col2 = 200 where col1 = 'A';",""],["t2","","update TableA set col2 = 300 where col1 = 'A';"],["t3","","commit;"],["t4","commit;",""]]},{"name":"트랜잭션 수행결과","cols":["COL1","COL2"],"rows":[["A","300"],["B","200"]]}]},{"id":1804,"c":"s35","d":3,"q":"아래를 참고할 때 DELETE FROM T; 를 수행한 후에 테이블 R에 남아있는 데이터로 가장 적절한 것은?","code":["CREATE TABLE T","(C INTEGER PRIMARY KEY,","  D INTEGER);","","CREATE TABLE S","(B INTEGER PRIMARY KEY,","  C INTEGER REFERENCES T(C) ON DELETE CASCADE);","","CREATE TABLE R","(A INTEGER PRIMARY KEY,","  B INTEGER REFERENCES S(B) ON DELETE SET NULL);"],"o":["(1, NULL)과 (2, 2)","(1, NULL)과 (2, NULL)","(2, 2)","(1, 1)"],"a":1,"e":"T를 지우면 S는 ON DELETE CASCADE라 C=1인 두 행 모두 삭제. R은 S를 참조하는데 ON DELETE SET NULL이라 B가 NULL로 바뀐다. 남는 건 (1, NULL), (2, NULL).","src":"핵심기출 · 2과목 102번","w":["S의 B=2도 C=1이라 같이 삭제됨","","R 행 자체는 삭제되지 않음(SET NULL)","R의 B가 NULL로 바뀌어야 함"],"kc":"2-102","tables":[{"name":"T","cols":["C","D"],"rows":[["1","1"],["2","1"]],"after":true},{"name":"S","cols":["B","C"],"rows":[["1","1"],["2","1"]],"after":true},{"name":"R","cols":["A","B"],"rows":[["1","1"],["2","2"]],"after":true}]},{"id":1805,"c":"s34","d":2,"q":"아래 SQL의 실행 결과로 가장 적절한 것은?","code":["begin transaction;","save transaction sp1;","delete from Table_A where keya = 2;","save transaction sp2;","delete from Table_A where col1 = 'A';","delete from Table_A where col2 = 3;","rollback transaction sp2;","commit;","select count(*) as cnt from Table_A;"],"o":["2","3","4","5"],"a":2,"e":"sp2 이후의 두 DELETE는 ROLLBACK TRANSACTION sp2로 취소되고, sp2 이전의 keya=2 삭제만 남은 채 커밋된다. 5-1 = 4건.","src":"핵심기출 · 2과목 103번","w":["2건이 남는 경우는 없음(sp2 이후 삭제까지 반영되면 0건)","keya=2 외에 한 건을 더 지운 셈","","sp1까지 롤백해야 5건"],"kc":"2-103","tables":[{"name":"Table_A","cols":["keya","col1","col2"],"rows":[["1","A","2"],["2","A","2"],["3","B","3"],["4","B","3"],["5","C","3"]]}]},{"id":1806,"c":"s03","d":1,"q":"SQL에서 중복 행을 제거하는 데 사용되는 키워드로 가장 적절한 것은?","code":null,"o":["UNIQUE","SORT","ORDER BY","DISTINCT"],"a":3,"e":"SELECT 결과의 중복 행 제거 = DISTINCT.","src":"핵심기출 · 2과목 104번","w":["UNIQUE는 제약조건 키워드","SORT는 SQL 키워드가 아님","ORDER BY는 정렬",""],"kc":"2-104"},{"id":1807,"c":"s35","d":2,"q":"테이블 생성 시 주의해야 할 사항으로 가장 적절한 것은?","code":null,"o":["테이블명은 객체를 의미할 수 있는 적절한 이름을 사용하고 가능한 복수형을 권고한다.","한 테이블 내에서는 칼럼명을 중복되게 지정할 수 있다.","칼럼 뒤에 데이터 유형은 꼭 지정되어야 한다.","벤더에서 사전에 정의한 예약어(Reserved Word)도 쓸 수 있다."],"a":2,"e":"칼럼 뒤에는 데이터 유형을 반드시 지정해야 한다.","src":"핵심기출 · 2과목 105번","w":["복수형이 아니라 단수형 권고","한 테이블 안에서 칼럼명 중복 불가","","예약어는 쓸 수 없음"],"kc":"2-105"},{"id":1808,"c":"s33","d":3,"q":"아래 SQL을 수행했을 때 T1 테이블의 최종 건수로 가장 적절한 것은?","code":["MERGE","  INTO t1 a","  USING T2 B","    ON (B.EMPNO = A.EMPNO)","  WHEN MATCHED THEN","       UPDATE SET A.SAL = B.SAL - 500","        WHERE A.JOB = 'CLERK'","       DELETE","        WHERE A.SAL < 2000","  WHEN NOT MATCHED THEN","       INSERT (A.EMPNO, A.ENAME, A.JOB)","       VALUES (B.EMPNO, B.ENAME, B.JOB)","        WHERE B.JOB = 'CLERK';"],"o":["1","2","3","4"],"a":1,"e":"7369(CLERK)는 매칭 → SAL 300으로 UPDATE 후 DELETE WHERE SAL<2000에 걸려 삭제. 7566(MANAGER)은 JOB='CLERK' 조건에 안 걸려 UPDATE 안 됨 → DELETE도 대상 아님(남음). 매칭 안 된 것 중 CLERK인 7876 ADAMS만 INSERT. 결과 JONES, ADAMS 2건.","src":"핵심기출 · 2과목 106번","w":["ADAMS INSERT를 빼먹은 결과","","DELETE를 무시해 SMITH가 남았다고 본 결과","INSERT의 CLERK 조건을 무시해 SCOTT·ADAMS·FORD가 모두 들어간 경우(JONES 포함 4건)"],"kc":"2-106","tables":[{"name":"T1","cols":["EMPNO","ENAME","JOB","SAL"],"rows":[["7369","SMITH","CLERK","800"],["7566","JONES","MANAGER","2975"]]},{"name":"T2","cols":["EMPNO","ENAME","JOB","SAL"],"rows":[["7369","SMITH","CLERK","800"],["7566","JONES","MANAGER","2975"],["7788","SCOTT","ANALYST","3000"],["7876","ADAMS","CLERK","1100"],["7902","FORD","ANALYST","3000"]]}]},{"id":1809,"c":"s10","d":1,"q":"아래와 같이 테이블을 생성한 후 데이터를 삽입했을 때, (가)와 (나)의 실행 결과에 대한 설명으로 가장 적절한 것은?","code":["CREATE TABLE 학생 (학번 CHAR (8) PRIMARY KEY,","                  장학금 INTEGER) ;","","(가) SELECT COUNT(*) FROM 학생","(나) SELECT COUNT(학번) FROM 학생"],"o":["(가), (나) 문장의 실행 결과는 다를 수 있으며, 그 이유는 장학금 속성에 NULL이 존재할 수 있기 때문이다.","(가), (나) 문장의 실행 결과는 항상 다르다.","(가), (나) 문장의 실행 결과는 항상 같다.","(가), (나) 문장의 실행 결과는 다를 수 있으며, 그 이유는 학번 속성에 NULL이 존재할 수 있기 때문이다."],"a":2,"e":"학번은 PK라 NULL이 들어갈 수 없다. COUNT(*)와 COUNT(학번)은 항상 같다.","src":"핵심기출 · 2과목 107번","w":["COUNT(학번)은 장학금과 무관","항상 다르지 않음","","PK에는 NULL이 없음"],"kc":"2-107"},{"id":1810,"c":"s35","d":2,"q":"외래키에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["테이블 생성 시 설정할 수 있다.","외래키 값은 NULL을 가질 수 없다.","한 테이블에 하나 이상 생성할 수 있다.","외래키 값은 참조 무결성 제약을 받을 수 있다."],"a":1,"e":"외래키 값은 NULL을 가질 수 있다(관계가 선택일 때).","src":"핵심기출 · 2과목 108번","w":["CREATE TABLE 시 설정 가능, 맞음","","한 테이블에 여러 개 가능, 맞음","참조 무결성 제약을 받음, 맞음"],"kc":"2-108"},{"id":1811,"c":"c09","d":1,"q":"아래 SQL에서 RepName 속성이 가지는 키 특성으로 가장 적절한 것은?","code":["CREATE TABLE SALESREP (","SalesRepNo      int         NOT NULL,","RepName char(35)  NOT NULL,","HireDate date     NOT NULL,","","CONSTRAINT SalesRepPK    PRIMARY KEY (SalesRepNo),","CONSTRAINT SalesRepAK1   UNIQUE (RepName)",");"],"o":["기본키(Primary Key)","외래키(Foreign Key)","후보키(Candidate Key)","대리키(Surrogate Key)"],"a":2,"e":"RepName은 NOT NULL + UNIQUE로 유일하게 식별할 수 있지만 PK로는 선택되지 않았다 → 후보키(그중 PK가 아닌 것이라 대체키).","src":"핵심기출 · 2과목 109번","w":["PK는 SalesRepNo","외래키 제약 없음","","대리키는 인위적으로 만든 키"],"kc":"2-109"},{"id":1812,"c":"s35","d":1,"q":"아래 테이블에서 COMM 칼럼을 삭제하고자 할 때, SQL의 빈칸 ㉠, ㉡ 안에 들어갈 내용으로 가장 적절한 것은?","code":["( ㉠ ) TABLE EMP ( ㉡ ) COMM;"],"o":["ALTER, DROP COLUMN","ALTER, REMOVE COLUMN","MODIFY, DROP COLUMN","MODIFY, REMOVE COLUMN"],"a":0,"e":"칼럼 삭제: ALTER TABLE 테이블명 DROP COLUMN 칼럼명.","src":"핵심기출 · 2과목 110번","w":["","REMOVE COLUMN 문법 없음","MODIFY TABLE 문법 없음","둘 다 틀림"],"kc":"2-110","tables":[{"name":"EMP","cols":["MGR","ENAME","SAL","COMM"],"rows":[["7566","FORD","3000","NULL"],["7566","SCOTT","3000","NULL"],["7698","JAMES","950","NULL"],["7698","ALLEN","1600","NULL"],["7698","WARD","1250","NULL"],["7698","TURNER","1500","NULL"],["7698","MARTIN","1250","NULL"],["7782","MILLER","1300","NULL"],["7788","ADAMS","1100","NULL"],["7839","BLAKE","2850","NULL"],["7839","JONES","2980","NULL"],["7839","CLARK","2450","NULL"],["7902","SMITH","800","NULL"],["NULL","KING","5000","NULL"]]}]},{"id":1813,"c":"s10","d":2,"q":"아래 SQL의 실행 결과로 가장 적절한 것은?","code":["SELECT COUNT(COL1) AS CNT1, COUNT(COL2) AS CNT2","  FROM (","        SELECT DISTINCT COL1, COL2","        FROM T1","       );"],"o":["4, 2","2, 2","1, 2","4, 4"],"a":1,"e":"DISTINCT는 선택한 컬럼 조합 전체가 같을 때만 중복으로 본다. 결과는 (1, AAAA), (1, BBBB) 2행 → COUNT(COL1)=2, COUNT(COL2)=2.","src":"핵심기출 · 2과목 111번","w":["DISTINCT 전 원본 건수로 센 값","","COL1 값 종류(1개)로 착각","원본 4건을 그대로 센 값"],"kc":"2-111","tables":[{"name":"T1","cols":["COL1","COL2"],"rows":[["1","AAAA"],["1","AAAA"],["1","AAAA"],["1","BBBB"]]}]},{"id":1814,"c":"s35","d":1,"q":"SQL에서 사용되는 표준 데이터 타입으로 가장 적절하지 않은 것은? (단, DBMS는 오라클로 가정)","code":null,"o":["Text","Char","Varchar2","Number"],"a":0,"e":"오라클 문자형은 CHAR, VARCHAR2. Text는 오라클 표준 타입이 아니다.","src":"핵심기출 · 2과목 112번","w":["","CHAR는 고정 길이 문자","VARCHAR2는 가변 길이 문자","NUMBER는 숫자"],"kc":"2-112"},{"id":1815,"c":"s35","d":2,"q":"관계형 데이터베이스에서 자식 테이블의 FK 데이터 생성시 부모 테이블에 PK가 없는 경우, 자식 테이블 데이터 입력을 허용하지 않는 참조동작(Referential Action)은?","code":null,"o":["CASCADE","RESTRICT","AUTOMATIC","DEPENDENT"],"a":3,"e":"입력 참조동작(Insert Action) 중 Dependent는 부모 테이블에 PK가 있을 때만 자식 입력을 허용한다.","src":"핵심기출 · 2과목 113번","w":["Cascade는 삭제/수정 액션(부모 삭제 시 자식도 삭제)","Restrict도 삭제/수정 액션(자식 있으면 부모 삭제 불가)","Automatic은 부모 PK가 없으면 부모 PK를 만든 뒤 자식 입력",""],"kc":"2-113"},{"id":1816,"c":"s33","d":3,"q":"아래를 참고할 때 오류가 발생하지 않는 SQL은?","code":["CREATE TABLE TBL","(","    ID NUMBER PRIMARY KEY,","    AMT NUMBER NOT NULL,","    DEGREE VARCHAR2(1)",");","","(가) INSERT INTO TBL VALUES(1, 100);","(나) INSERT INTO TBL(ID, AMT, DEGREE) VALUES(2, 200, 'AB');","(다) INSERT INTO TBL(ID, DEGREE) VALUES(4, 'X');","(라) INSERT INTO TBL(ID, AMT) VALUES(3, 300);","(마) INSERT INTO TBL VALUES(5, 500, NULL);"],"o":["(가), (나)","(나), (다)","(다), (라)","(라), (마)"],"a":3,"e":"(라)는 NOT NULL인 AMT까지 넣었고, (마)는 3개 컬럼 모두 값(DEGREE NULL 허용)을 넣어 오류가 없다.","src":"핵심기출 · 2과목 114번","w":["(가) 컬럼 생략 시 모든 칼럼 값을 줘야 하는데 2개뿐, (나) DEGREE VARCHAR2(1)에 'AB' 초과","(다) NOT NULL인 AMT를 안 넣음","(다) 오류",""],"kc":"2-114"},{"id":1817,"c":"s33","d":2,"q":"아래를 참고할 때 오류가 발생하는 SQL은?","code":null,"o":["INSERT INTO BOARD VALUES (1, 'Q&A', 'Y', SYSDATE, 'Q&A 게시판');","INSERT INTO BOARD (BOARD_ID, BOARD_NM, USE_YN, BOARD_DESC) VALUES ('100', 'FAQ', 'Y', 'FAQ 게시판');","UPDATE BOARD SET USE_YN = 'N' WHERE BOARD_ID = '1';","UPDATE BOARD SET BOARD_ID = 200 WHERE BOARD_ID = '100';"],"a":1,"e":"REG_DATE는 NOT NULL인데 ②의 INSERT는 이 컬럼을 빼먹어 NULL이 들어가므로 오류.","src":"핵심기출 · 2과목 115번","w":["숫자 1은 VARCHAR2로 자동 변환되고 모든 컬럼에 값 입력, 정상","","정상 UPDATE","200이 VARCHAR2로 변환돼 정상 UPDATE"],"kc":"2-115","box":["BOARD","  BOARD_ID: VARCHAR2(10) NOT NULL  (식별자)","  BOARD_NM: VARCHAR2(50) NOT NULL","  USE_YN: VARCHAR2(1) NOT NULL","  REG_DATE: DATE NOT NULL","  BOARD_DESC: VARCHAR2(100) NULL"]},{"id":1818,"c":"s33","d":2,"q":"아래를 참고할 때 오류가 발생하는 INSERT문으로 가장 적절한 것은?","code":["CREATE TABLE 주문 (","    주문번호 NUMBER PRIMARY KEY,","    주문일자 DATE NOT NULL,","    회원번호 NUMBER,","    주문상태코드 VARCHAR2(3) DEFAULT '000'",");"],"o":["INSERT INTO 주문(주문번호, 주문일자, 회원번호, 주문상태코드)\nVALUES(1, SYSDATE, 1900123, '002');","INSERT INTO 주문(주문번호, 주문일자, 회원번호, 주문상태코드)\nVALUES(2, '20190301', 1900124, '001');","INSERT INTO 주문(주문번호, 주문일자, 회원번호, 주문상태코드)\nVALUES(3, SYSDATE-1, 1900125, '001');","INSERT INTO 주문(주문번호, 주문일자, 회원번호, 주문상태코드)\nVALUES(4, 20190302, 1900126, '001');"],"a":3,"e":"DATE 컬럼에 숫자 20190302는 넣을 수 없다. 문자 '20190301'은 기본 날짜 포맷에 따라 변환될 수 있지만 숫자는 바로 에러.","src":"핵심기출 · 2과목 116번","w":["SYSDATE, 정상","문자열 → DATE 묵시적 변환(NLS 포맷 일치 시)","SYSDATE-1, 정상",""],"kc":"2-116"},{"id":1819,"c":"s08","d":1,"q":"아래의 산술 연산자를 우선순위가 높은 순으로 나열한 것은?","code":null,"o":["*, /, +, -, ()","+, -, *, /, ()","(), *, /, +, -","(), +, -, *, /"],"a":2,"e":"산술 연산자 우선순위는 수학과 같다: () → *, / → +, -.","src":"핵심기출 · 2과목 117번","w":["괄호가 가장 먼저","덧셈이 곱셈보다 먼저일 수 없음","","+, -가 *, /보다 먼저일 수 없음"],"kc":"2-117","box":["*, +, -, (), /"]},{"id":1820,"c":"s35","d":2,"q":"아래와 같은 테이블에서 Department의 did가 '1'인 행이 삭제될 때, Employee의 did가 '1'인 행도 같이 삭제하도록 하는 방법으로 가장 적절한 것은? (단, Employee의 did는 Department에서 가져온 외래키이다.)","code":null,"o":["Employee 릴레이션을 생성할 때 FOREIGN KEY(did) REFERENCES Department(did) ON DELETE RESTRICT 명령어를 추가한다.","Department 릴레이션을 생성할 때 FOREIGN KEY(did) REFERENCES Employee(did) ON DELETE CASCADE 명령어를 추가한다.","Employee 릴레이션을 생성할 때 FOREIGN KEY(did) REFERENCES Department(did) ON DELETE CASCADE 명령어를 추가한다.","Department 릴레이션을 생성할 때 FOREIGN KEY(did) REFERENCES Employee(did) ON DELETE RESTRICT 명령어를 추가한다."],"a":2,"e":"자식(Employee) 쪽 FK에 ON DELETE CASCADE를 걸면 부모 Department 행이 삭제될 때 연결된 Employee 행도 같이 삭제된다.","src":"핵심기출 · 2과목 118번","w":["RESTRICT는 자식이 있으면 부모 삭제를 막음","FK는 자식 테이블(Employee)에 걸어야 함","","방향도 틀리고 RESTRICT라 삭제도 막힘"],"kc":"2-118","box":["Employee(__eid__, ename, did)","Department(__did__, dname, budget)"]},{"id":1821,"c":"s35","d":2,"q":"DELETE 와 TRUNCATE, DROP 명령어에 대해 비교한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["특정 테이블에 대하여 WHERE 조건절이 없는 DELETE 명령을 수행하면 DROP TABLE 명령을 수행했을 때와 똑같은 결과를 얻을 수 있다.","DROP 명령어는 테이블 정의 자체를 삭제하고, TRUNCATE 명령어는 테이블을 초기상태로 만든다.","TRUNCATE 명령어는 UNDO를 위한 데이터를 생성하지 않기 때문에 동일 데이터량 삭제 시 DELETE보다 빠르다.","DROP과 TRUNCATE는 Auto Commit되고, DELETE는 사용자 Commit으로 수행된다."],"a":0,"e":"WHERE 없는 DELETE는 데이터만 지우고 테이블 구조와 저장공간은 남는다. DROP TABLE은 테이블 정의 자체를 없애므로 결과가 다르다.","src":"핵심기출 · 2과목 119번","w":["","DROP은 정의 삭제, TRUNCATE는 초기 상태로, 맞음","TRUNCATE는 UNDO를 안 남겨 DELETE보다 빠름, 맞음","DROP·TRUNCATE는 Auto Commit, DELETE는 사용자 Commit, 맞음"],"kc":"2-119"},{"id":1822,"c":"c13","d":2,"q":"데이터베이스 트랜잭션에 대한 설명으로 가장 적절하지 않은 것은?","code":null,"o":["원자성(Atomicity) : 트랜잭션에서 정의된 연산들은 모두 성공적으로 실행되든지 아니면 전혀 실행되지 않은 상태로 남아 있어야 한다.","일관성(Consistency) : 트랜잭션이 실행 되기 전의 데이터베이스 내용이 잘못 되어 있지 않다면 트랜잭션이 실행된 이후에도 데이터베이스의 내용에 잘못이 있으면 안 된다.","고립성(Isolation) : 트랜잭션이 실행되는 도중에 다른 트랜잭션의 영향을 받아 잘못된 결과를 만들어서는 안 된다.","지속성(Durability) : 트랜잭션을 취소하더라도 트랜잭션이 갱신한 내용이 데이터베이스에 저장되어야 한다."],"a":3,"e":"지속성은 '성공적으로 수행된' 트랜잭션의 결과가 영구 저장되는 것. 취소한 트랜잭션의 내용까지 저장된다는 ④는 틀렸다.","src":"핵심기출 · 2과목 120번","w":["원자성 설명, 맞음","일관성 설명, 맞음","고립성 설명, 맞음",""],"kc":"2-120"},{"id":1823,"c":"s34","d":3,"q":"아래 SQL 실행 결과 테이블 A의 ID '001'에 해당하는 최종 VAL의 값이 오라클에서는 200, SQL Server에서는 100이 되었다고 할 때, 이에 대한 설명으로 가장 적절하지 않은 것은? (단, AUTO COMMIT은 FALSE로 설정되어 있다)","code":["UPDATE A SET VAL = 200 WHERE ID = '001';","CREATE TABLE B ( ID CHAR(3) PRIMARY KEY);","ROLLBACK;"],"o":["오라클에서는 CREATE TABLE 문장을 수행한 후, 묵시적으로 COMMIT이 수행되어 VAL 값은 200이 되었다.","SQL Server에서는 ROLLBACK 문장에 의해 UPDATE가 취소되어 VAL 값은 100이 되었다.","오라클에서는 CREATE TABLE 문장 수행에 의해 VAL 값은 200이 되었지만, ROLLBACK 실행으로 최종적으로 B 테이블은 생성되지 않았다.","SQL Server에서는 ROLLBACK 실행으로 인하여 UPDATE가 취소되었으며, 최종적으로 B 테이블은 생성되지 않았다."],"a":2,"e":"오라클은 DDL(CREATE TABLE)을 실행하면 내부적으로 커밋하고 트랜잭션을 끝낸다. 그래서 UPDATE도 확정되고 B 테이블도 생성된 상태로 남는다. ROLLBACK은 되돌릴 게 없다.","src":"핵심기출 · 2과목 121번","w":["오라클 DDL 자동 커밋, 맞음","SQL Server는 DDL 후 자동 커밋 안 함 → ROLLBACK으로 UPDATE 취소, 맞음","","SQL Server는 CREATE TABLE도 트랜잭션에 포함돼 같이 롤백, 맞음"],"kc":"2-121","tables":[{"name":"A","cols":["ID(PK)","VAL"],"rows":[["001","100"],["002","200"]]}]},{"id":1824,"c":"c13","d":1,"q":"데이터베이스의 논리적 연산 단위를 가리키는 용어로 가장 적절한 것은?","code":null,"o":["뷰(View)","트랜잭션(Transaction)","프로시저(Procedure)","트리거(Trigger)"],"a":1,"e":"DB의 논리적 연산 단위 = 트랜잭션.","src":"핵심기출 · 2과목 122번","w":["뷰는 가상 테이블","","프로시저는 저장된 SQL 블록","트리거는 이벤트 발생 시 자동 실행되는 블록"],"kc":"2-122"},{"id":1825,"c":"s34","d":3,"q":"아래 SQL의 실행 결과로 가장 적절한 것은?","code":["BEGIN TRANSACTION","INSERT INTO 품목(품목ID, 단가)","  VALUES('005',2000)","COMMIT","BEGIN TRANSACTION","DELETE 품목 WHERE 품목ID='002'","BEGIN TRANSACTION","UPDATE 품목 SET 단가=2000 WHERE","  단가=1000","ROLLBACK","SELECT COUNT(품목ID) FROM 품목","  WHERE 단가=2000"],"o":["0","2","3","4"],"a":2,"e":"005 INSERT는 커밋됐다. 그 뒤 BEGIN이 두 번 중첩된 상태에서 ROLLBACK을 하면 SQL Server는 커밋 안 된 트랜잭션을 전부 롤백 → 002 삭제도 취소. 단가 2000인 건 002, 004, 005 = 3.","src":"핵심기출 · 2과목 123번","w":["모든 행이 삭제·변경된 경우 없음","002 삭제는 남고 UPDATE만 롤백됐다고 본 값(004, 005)","","ROLLBACK을 무시한 값(001, 003, 004, 005)"],"kc":"2-123","tables":[{"name":"품목","cols":["품목ID","단가"],"rows":[["001","1000"],["002","2000"],["003","1000"],["004","2000"]]}]},{"id":1826,"c":"s34","d":2,"q":"아래를 참고할 때 상품ID '001'의 최종 상품명으로 가장 적절한 것은?","code":["BEGIN TRANSACTION;","SAVE TRANSACTION SP1;","UPDATE 상품 SET 상품명 = 'LCD-TV' WHERE 상품ID = '001';","SAVE TRANSACTION SP2;","UPDATE 상품 SET 상품명 = '평면-TV' WHERE 상품ID = '001';","ROLLBACK TRANSACTION SP2;","COMMIT;"],"o":["TV","LCD-TV","평면-TV","오류가 발생한다."],"a":1,"e":"ROLLBACK TRANSACTION SP2는 SP2 이후의 '평면-TV' UPDATE만 취소한다. 'LCD-TV' UPDATE는 남은 채 커밋.","src":"핵심기출 · 2과목 124번","w":["SP1로 롤백해야 TV","","SP2 이후 작업은 취소됨","SAVE TRANSACTION은 SQL Server 정상 문법"],"kc":"2-124","tables":[{"name":"상품","cols":["상품ID","상품명"],"rows":[["001","TV"]]}]},{"id":1827,"c":"s30","d":2,"q":"아래 테이블에서 승리건수가 높은 순으로 3위까지 출력하되 3위의 승리건수가 동일한 팀이 있다면 함께 출력하기 위한 SQL로 가장 적절한 것은?","code":null,"o":["SELECT TOP(3) 팀명, 승리건수\nFROM 팀별성적\nORDER BY 승리건수 DESC;","SELECT TOP(3) 팀명, 승리건수\nFROM 팀별성적;","SELECT 팀명, 승리건수\nFROM 팀별성적\nWHERE ROWNUM <= 3\nORDER BY 승리건수 DESC;","SELECT TOP(3) WITH TIES 팀명, 승리건수\nFROM 팀별성적\nORDER BY 승리건수 DESC;"],"a":3,"e":"3위와 같은 승리건수(D팀, F팀 100)를 같이 출력하려면 TOP(3) WITH TIES + ORDER BY.","src":"핵심기출 · 2과목 125번","w":["WITH TIES가 없어 공동 3위 중 한 팀만 나옴","ORDER BY도 없어 아무 3건","ROWNUM이 정렬 전에 붙어 임의 3건을 정렬",""],"kc":"2-125","tables":[{"name":"팀별성적","cols":["팀명","승리건수","패배건수"],"rows":[["A팀","120","80"],["B팀","20","180"],["C팀","10","190"],["D팀","100","100"],["E팀","110","90"],["F팀","100","100"],["G팀","70","130"]]}]},{"id":1828,"c":"s33","d":4,"q":"부서 테이블의 담당자 변경을 위해 부서임시 테이블에 입력된 데이터를 활용하여 주기적으로 부서 테이블을 실행 결과와 같이 반영하기 위한 SQL로 가장 적절한 것은? (단, 부서임시 테이블에서 변경일자를 기준으로 가장 최근에 변경된 데이터를 기준으로 부서 테이블에 반영되어야 한다.)","code":null,"o":["UPDATE 부서 A SET 담당자 = (SELECT C.부서코드\n       FROM (SELECT 부서코드, MAX(변경일자) AS 변경일자\n             FROM 부서임시\n             GROUP BY 부서코드) B, 부서임시 C\n       WHERE B.부서코드 = C.부서코드\n       AND B.변경일자 = C.변경일자\n       AND A.부서코드 = C.부서코드)","UPDATE 부서 A SET 담당자 = (SELECT C.부서코드\n       FROM (SELECT 부서코드, MAX(변경일자) AS 변경일자\n             FROM 부서임시\n             GROUP BY 부서코드) B, 부서임시 C\n       WHERE B.부서코드 = C.부서코드\n       AND B.변경일자 = C.변경일자\n       AND A.부서코드 = C.부서코드)\nWHERE EXISTS (SELECT 1 FROM 부서 X WHERE A.부서코드\n              = X.부서코드);","UPDATE 부서 A SET 담당자 = (SELECT B.담당자\n       FROM 부서임시 B\n       WHERE B.부서코드 = A.부서코드\n       AND B.변경일자 = (SELECT MAX(C.변경일자)\n                        FROM 부서임시 C\n                        WHERE\n                        C.부서코드 = B.부서코드))\nWHERE 부서코드 IN (SELECT 부서코드 FROM 부서임시);","UPDATE 부서 A SET 담당자 = (SELECT B.담당자\n       FROM 부서임시 B\n       WHERE B.부서코드 = A.부서코드\n       AND B.변경일자 = '2015.01.25');"],"a":2,"e":"③은 부서임시에 있는 부서(A007, A008)만 UPDATE 대상으로 잡고, 그 부서의 가장 최근 변경일자 담당자를 넣는다.","src":"핵심기출 · 2과목 126번","w":["WHERE 절이 없어 A007, A008 외 모든 부서 담당자가 NULL. 담당자에 부서코드를 넣는 것도 틀림","WHERE EXISTS가 부서 테이블 자체를 보니 사실상 전체 대상 → 나머지 NULL","","WHERE 절이 없어 나머지 부서 NULL, 날짜 하드코딩도 부적절"],"kc":"2-126","tables":[{"name":"부서","cols":["부서코드(PK)","부서명","상위부서코드","담당자"],"rows":[["A001","대표이사","NULL","김대표"],["A002","영업본부","A001","홍길동"],["A003","경영지원본부","A001","이순신"],["A004","마케팅본부","A001","강감찬"],["A005","해외영업팀","A002","이청용"],["A006","국내영업팀","A002","박지성"],["A007","총무팀","A003","차두리"],["A008","인사팀","A003","이민정"],["A009","해외마케팅팀","A004","이병헌"],["A010","국내마케팅팀","A004","차승원"]]},{"name":"부서임시","cols":["변경일자(PK)","부서코드(PK)","담당자"],"rows":[["2014.01.23","A007","이달자"],["2015.01.25","A007","홍경민"],["2015.01.25","A008","유재석"]]},{"name":"실행 결과","cols":["부서코드(PK)","부서명","상위부서코드","담당자"],"rows":[["A001","대표이사","NULL","김대표"],["A002","영업본부","A001","홍길동"],["A003","경영지원본부","A001","이순신"],["A004","마케팅본부","A001","강감찬"],["A005","해외영업팀","A002","이청용"],["A006","국내영업팀","A002","박지성"],["A007","총무팀","A003","홍경민"],["A008","인사팀","A003","유재석"],["A009","해외마케팅팀","A004","이병헌"],["A010","국내마케팅팀","A004","차승원"]]}]}]);
